window.__D("text/zohar/c029",{"p":[[9520012147,"<p>תָּאנָא, אָמַר רִבִּי יְהוּדָה, יוֹמָא חַד הֲווֹ אַזְלֵי (קמ\"ד ע\"א, צ\"א) רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא בְּאוֹרְחָא, עָרְעוּ בְּגוּשׁ חָלָב, וַהֲוָה חָרִיב, יָתְבוּ סָמִיךְ לְבֵי קִבְרֵי, וְרִבִּי יֵיסָא הֲוָה בִּידֵיהּ חַד חוּטְרָא (ס\"א קיטרא) דְסֵפֶר תּוֹרָה דְּאִקְרַע, עַד דְּיָתְבוּ אִתְרְגִישׁ חַד קִבְרָא קָמַיְיהוּ, וְצָוַוח וַוי וַוי, דְּהָא עָלְמָא בְּצַעֲרָא שְׁכִיחַ, הָא אוֹרַיְיתָא הָכָא דְּאִתְגַּלְיָיא, אוֹ חַיָּיָא אָתוּ לְחַיְּיכָא עֲלָן, וּלְכַסְּפָא בְּכִסּוּפָא עֲלָן בְּאוֹרָיְיתַיְיהוּ. אִזְדַּעֲזָעוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא.</p>\n<p>אָמַר רִבִּי חִזְקִיָּה מַאן אַתְּ. אָמַר לֵיהּ מֵיתָא אֲנָא, וְהָא אִתְּעַרְנָא לְגַבֵּי סֵפֶר תּוֹרָה. דְּזִמְנָא חֲדָא הֲוָה יָתִיב עָלְמָא בְּצַעֲרָא, וְאָתוּ חַיָּיָא הָכָא, לְאִתְּעָרָא לָן בְּסֵפֶר תּוֹרָה, וַאֲנָא וְחַבְרָאי אַקְדִּימְנָא לְגַבֵּי דְּמִיכֵי חֶבְרוֹן, וְכַד אִתְחַבָּרוּ בְּגַן עֵדֶן בְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא, אִשְׁתְּכַח קָמַיְיהוּ, דְּהַהוּא סֵפֶר תּוֹרָה דְּאַיְיתוּ לְקַמָּן אִינּוּן חַיַיָא, הֲוָה פָּסוּל וּמְשַׁקֵּר בִּשְׁמָא דְּמַלְכָּא, עַל דְּאִשְׁתְּכַח וָא\"ו יַתִּיר בְּהַהוּא קְרָא (ויקרא יא) דִּוְשֹׁסַעַת שֶׁסַע שְׁתֵּי פְרָסוֹת, וְאָמְרוּ דְּהוֹאִיל וְשַׁקְּרוּ בִּשְׁמָא דְּמַלְכָּא דְּלָא יְתוּבוּן לְגַבֵּיהוֹן, וְדָחוּ לִי וּלְחַבְרָאי בְּהַהִיא שַׁעֲתָא מִבֵּי מְתִיבְתָּא.</p>\n<p>עַד דְּחַד סָבָא דְּהֲוָה בֵּינַיְיהוּ, אָזַל וְאַיְיתֵי סַפְרָא דְּרַב הַמְנוּנָא סָבָא, וּכְדֵין אִתְּעַר (קהלת רבה פסוק שלח לחמך) רִבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן, דְּהֲוָה קָבִיר עִמָּנָא, וְאָזַל וּבָעָא בְּגַּן עֵדֶן עָלַיְיהוּ, וְאִתְסֵי עָלְמָא, כְּדֵין שָׁארוּ לָן, וּמִן הַהוּא יוֹמָא דִּסְלִיקוּ לֵיהּ לְרִבִּי אֶלְעָזָר מִבֵּי קִבְרָא דָּא, וְאִתְיְיהִיב לְגַבֵּי אֲבוּהָ, לֵית מַאן דְּאִתְּעַר לְמֵיקָם קַמַּיְיהוּ דִּדְמִיכֵי חֶבְרוֹן, דְּמִסְתַּפֵּינָא מִן הַהוּא יוֹמָא דְּדָחוּ לִי וְלַחֲבֵרַי. וְהַשְׁתָּא אֲתִיתּוּן לְגַבָּן, וְסֵפֶר תּוֹרָה גַּבֵּיכוֹן, אֲמֵינָא דְּהָא עָלְמָא בְּצַעֲרָא אִשְׁתְּכַח. וְעַל דָּא אִזְדַּעֲזַעַנָא, דַּאֲמֵינָא מַאן יַקְדִּים לְאוֹדָעָא לְאִינּוּן זַכָּאֵי קְשׁוֹט דְּמִיכֵי חֶבְרוֹן, אִשְׁתְּמִיט רִבִּי יֵיסָא בְּהַהוּא קִיטְרָא דְּסֵפֶר תּוֹרָה. אָמַר רִבִּי חִזְקִיָּה, חַס וְשָׁלוֹם לֵית עָלְמָא בְּצַעֲרָא, וַאֲנָן לָא אֲתֵינָן לְהַאי.</p>\n<p>קָמוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא וְאַזְלוּ. אַמְרֵי, וַדַּאי בְּשַׁעֲתָא דְּזַכָּאִין לָא אִשְׁתְּכָחוּ בְּעָלְמָא, עָלְמָא לָא מִתְקַיְּימָא אֶלָּא בְּגִינֵיהוֹן דְּמֵתַיָּיא. אָמַר רִבִּי יֵיסָא, בְּשַׁעֲתָא דְּאִצְטְרִיךְ עָלְמָא לְמִטְרָא, אֲמַאי אַזְלֵינָן לְגַבֵּיהוֹן דְּמֵתַיָּיא, וְהָא כְּתִיב <Nonei></i>(דברים י״ח:י״א) וְדוֹרֵשׁ אֶל הַמֵּתִים וְאָסִיר. אָמַר לֵיהּ עַד כָּאן לָא חֲמֵיתָא גַּדְפָּא דְּצִפָּרָא דְּעֵדֶן. וְדוֹרֵשׁ אֶל הַמֵּתִים, אֶל הַמֵּתִים דַּיְיקָא. דְּאִינּוּן חַיָּיבֵי עָלְמָא, דְּאִינּוּן מֵעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּאִשְׁתְּכָחוּ תָּדִיר מֵתִים. אֲבָל יִשְׂרָאֵל דְּאִינּוּן זַכָּאֵי קְשׁוֹט, שְׁלֹמֹה קְרָא עָלַיְיהוּ (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, בְּזִמְנָא אָחֳרָא וְלָא הַשְׁתָּא. שֶׁכְּבָר מֵתוּ, וְהַשְׁתָּא אִינּוּן חַיִּין.</p>\n<p>וְעוֹד, דִּשְׁאָר עַמִּין כַּד אָתָאן לִמְתֵיהוֹן, אַתְיָין בְּחַרְשִׁין, לְאִתְּעָרָא עָלַיְיהוּ זִינִין בִּישִׁין. וְכַד יִשְׂרָאֵל אָתָאן לִמְתֵיהוֹן, אַתְיָין בְּכַמָּה תְּשׁוּבָה לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. בִּתְבִירוּ דְּלִבָּא, בְּתַעֲנִיתָא לָקֳבְלֵיהּ, וְכֹלָּא בְּגִין דְּנִשְׁמָתִין קַדִּישִׁין יִבְעוּן רַחֲמֵי לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל עָלְמָא בְּגִינֵיהוֹן.</p>\n<p>וְעַל דָּא תָּנֵינָן, צַדִּיקָא אַף עַל גַּב דְּאִתְפְּטָר מֵהַאי עָלְמָא, לָא אִסְתַּלָּק וְלָא אִתְאֲבִיד מְכֻּלְּהוּ עָלְמִין, דְּהָא בְּכֻלְּהוּ עָלְמִין אִשְׁתְּכַח יַתִּיר מֵחַיּיוֹי. דִּבְחַיּיוֹי אִשְׁתְּכַח בְּהַאי עָלְמָא בִּלְחוֹדוֹי, וּלְבָתַר אִשְׁתְּכַח בִּתְלַת עָלְמִין, וְזַמִּין לְגַבַּיְיהוּ, דִּכְתִּיב, (שיר השירים א׳:ג׳) עֲלָמוֹת אֲהֵבוּךָ, אַל תִּקְרֵי עֲלָמוֹת, אֶלָּא עוֹלָמוֹת. זַכָּאָה חוּלָקֵיהוֹן.</p>\n<p>תָּאנָא, כְּתִיב (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדוֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים, וְהָיְתָה נֶפֶשׁ אֲדוֹנִי, נִשְׁמַת אֲדוֹנִי מִבָּעֵי לֵיהּ. אֶלָּא כְּמָה דְּאַמָרָן, דְּזַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא דְּכֹלָּא אִתְקְשַׁר דָּא בְּדָא, נֶפֶשׁ בְּרוּחַ, וְרוּחַ בִּנְּשָׁמָה, וּנְשָׁמָה בְּקוּדְשָׁא בְּרִיךְ הוּא. אִשְׁתְּכַח דְּנֶפֶשׁ צְרוּרָה בִּצְרוֹר הַחַיִּים.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, הַאי דְּאָמְרוּ חַבְרַיָּיא, גָּלוּתָא דְסֵפֶר תּוֹרָה אֲפִילּוּ מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא אָחֳרָא אָסִיר. וְכָּל שֶׁכֵּן לְבֵי רְחוֹב, אֲמַאי לְבֵי רְחוֹב. אָמַר רִבִּי יְהוּדָה, כְּמָה דְּאַמָרָן, בְּגִין דְּיִתְעָרוּן עָלֵיהּ וְיִתְבְּעוּן רַחֲמֵי עַל עָלְמָא. אָמַר רִבִּי אַבָּא, שְׁכִינְתָּא כַּד אִתְגַּלְיָיא הָכִי נָמֵי מֵאֲתַר לַאֲתַר, עַד דְּאָמְרָה (ירמיהו ט׳:א׳) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים וְגוֹ' אוּף הָכָא בְּקַדְמִיתָא מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא, לְבָתַר לְבֵי רְחוֹב, לְבָתַר בַּמִּדְבָּר מְלוֹן אוֹרְחִים. אָמַר רִבִּי יְהוּדָה, בְּנֵי בָּבֶל מִסְתָּפוּ וְלָא קָא עַבְרֵי אֲפִילּוּ מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא, כָּל שֶׁכֵּן הַאי.</p>\n<p>תַּנְיָא, אָמַר לְהוּ רַבִּי שִׁמְעוֹן לְחַבְרַיָּא, בְּיוֹמַאי לָא יִצְטָרְכוּן בְּנֵי עָלְמָא לְהַאי. אָמַר לֵיהּ רִבִּי יוֹסֵי, צַדִּיקַיָּיא מְגִינִּין עַל עָלְמָא בְּחַיֵּיהוֹן, וּבְמִיתָתְהוֹן יוֹתֵר מֵחַיֵּיהוֹן. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ז:ל״ה) וְגַנּוֹתִי עַל הָעִיר הַזֹאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי, וְאִילּוּ בְּחַיּיוֹהִי לָא כְּתִיב. אָמַר רִבִּי יְהוּדָה מַאי שְׁנָא הָכָא דִּכְתִּיב לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי, דְּשָׁקִיל הַאי לְגַבֵּי הַאי. אֶלָּא, בְּגִין דְּדָוִד זָכָה לְאִתְקַשְּׁרָא בִּרְתִּיכָא קַדִּישָׁא דַּאֲבָהָתָא, וּבְגִין כָּךְ כֹּלָּא חַד, בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמַיָּא.</p>"],[9520012148,"<p>(ויקרא י״ח:ג׳) כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ, רִבִּי יִצְחָק פָּתַח, (תהילים ק״ב:כ״ב) לְסַפֵּר בְּצִיּוֹן שֵׁם יְיָ' וּתְהִלָּתוֹ בִּיְרוּשָׁלַ ם. תַּמָּן תָּנֵינָן, שְׁמָא קַדִּישָׁא סָתִים וְגַלְיָא. וְאוֹרַיְיתָא דְּהִיא שְׁמָא קַדִּישָׁא עִלָּאָה, סָתִים וְגַלְיָא. וְכָל קְרָא דִּבְאוֹרַיְיתָא, וְכָל פַּרְשְׁתָא דְּאוֹרַיְיתָא, סָתִים וְגַלְיָא.</p>\n<p>דְּתַנְיָא אָמַר רִבִּי יְהוּדָה, מֵחֲצִיפוּתָא דְּצַדֶּקֶת חֲדָא, נַפְקָן כְּמָה טָבָאן לְעָלְמָא. וּמַאן הִיא. תָּמָר. דִּכְתִּיב, (בראשית ל״ח:י״ד) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. אָמַר רִבִּי אַבָּא, פַּרְשְׁתָּא דָּא מוֹכַח, דְּאוֹרַיְיתָא סָתִים וְגַלְיָא. וְהָא אִסְתַּכַּלְנָא בְּאוֹרַיְיתָא כֻּלָּא, וְלָא אַשְׁכַּחְנָא אֲתַר דְּאִקְרֵי פֶּתַח עֵינַיִם, אֶלָּא כֹּלָּא סָתִים, וְרָזָא דְּרָזִין הוּא.</p>\n<p>וְתַנְיָא, מַאי חָמָאת צַדֶּקֶת זוֹ לְעוֹבָדָא דָּא. אֶלָּא יַדְעַת בְּבֵיתָא דַּחֲמוֹהִי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, הֵיךְ מַדְבֵּר הַאי עָלְמָא עִם בְּנֵי נָשָׁא. וּבְגִין דְּהִיא יַדְעַת, קוּדְשָׁא בְּרִיךְ הוּא אוֹקִים מִלָּה עַל יְדָהָא. וְאַזְלָא הָא כְּמָה דְּתָנֵינָן, אִזְדַּמְּנַת הֲוַת בַּת שֶׁבַע מו' יְמֵי בְּרֵאשִׁית לְמֶהֱוִי אִמֵּיהּ דִּשְׁלָמָא מַלְכָּא. אוּף הָכָא אִזְדַּמְּנַת הֲוַת תָּמָר לְדָא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא.</p>\n<p>וַתֵּשֶׁב בְּפֶתַח עֵינַיִם, מַאן פֶּתַח עֵינַיִם כְּמָה דְּאַתְּ אָמֵר, (בראשית י״ח:א׳) וְהוּא יוֹשֵׁב פֶּתַח הָאֹהֶל. וּכְתִיב, (שמות י״ב:כ״ג) וּפָסַח יְיָ' עַל הַפֶּתַח. וּכְתִיב (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק וְגוֹ'. עֵינַיִם: דְּכָל עַיְינִין דְּעָלְמָא <Nonei></i>לְהַאי פִּתְחָא מְצַפָּאן. אֲשֶׁר עַל דֶּרֶךְ תִּמְנָתָה, מַאי תִּמְנָתָה. כְּמָה דְאַתְּ אָמֵר (במדבר יב) וּתְמוּנַת יְיָ' יַבִּיט. וְהָכִי אוֹקִימְנָא, תָּמָר אוֹקִימַת מִלָּה לְתַתָּא, וּפַרְחַת פַּרְחִין, וַאֲנִיצַת עַנְפִין בְּרָזָא דִּמְהֵימְנוּתָא.</p>\n<p>(הושע י״ב:א׳) וִיהוּדָה עוֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן. וַיִרְאֶהָ יְהוּדָה וַיַּחְשְׁבֶהָ לְזוֹנָה וְגוֹ'. כְּמָה דְאַתְּ אָמֵר, (משלי ל׳:כ׳) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת. כִּי כִסְּתָה פָּנֶיהָ, וְאוֹקִימְנָא כִּי כִסְּתָה פָּנֶיהָ, כְּמָה דְאַתְּ אָמֵר, אָכְלָה וּמָחֲתָה פִיהָ, אוֹקִידַת עָלְמָא בְּשַׁלְהוֹבוֹי, וְאָמְרָה לֹא פָעַלְתִּי אָוְן. מַאי טַעְמָא. בְּגִין כִּי כִסְּתָה פָּנֶיהָ, וְלֵית מַאן דְּיֵדַע אוֹרְחָהָא, לְאִשְׁתְּזָבָא מִנָּהּ. וַיֵּט אֵלֶיהָ אֶל הַדֶּרֶךְ, אֶל הַדֶּרֶךְ מַמָּשׁ, לְאִתְחַבְּרָא חִוָּורָא בְּסוּמָקָא. וַיֹאמֶר הָבָה נָא אָבֹא אֵלַיִךְ וְגוֹ', הָא אוֹקִימְנָא הָבָה בְּכָל אֲתַר.</p>\n<p>כִּי לֹא יָדַע כִּי כַלָּתוֹ הִיא. כִּי כַלָּתוֹ הִיא דְּעָלְמָא, מְתַרְגְּמִינָן אֲרִי שֵצַיְיתָא דְּעָלְמָא הִיא. מַאי טַעֲמָא לָא יָדַע. בְּגִין דְּהָא מְנַהֲרָן אַנְפָּהָא, לְקַבְּלָא מִנֵּיהּ, וְאִזְדַּמְּנָא לְאִתְבַּסְּמָא וּלְרַחֲמָא עָלְמָא (דבר אחר) כִּי כַלָּתוֹ הִיא, דָּא כַּלָּה מַמָּשׁ, דִּכְתִּיב, (שיר השירים ד׳:ח׳) אִתִּי מִלְּבָנוֹן כַּלָּה.</p>\n<p>וַתֹּאמֶר מַה תִּתֵּן לִי כִּי תָּבֹא אֵלָי. הַשְׁתָּא כַּלָּה בַּעְיָא תַּכְשִׁיטָהָא. וַיֹאמֶר אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן. לְמַלְכָּא דְהַוָה לֵיהּ בְּרָא מֵאָמַהוּ חֲדָא, וְאָזִיל בְּהֵיכָלָא, בָּעָא מַלְכָּא לְאִתְנַסְּבָא בְּמַטְרוֹנִיתָא עִלָּאָה, וּלְאַעְלָאָה בְּהֵיכָלֵיהּ. אָמְרָה מַאן יָהִיב לֵיהּ בְּהֵיכָלֵיהּ דְּמַלְכָּא (נ\"א מאן יהיב ליה לדין בהיכליה דמלכא. אמר מלכא), אָמַר מִכָּאן וּלְהָלְאָה אַשְׁדַר וְאַתָּרִיךְ לִבְרָא דְּאָמַהוּ מֵהֵיכָלָא דִּילִי.</p>\n<p>כַּךְ נָמֵי הָכָא, אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן. וְהָא אוֹקִימְנָא, בְּלֹא תְבַשֵּׁל גְּדִי. וְכָל אִינּוּן בְּסִטְרָא דִּבְכוֹר בְּהֵמָה קָא אָתוּ. וְעַל דָּא לָא כְּתִיב אָנֹכִי אֶתֵּן, אֶלָּא אָנֹכִי אֲשַׁלַּח, אַתָּרִיךְ וְאַשְׁדָּר לֵיהּ, דְּלָא יִשְׁתְּכַּח בְּהֵיכָלִי.</p>\n<p>וַתֹּאמֶר אִם תִּתֵּן עֵרָבוֹן עַד שָׁלְחֶךָ. אִלֵּין אִינּוּן סִימָנִין דְּמַטְרוֹנִיתָא, דְּאִתְבָּרְכָא מִן מַלְכָּא בְּזִוּוּגָהָא. וַיֹּאמֶר מַה הָעֵרָבוֹן אֲשֶׁר אֶתֵּן לָךְ, וַתֹּאמֶר חוֹתָמְךָ וּפְתִילֶךָ וּמַטְּךָ. אִלֵּין אִינּוּן (נ\"א סטרי) קִטְרֵי עִלָּאֵי, תַּכְשִׁיטָהָא דְּכַלָּה אִתְבָּרְכָא מִתְּלָתָא אִלֵּין, נֶצַח הוֹד יְסוֹד, וְכֹלָּא אִשְׁתְּכַח בִּתְלָתָא אִלֵּין וְכַלָה (ס\"א מנצח הוד יסוד) מֵהָכָא מִתְבָּרְכָא. מִיַּד וַיִּתֶּן לָהּ וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ. וַיְּהִי כְּמִשְׁלֹשׁ חֳדָשִׁים. מַאן מִשְׁלֹשׁ חֳדָשִׁים. בָּתַר דִּיתַלְּתוּן יַרְחַיָּא, וְהָא ג' יַרְחִין אוֹקִימְנָא. וְהָכָא כְּמִשְׁלֹשׁ חֳדָשִׁים, דְּשָׁארִי יַרְחָא רְבִיעָאָה לְאִתְּעָרָא דִּינִין בְּעָלְמָא בְּחוֹבֵי בְּנֵי נָשָׁא, וְהִיא יַנְקָא מִסִּטְרָא אָחֳרָא. כְּדֵין, וַיּוּגַּד לִיהוּדָה לֵאמֹר זָנְתָה תָּמָר כַּלָּתֶךָ, הָא כַּלָּה בְּסִטְרָא אָחֳרָא אִשְׁתְּכַחַת. מַה כְּתִיב, הוֹצִיאוּהָ. כְּמָה דִּכְתִּיב, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. וְתִשָּׂרֵף, בְּשַׁלְהוֹבֵי טִיהֲרָא בְּגָלוּתָא. מַה כְּתִיב, הִיא מוּצֵאת, לְאִתְמַשְּׁכָא בְּגָלוּתָא. וְהִיא שָׁלְחָה אֶל חָמִיהָ לֵאמֹר לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. לְאִישׁ אֲשֶׁר אֵלֶּה מִמֶּנוּ לָא כְּתִיב, אֶלָּא לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. דִּילֵיהּ סִימָנִין אִלֵּין מִשְׁתַּכְּחִין, אָנֹכִי הָרָה. מִיַּד וַיַּכֵּר יְהוּדָה וַיֹּאמֶר צָדְקָה מִמֶּנִּי. צָדְקָה וַדַּאי, וּשְׁמָא גָּרִים. מַאן גָּרִים לָהּ, שְׁמָא דָּא. הָדָר וְאָמַר מִמֶּנִּי, דִּכְתִּיב, (תהילים י״א:ז׳) כִּי צַדִּיק יְיָ' צְדָקוֹת אָהֵב יָשָׁר יֶחזוּ פָנֵימוֹ. צָדְקָה: צָדַק ה', דְּמִמֶּנִּי נַטְלַת שְׁמָא דָּא. מִמֶּנִּי יָרְתָא. מִמֶּנִּי אִשְׁתְּכַחַת.</p>\n<p>אָמַר רִבִּי יוֹסֵי, מַאי טַעְמָא חָמִיהָ כְּתִיב בַּאֲתַר חַד, יְהוּדָה בַּאֲתַר אָחֳרָא. אָמַר לֵיהּ, כֹּלָּא אִתְקְטַר דָּא בְּדָא. חָמִיהָ, בַּאֲתַר עִלָּאָה תָּלֵי.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, פַּרְשְׁתָּא דָּא אוֹקִימְנָא בְּרָזָא עִלָּאָה, בְּכַמָּה גַּוְונִין. כַּד יִסְתַּכְּלוּן מִלֵּי, מִינָּהּ יִשְׁתְּמַע רָזִין דְּאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְדִינוֹי בְּכָל אֲתַר. וְהִיא יַדְעַת וְאַקְדִּימַת גַּרְמָאָה לְמִלָּה דָּא, לְאַשְׁלְמָא אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּיִנְפְּקוּ מִינָּהּ מַלְכִין שַׁלִּיטִין, וּזְמִינִין לְשַׁלְּטָאָה עַל עָלְמָא. וְרוּת כְּהַאי גַּוְונָא עַבְדַת.</p>"],[9520012149,"<p>אָמַר רִבִּי אַבָּא, פַּרְשְׁתָּא דָּא בְּרָזָא דְּחָכְמְתָא דְּאוֹרַיְיתָא אִתְקַשְּׁרָא, וְכֹלָּא סָתִים וְגַלְיָא. וְאוֹרַיְיתָא כֹּלָּא כְּהַאי גַּוְונָא אִשְׁתְּכַחַת. וְלֵית לָךָ מִלָּה בְּאוֹרַיְיתָא, דְּלָא רָשִׁים בָּהּ שְׁמָא קַדִּישָׁא עִלָּאָה, דְּסָתִים וְגַלְיָא. <Nonei></i>בְּגִינֵי כַּךְ, סְתִימֵי דְּאוֹרַיְיתָא, קַדִּישֵׁי עֶלְיוֹנִין יָרְתִין לָהּ, וְאִתְגַּלְיָא בִּשְׁאָר בְּנֵי עָלְמָא. כְּגַוְונָא דָּא כְּתִיב, (תהילים ק״ב:כ״ב) לְסַפֵּר בְּצִיּוֹן שֵׁם יְיָ' וּתְהִלָּתוֹ בִּיְרוּשָׁלַ ם, דְּהָא בְּצִיּוֹן בְּמַקְדְּשָׁא, שָׁרֵי לְאַדְכְּרָא שְׁמָא קַדִּישָׁא כַּדְקָא חֲזֵי. וּלְבַר בְּכִינּוּיוֹ. וְעַל דָּא כֹּלָּא סָתִים וְגַלְיָא. תָּאנָא, כָּל מַאן דְּגָרַע אָת חַד מֵאוֹרַיְיתָא. אוֹ יוֹסִיף אָת חַד בְּאוֹרַיְיתָא, כְּמַאן דִּמְשַׁקֵּר בִּשְׁמָא קַדִּישָׁא עִלָּאָה דְּמַלְכָּא.</p>\n<p>אָמַר רִבִּי יִצְחָק, עוֹבָדָא דְּמִצְרַיִם פַּלְחִין לְשִׁפְחָה, כְּמָה דְּאוֹקִימְנָא. עוֹבָדָא דִּכְנַעַן, פַּלְחִין לְהַהוּא דְּאִקְרֵי (שמות י״ב:כ״ט) שְׁבִי אֲשֶׁר בְּבֵית הַבּוֹר. וְעַל דָּא כְּתִיב, (בראשית ט׳:כ״ה) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. בְּגִין כָּךְ כֻּלְּהוּ מַכְתִיבִין (ס\"א מברכין) (ס\"א מכדבין) בְּמִלִּין קַדִּישִׁין, וְעַבְדִין עוֹבָדִין (ס\"א עריין) בְּכֹלָּא. בְּגִינֵי כַּךְ כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ וְגוֹ'. רִבִּי יְהוּדָה אָמַר, דְּעַבְדִּין דִּינִין (ס\"א זינין) בִּישִׁין לְשַׁלְטָא עַל (נ\"א לסאבא) אַרְעָא, כְּמָה דְאַתְּ אָמֵר וְלֹא תְּטַמֵּא אֶת אַדְמָתְךָ. וּכְתִיב וַתִּטְמָא הָאָרֶץ.</p>\n<p>(ויקרא י״ח:ג׳) כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם וְגוֹ', רִבִּי חִיָּיא פָּתַח, (איוב ל״ח:י״ג) לֶאֱחוֹז בְּכַנְפוֹת הָאָרֶץ וְגוֹ', תָּאנָא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לְאַרְעֵיהּ, מִכָּל מְסַאֲבוּתָא דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּסָאִיבוּ לָהּ. כְּהַאי מַאן דְּאָחִיד בְּטָלִיתֵיהּ, וְאַנְעַר טִנּוּפָא מִנֵּיהּ. וְכָל אִינּוּן דְּאִתְקְבָרוּ בְּאַרְעָא קַדִּישָׁא, לְמִשְׁדֵּי לוֹן לְבַר, וּלְדַכְּאָה אַרְעָא קַדִּישָׁא מִסִּטְרָא אָחֳרָא (ס\"א קדישא אחרא), כִּבְיָכוֹל דְּהֲוָה מַתְּזָנָא לִשְׁאָר רַבְרְבֵי עַמִּין, וּלְקַבְּלָא מְסַאֲבוּתָא דִּלְהוֹן, וּלְדַבְּרָא לוֹן. וְזַמִּין לְדַכְּאָה לָהּ וּלְאַעְבְּרָא לוֹן לְבַר.</p>"],[9520012150,"<p>רִבִּי שִׁמְעוֹן הֲוָה מַדְכֵּי טוּרֵי (ס\"א שוקי) דִּטְבֶרְיָא, וְכָל דְּהֲוָה תַּמָּן מִית, הֲוָה סָלִיק לֵיהּ, וּמְדַכֵּי אַרְעָא. תָּאנָא, כְּתִיב (ירמיהו ב׳:ז׳) וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְגוֹ', אָמַר רִבִּי יְהוּדָה, זַכָּאָה חוּלָקֵיהּ מַאן דְּזָכֵי בְּחַיּיוֹי לְמִשְׁרֵי מָדוֹרָא בְּאַרְעָא קַדִּישָׁא. דְּכָל מַאן דְּזָכֵי לָהּ, זָכֵי לְאַנְגְּדָא מִטַּלָּא דִּשְׁמַיָּא דִּלְעֵילָּא, דְּנָחִית עַל אַרְעָא. וְכָל מַאן דְּזָכֵי לְאִתְקַשְּׁרָא בְּחַיּיוֹי בְּהַאי אַרְעָא קַדִּישָׁא, זָכֵי לְאִתְקַשְּׁרָא לְבָתַר בְּאַרְעָא קַדִּישָׁא עִלָּאָה.</p>\n<p>וְכָל מַאן דְּלָא זָכֵי בְּחַיּוֹי, וּמַיְיתִין לֵיהּ לְאִתְקַבְּרָא תַּמָּן, עָלֵיהּ כְּתִיב, (ירמיהו ב׳:ז׳) וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. רוּחֵיהּ נָפִיק בִּרְשׁוּתָא נוּכְרָאָה אָחֳרָא, וְגוּפֵיהּ אָתֵי תְּחוֹת רְשׁוּתָא דְּאַרְעָא קַדִּישָׁא, כִּבְיָכוֹל עָבִיד קֹדֶשׁ חוֹל, וְחוֹל קֹדֶשׁ. וְכָל מַאן דְּזָכֵי לְמֵיפַּק נִשְׁמָתֵיהּ בְּאַרְעָא קַדִּישָׁא, אִתְכְּפָּרוּ חוֹבוֹי, וְזָכֵי לְאִתְקַשְּׁרָא תְּחוֹת גַּדְפּוֹי דִּשְׁכִינְתָּא, דִּכְתִּיב, (דברים ל״ב:מ״ג) וְכִפֶּר אַדְמָתוֹ עַמּוֹ. וְלֹא עוֹד אֶלָּא אִי זָכֵי בְּחַיּיוֹי, זָכֵי לְאִתְמַשְּׁכָא עָלֵיהּ רוּחָא קַדִּישָׁא תָּדִיר, וְכָל מַאן דְּיָתִיב בִּרְשׁוּתָא אָחֳרָא, אִתְמְשַׁךְ עָלֵיהּ רוּחָא אָחֳרָא נוּכְרָאָה.</p>\n<p>תָּאנָא, כַּד סָלִיק רַב הַמְנוּנָא סָבָא לְהָתָם, הֲווֹ עִמֵּיהּ תְּרֵיסָר בְּנֵי מְתִיבְתָּא דִּילֵיהּ, אָמַר לוֹן, אִי אֲנָא אָזִיל לְאָרְחָא דָּא, לָאו עַל דִּידִי קָא עֲבִידְנָא, אֶלָּא לְאָתָבָא פִּקְדוֹנָא לְמָארֵיהּ. תָּנֵינָן כָּל אִינּוּן דְּלָא זָכוּ לְהַאי בְּחַיּיוֹי, אָתִיבִין פִּקְדוֹנָא דְּמָארֵיהוֹן לְאָחֳרָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, בְּגִינֵי כַּךְ, כָּל מַאן דְּאַעְבָּר מֵאִינּוּן זִינִין בִּישִׁין, אוֹ רְשׁוּתָא אָחֳרָא בְּאַרְעָא, אַרְעָא אִסְתְּאָבַת, וַוי לֵיהּ לְהַהוּא גְּבַר, וַוי לְנַפְשֵׁיהּ, דְּהָא אַרְעָא קַדִּישָׁא לָא מְקַבְּלָא לֵיהּ לְבָתַר. עָלֵיהּ כְּתִיב, (תהילים ק״ד:ל״ה) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ, בָּעוֹלָם הַזֶּה, וּבָעוֹלָם הַבָּא, וּרְשָׁעִים עוֹד אֵינָם, בִּתְחִיַּית הַמֵּתִים, כְּדֵין בָּרַכִי נַפְשִׁי אֶת יְיָ' הַלְלוּיָהּ.</p>"],[9520012151,"<p>(ויקרא י״ח:ד׳) אֶת מִשְׁפָּטַי תַּעֲשׂוּ וְאֶת חֻקֹּתַי תִּשְׁמְרוּ לָלֶכֶת בָּהֶם וְגוֹ', רִבִּי אַבָּא אָמַר, זַכָּאָה חוּלָקָא דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, וּבְגִין רְחִימוּתָא דִּילֵיהּ עָלַיְיהוּ, יָהִיב לוֹן נִימוּסִין דִּקְשׁוֹט, נָטַע בְּהוּ אִילָנָא דְּחַיֵּי, אַשְׁרֵי שְׁכִינְתָּא בֵּינַיְיהוּ. מַאי טַעְמָא. בְּגִין דְּיִשְׂרָאֵל רְשִׁימִין בִּרְשִׁימָא קַדִּישָׁא בִּבְשָׂרֵיהוֹן. וְאִשְׁתְּמוֹדְעָן דְּאִינְהוּ דִּילֵיהּ, (אשתמודען) מִבְּנֵי הֵיכָלֵיהּ.</p>\n<p>וּבְגִּינֵי כַּךְ, כָּל אִינּוּן דְּלָא רְשִׁימִין בִּרְשִׁימוּ קַדִּישָׁא <Nonei></i>בִּבְשָׂרֵיהוֹן לָאו אִינּוּן דִּילֵיהּ, וְאִשְׁתְּמוֹדְעָן דְּכֻלְּהוּ מִסִּטְרָא דִּמְסָאֲבוּתָא אַתְיָין, וְאָסִיר לְאִתְחַבְּרָא בְּהוּ, וּלְאִשְׁתָּעֵי בַּהֲדַיְיהוּ, בְּמִלּוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וְאָסִיר לְאוֹדָעָא לְהוּ מִלֵּי דְּאוֹרַיְיתָא, בְּגִין דְּאוֹרַיְיתָא כֻּלָּא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָל אָת דְּאוֹרַיְיתָא, מִתְקַשְּׁרָא בִּשְׁמָא קַדִּישָׁא. וְכָל מַאן דְּלָא אִתְרְשִׁים בִּרְשִׁימָא קַדִּישָׁא בִּבְשָׂרֵיהּ, אָסִיר לְאוֹדָעָא לֵיהּ מִלָּה דְּאוֹרַיְיתָא. וְכָּל שֶׁכֵּן לְאִשְׁתַּדְּלָא (נ\"א לאסתכלא) בֵּיהּ.</p>"],[9520012152,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (שמות י״ב:מ״ג-מ״ד) זֹאת חֻקַּת הַפָּסַח כָּל בֶּן נֵכָר לֹא יֹאכַל בּוֹ, וּכְתִיב וְכָל עֶבֶד אִישׁ וְגוֹ'. וּכְתִיב תּוֹשָׁב וְשָׂכִיר לֹא יֹאכַל בּוֹ. וּמַה פִּסְחָא דְּאִיהוּ בִּשְׂרָא לְמֵיכְלָא, עַל דְּאִתְרְמִיז בְּמִלָּה קַדִּישָׁא, אָסִיר לְכָל הָנֵי לְמֵיכַל בֵּיהּ, וּלְמֵיהַב לְהוּ לְמֵיכַל, עַד דְּאִתְגְּזָרוּ. אוֹרַיְיתָא דְּהִיא קֹדֶשׁ קֳדָשִׁים (דקדישא) שְׁמָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>רִבִּי אֶלְעָזָר שָׁאִיל לְרִבִּי שִׁמְעוֹן אֲבוּהִי, אָמַר לֵיהּ, הָא תָּנֵינָן אָסוּר לְלַמֵּד תּוֹרָה לְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת, וְשַׁפִּיר אַתְּעֲרוּ חַבְרַיָּיא דְּבָבֶל, דִּכְתִּיב, (תהילים קמ״ז:כ׳) לֹא עָשָׂה כֵן לְכָל גּוֹי, אֲבָל כֵּיוָן דְּאָמַר מַגִּיד דְּבָרָיו לְיַעֲקֹב, אֲמַאי חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. אָמַר לֵיהּ, אֶלְעָזָר תָּא חֲזֵי, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּחוּלָקָא עִלָּאָה קַדִּישָׁא דָּא נָטַע בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (משלי ד׳:ב׳) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם, לָכֶם, וְלָא לְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה.</p>\n<p>וּבְגִין דְּאִיהִי גְּנִיזָא עִלָּאָה יַקִּירָא, שְׁמֵיהּ מַמָּשׁ, אוֹרַיְיתָא כֹּלָּא סָתִים וְגַלְיָא, בְּרָזָא דִּשְׁמֵיהּ. וְעַל דָּא, יִשְׂרָאֵל בִּתְרֵין דַּרְגִּין אִינּוּן, סָתִים וְגַלְיָא, דְּתָנֵינָן תְּלַת דַּרְגִּין אִינּוּן מִתְקַשְּׁרָן דָּא בְּדָא, קוּדְשָׁא בְּרִיךְ הוּא, אוֹרַיְיתָא, וְיִשְׂרָאֵל. וְכָל חַד, דַּרְגָּא עַל דַּרְגָּא, סָתִים וְגַלְיָא. קוּדְשָׁא בְּרִיךְ הוּא דַּרְגָּא עַל דַּרְגָּא, סָתִים וְגַלְיָא. אוֹרַיְיתָא הָכִי נָמֵי סָתִים וְגַלְיָא. יִשְׂרָאֵל הָכִי נָמֵי דַּרְגָּא עַל דַּרְגָּא, הֲדָא הוּא דִּכְתִּיב, (תהילים קמ״ז:י״ט) מַגִּיד דְּבָרָיו לְיַעֲקֹב חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. תְּרֵי דַּרְגִּין אִינּוּן, יַעֲקֹב וְיִשְׂרָאֵל, חַד גַּלְיָא, וְחַד סָתִים.</p>\n<p>מַאי קָא מַיְירֵי. אֶלָא כָּל מָאן דְּאִתְגְּזַר וְאִתְרְשִׁים בִּשְׁמָא (נ\"א ברשומא) קַדִּישָׁא, יָהֲבִין לֵיהּ בְּאִינּוּן מִלִּין דְּאִתְגַּלְּיָין בְּאוֹרַיְיתָא, כְּלוֹמַר, מוֹדִיעִין לֵיהּ בְּרֵישֵׁי אַתְוָון, בְּרֵישֵׁי פִּרְקִין, יָהֲבִין עָלֵיהּ חוּמְרָא דְּפִקוּדֵי אוֹרַיְיתָא, וְלָא יַתִּיר, עַד דְּיִסְתָּלַק בְּדַרְגָּא אָחֳרָא, הֲדָא הוּא דִכְתִיב מַגִּיד דְּבָרָיו לְיַעֲקֹב (ליעקב שפיר). אֲבָל חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, דְּאִיהוּ בְּדַרְגָּא עִלָּאָה יַתִּיר. וּכְתִיב (בראשית ל״ה:י׳) לֹא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב וְגוֹ'. חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, אִלֵּין רָזֵי אוֹרַיְיתָא וְנִמּוּסֵי אוֹרַיְיתָא, וְסִתְרֵי אוֹרַיְיתָא, דְּלָא יִצְטָרְכוּן לְגַלָּאָה אֶלָּא לְמַאן דְּאִיהוּ בְּדַרְגָּא עִלָּאָה יַתִּיר כַּדְקָא חֲזֵי.</p>\n<p>וּמַה לְיִשְׂרָאֵל הַאי, לְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה עַל אַחַת כַּמָּה וְכַמָּה, וְכָל מַאן דְּלָא אִתְגְּזַר וְיָהֲבִין לֵיהּ אֲפִילּוּ אָת זְעֵירָא דְּאוֹרַיְיתָא, כְּאִלּוּ חָרִיב עָלְמָא, וּמְשַׁקֵּר בִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּכֹלָּא בְּהַאי תַּלְיָא, וְדָא אִתְקְשַׁר, דִּכְתִּיב, (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.</p>\n<p>תָּא חֲזֵי, כְּתִיב (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. לִפְנֵי בְּנֵי יִשְׂרָאֵל שָׂם, אַבָל לִשְׁאָר עַמִּין לָא שָׂם. בְּגִין כָּךְ דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל. (ויקרא כ) וְאֶל בְּנֵי יִשְׂרָאֵל תֹּאמַר. וְכֵן כֻּלְּהוּ. יְנוּחוּן אֲבָהָן דְּעָלְמָא, אִינּוּן הִלֵל וְשַׁמָּאי, דְּהָכִי אָמְרוּ לְאוּנְקְלוּס, וְלָא אוֹדְעוּ לֵיהּ מִלָּה דְּאוֹרַיְיתָא עַד דְּאִתְגְּזַר.</p>\n<p>וְתָא חֲזֵי, מִלָּה קַדְמָאָה דְּאוֹרַיְיתָא, דְּיָהֲבִין לִינוֹקֵי, אָלֶ\"ף בֵּי\"ת, דָּא מִלָּה דְּלָא יַכְלִין בְּנֵי עָלְמָא לְאַדְבְּקָא בְּסוּכְלְתָנוּ, וּלְסַלְּקָא לֵיהּ בִּרְעוּתָא, וְכָּל שֶׁכֵּן לְמַלְּלָא בְּפוּמֵיהוֹן. וַאֲפִילּוּ מַלְאֲכֵי עִלָּאֵי, וְעִלָאֵי דְּעִלָאֵי, לָא יַכְלִין לְאַדְבְּקָא, בְּגִין דְּאִינּוּן סְתִימִין דִּשְׁמָא קַדִּישָׁא. וַאֶלַף וְאַרְבַּע מְאָה וַחֲמֵשׁ רִבְּבָן דְּעָלְמִין, כֻּלְּהוּ תַלְיָין בְּקוּצָא דְּאַלֶ\"ף, וְשִׁבְעִין וּתְרֵין שְׁמָהָן קַדִישִׁין גְלִיפִין בְּאַתְווֹי רְשִׁימִין, דְּקַיְימוּ בְּהוּ עִלָּאֵי וְתַתָּאֵי, שְׁמַיָא וְאַרְעָא, וְכוּרְסְיָיא יְקָרָא דְּמַלְכָּא, תַּלְיָין מִסִּטְרָא חֲדָא לְסִטְרָא חֲדָא, דִּפְשִׁיטוּתָא דְּאָלֶף, קִיוּמָא דְּעָלְמִין כֻּלְּהוּ, וְסַמְכִין דְּעִלָּאִין וְתַתָּאִין בְּרָזָא דְּחָכְמְתָא.</p>\n<p>וּשְׁבִילִין סְתִימִין, וְנַהֲרִין עֲמִיקִין, וְעֶשֶׂר אֲמִירָן, כֻּלְּהוּ נָפְקִין מֵהַהוּא קוֹצָא תַּתָּאָה דִּתְחוֹת אָלֶף. מִכָּאן וּלְהָלְאָה שָׁארֵי לְאִתְפַּשְׁטָא אָלֶף בְּבֵית. וְלֵית חוּשְׁבָּן לְחָכְמְתָא דְּהָכָא אִתְגְּלִיף.</p>\n<p>בְּגִינֵי <Nonei></i>כַּךְ, אוֹרַיְיתָא קִיוּמָא דְּכֹלָּא, וּמְהֵימְנוּתָא דְּכֹלָּא, לְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא דָּא בְּדָא כַּדְקָא חֲזֵי. וּמַאן דְּאִתְגְּזַר, אִתְקָשַׁר בְּהַהוּא קִשְׁרָא דִּמְהֵימְנוּתָא. וּמַאן דְּלָא אִתְגְּזַר, וְלָא אִתְקְשַׁר בֵּיהּ, כְּתִיב בֵּיהּ, (ויקרא כ״ב:י׳) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. (שמות י״ב:מ״ח) וְכָל עָרֵל לֹא יֹאכַל בּוֹ. דְּהָא אִתְּעַר רוּחַ מִסְאֲבָא דְּמִסִּטְרֵיהּ, וְאָתֵי לְאִתְעָרְבָא בִּקְדוּשָּׁה. בְּרִיךְ רַחֲמָנָא, דְּפָרִישׁ לְיִשְׂרָאֵל בְּנוֹי, רְשִׁימִין בִּרְשִׁימָא קַדִּישָׁא, מִנַּיְיהוּ וּמִזוּהֲמָא דִּלְהוֹן. עָלַיְיהוּ כְּתִיב, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. וּבְגִּינֵי כַּךְ, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְלָא לְאָחֳרָא. תּוֹרַת אֱמֶת, לְזֶרַע אֱמֶת. אָתָא רִבִּי אֶלְעָזָר וּנְשָׁקֵיהּ עַל יְדוֹי.</p>\n<p>רִבִּי חִזְקִיָּה אָמַר, כְּתִיב (שמואל א י״ב:כ״ב) כִּי לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ בַּעֲבוּר שְׁמוֹ וְגוֹ', כִּי לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ, מַאי טַעְמָא בַּעֲבוּר שְׁמוֹ הַגָּדוֹל. בְּגִין דְּכֹלָּא אִתְקְשַׁר דָּא בְּדָא, וּבְמָּה אִתְקָשָּׁרוּ יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא. בְּהַהוּא רְשִׁימָא קַדִּישָׁא דְּאִתְרְשִׁים בִּבְשָׂרֵיהוֹן. וּבְגִּינֵי כַּךְ, לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ. וְלָמָּה. בַּעֲבוּר שְׁמוֹ הַגָּדוֹל דְּאִתְרְשִׁים בְּהוּ.</p>\n<p>תָּאנָא, אוֹרַיְיתָא אִקְרֵי בְּרִית, וְקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי בְּרִית. וְהַאי רְשִׁימָא קַדִּישָׁא אִקְרֵי בְּרִית. וְעַל דָּא כֹּלָּא אִתְקְשַׁר דָּא בְּדָא, וְלָא אִתְפְּרַשׁ דָּא מִן דָּא. אָמַר לֵיהּ רִבִּי יֵיסָא, אוֹרַיְיתָא וְיִשְׂרָאֵל שַׁפִּיר. אֲבָל קוּדְשָׁא בְּרִיךְ הוּא מְנָלָן דְּאִקְרֵי בְּרִית. אָמַר לֵיהּ דִּכְתִּיב, (תהילים ק״ו:מ״ה) וַיִּזְכּוֹר לָהֶם בְּרִיתוֹ, וְהָא אִתְיְידַע, וְהָא אִתְּמַר.</p>\n<p>(ויקרא י״ח:ד׳) וְאֶת חֻקֹּתַי תִּשְׁמְרוּ, חֻקּוֹתַי: אִלֵּין אִינּוּן נִמוּסֵי מַלְכָּא. מִשְׁפָּטַי: אִלֵּין אִינּוּן גִּזְרֵי אוֹרַיְיתָא, רִבִּי יְהוּדָה אָמַר, כָּל אִינּוּן נִמוּסִין מֵאֲתַר דְּאִקְרֵי צֶדֶק, אִקְרוּן חֻקּוֹתַי, וְאִינּוּן גְּזֵרַת מַלְכָּא. וּבְכָל אֲתַר דְּאִקְרֵי מִשְׁפָּט אִקְרוּן דִּינָא דְּמַלְכָּא, דְּאִיהוּ מַלְכָּא קַדִּישָׁא, קוּדְשָׁא בְּרִיךְ הוּא, מַלְכָּא דִּשְׁלָמָא כֹּלָּא דִּילֵיהּ הוּא. דְּהוּא מַלְכָּא קַדִּישָׁא, בַּאֲתַר דִּתְרֵין חוּלָקִין אֲחִידָן דָּא בְּדָא. וְעַל דָּא כְּתִיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ, וְאִינּוּן דִּינָא וְרַחֲמֵי. וּבְגִּינֵי כַּךְ חֹק וּמִשְׁפָּט. וְעַל דָּא כְּתִיב (תהילים קמ״ז:י״ט-כ׳) חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. לְיִשְׂרָאֵל וְלָא לִשְׁאָר עַמִּין.</p>\n<p>בַּתְרֵיהּ מַה כְּתִיב, לֹא עָשָׂה כֵן לְכָל גּוֹי. וְתָנֵינָן, אַף עַל גַּב דְּאִתְגְּזַר וְלָא עָבִיד פִּקּוּדֵי אוֹרַיְיתָא, הֲרֵי הוּא כְּגוֹי בְּכֹלָּא, וְאָסִיר לְמֵילַף לֵיהּ פִּתְגָּמֵי אוֹרַיְיתָא. וְעַל דָּא תָּנֵינָן (שמות כ׳:כ״ב) מִזְבַּח אֲבָנִים, דָּא מִזְבֵּחַ אֲבָנִים מַמָּשׁ. וְהָא קַשְׁיוּ דְּלִבֵּיהּ בְּאַתְרֵיהּ קַיְּימָא, וְזוּהֲמָא לָא אִתְפְּסָק מִנֵיהּ. בְּגִינֵי כַּךְ, לָא סָלִיק בִּידֵיהּ הַהוּא גְּזִירוּ, וְלָא מְהַנְיָא לֵיהּ. וְעַל דָּא כְּתִיב, (שמות כ׳:כ״ב) כִּי חַרְבְּךָ הֵנַפְתָּ עָלֶיהָ וַתְּחַלְלֶהָ.</p>\n<p>בְּגִינֵי כַּךְ, לֹא עָשָׂה כֵן לְכָל גּוֹי סְתָם. וּמִשְׁפָּטִים בַּל יְדָעוּם לְעָלַם וּלְעָלְמֵי עָלְמִין. מִלָּה אָחֳרָא (נ\"א זעירא), לָא יַהֲבֵינָן לְהוּ, כָּל שֶׁכֵּן רָזֵי אוֹרַיְיתָא, וְנִמוּסִין דְּאוֹרַיְיתָא. וּכְתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו.</p>"],[9520012153,"<p>מַתְנִיתִין, בְּנִמוּסֵי טְהִירִין. אַרְבַּע מַפְתְּחִין שָׁוִיין, לְאַרְבַּע סִטְרֵי עָלְמָא. בְּזִוְיַיתְהוֹן אִשְׁתְּכָחוּ. חַד לִסְטַר אַרְבַּע, וְאַרְבַּע לִסְטַר חַד. אִתְגַלְּפָן (ס\"א אתפלגן) בְּחַד גַּוְונָא. בְּהַהוּא גַּוְונָא, תְּכֵלָא, וְאַרְגְּוָונָא וְצֶבַע זְהוֹרִי, וְחִוָּורָא, וְסוּמָקָא. דָּא עָיֵיל בְּגַוְונָא דְּחַבְרֵיהּ, וְדִידֵיהּ בֵּיהּ רָשִׁים.</p>\n<p>אַרְבַּע רֵישִׁין כַּחֲדָא אִסְתְּלִיקוּ, וּבְחַד דִּיּוּקְנָא מִתְדַּבְּקָן. חַד רֵישָׁא אִסְתְּלִיק, מִגּוֹ סַחְיוּ דְּאִסְתְּחֵי. תְּרֵי אַיַּילְתָּא קְצִיבִין בְּשִׁיעוּרָא חַד, סַלְקָן מֵהַהוּא סַחְיוּתָא, דִּכְתִּיב, (שיר השירים ד׳:ב׳) כְּעֵדֶר הַקְּצוּבוֹת שֶׁעָלוּ מִן הָרַחְצָה. בְּשַׂעֲרָא דִּלְהוֹן, חֵיזוֹ דְּאֶבֶן טָבָא דְּאַרְבַּע גַּוְונִין.</p>\n<p>אַרְבַּע גַּדְפִּין דְּכַסְיָין עַל גּוּפָא, וִידִין זְעִירִין תְּחוֹת גַּדְפַּיְיהוּ. וְחָמֵשׁ בְּחָמֵשׁ גְּלִיפָן. טָאסִין (ס\"א שאפין) לְעֵילָּא לְעֵילָּא מֵהֵיכָלָא, דְּשַׁפִּירָא בְּרֵיוָא וְיָאֶה לְמֵחזֵי.</p>\n<p>חַד עוּלֵים רַבְיָא, נָפִּיק שִׁנָּן חַרְבָּא, דְּמִתְהַפְּכָא לְגוּבְרִין לְנוּקְבִין. נַטְלִין לִמְשִׁיחָא דְּאֵיפָה בֵּין שְׁמַיָּא וּבֵין אַרְעָא. לְזִמְנִין נַטְלִין (ס\"א עולין) לָהּ בְּכָל עָלְמָא, וְכָל מְשִׁיחִין בָּהּ מָשִׁיחִין, דִּכְתִּיב, (ויקרא י״ט:ל״ו) אֵיפַת צֶדֶק וְגוֹ'.</p>\n<p>חַד חֵיזוֹ דִּבְדוֹלְחָא, קַיְּימָא עַל חַרְבָּא חַד, בְּרֵישָׁא דְּהַהוּא רַבְיָא (נ\"א חרבא) מְלָהֲטָא סוּמָקָא מִגּוֹ בְּדוֹלְחָא. <Nonei></i>תְּרֵין סִטְרִין מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא, אִתְחֲזֵי הַהוּא חַרְבָּא, בִּרְשִׁימִין עֲמִיקִין, חַד גְּבָר תַּקִּיף, עוֹלְמָא דְּקַיְּימָא בי\"ג עָלְמִין. חַגִיר הַהוּא חַרְבָּא, לְמֶעְבַּד נוּקְמִין. עִמֵּיהּ חַגִּירִין שִׁתִּין אָחֳרָנִין, כֻּלְּהוּ מִשְׁתַלְחֶפֵי (נ\"א מתיילפי) (ס\"א משלפי) נַצְחִין קְרָבָא, הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר הוֹדְךָ וַהֲדָרֶךָ. וּכְתִיב (שיר השירים ג׳:ח׳) כֻּלָּם אֲחוּזֵי חֶרֶב מְלוּמְּדֵי מִלְחָמָה וְגוֹ'. בְּכַמָּה גַּוְונִין מִתְהַפְּכִין אַנְפַּיְיהוּ, לֵית דְּיֵדַע לוֹן, בַּר חַד תּוֹלַעְתָּא דְּשָׁאט (ס\"א דשארי) בֵּין נוּנֵי יַמָּא, כָּל אֲבָנִין דְּאַעְבָּר עָלַיְיהוּ מִתְבַּקְּעִין.</p>\n<p>בְּהַהוּא זִמְנָא, קָלָא דְּנָפִיק מֵאִינּוּן דַּחֲגִירֵי חַרְבָּא, מְבָקַע תִּמְנֵיסָר טוּרִין רַבְרְבִין, וְלֵית מַאן דְּיַרְכִּין אוּדְנֵיהּ. כֻּלְּהוּ עָלְמָא סְתִימִין עַיְינִין, אֲטִימִין לִבָּא, לֵית מַאן דְּיַשְׁגַּח דְּהָא בִּנְיָינָא לִסְתּוֹר כַּד עַבְדִּין עוֹבָדָן דְּלָא מִתְכַּשְּׁרָן, סָאטִין מֵאָרְחָא דְּתַקְּנָא, יְמִינָא אַעְדֵּי, וּשְׂמָאלָא שַׁלְטָא, כְּדֵין עֶרְיָין אִשְׁתְּכָחוּ. וַוי לְחַיָּיבַיָּא דְּגַרְמִין דָּא בְּעָלְמָא, דְּהָא לָא מִתְבָּרְכִין לְעֵילָּא, עַד דְּיִשְׁתְּצוּן אִינּוּן לְתַתָּא. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ל״ה) וּרְשָׁעִים עוֹד אֵינָם בָּרַכִי נַפְשִׁי אֶת יְיָ' הַלְלוּיָהּ. (ע\"כ).</p>"],[9520012154,"<p>(ויקרא ח\"י) עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה רִבִּי חִיָּיא פָּתַח. (שיר השירים ב׳:ג׳) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי בֵּין הַבָּנִים וְגוֹ'. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, אֲבָל כַּמָה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. דְּהִיא מְשַׁבַּחַת לֵיהּ בְּהַאי. הָכָא אִית לְאִסְתַּכְּלָא, אֲמַאי מְשַׁבַּחַת לֵיהּ בְּתַפּוּחַ, וְלָא בְּמִלָּה אָחֳרָא, אוֹ בִּגְוָונִין אוֹ בְּרֵיחָא אוֹ בְּטַעְמָא.</p>\n<p>אֲבָל הוֹאִיל וּכְתִיב תַּפּוּחַ, בְּכֹלָּא הִיא מְשַׁבַּחַת לֵיהּ, בִּגְוָונִין, בְּרֵיחָא, וּבְטַעְמָא. מַה תַּפּוּחַ הוּא אַסוּותָא לְכֹלָּא, אוּף קוּדְשָׁא בְּרִיךְ הוּא אַסוּותָא לְכֹלָּא. מַה תַּפּוּחַ אִשְׁתְּכַח בִּגְוָונֵי, כְּמָה דְּאוֹקִימְנָא, אוּף קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בִּגְוָונִין עִלָּאִין. מַה תַּפּוּחַ אִית בֵּיהּ רוּחָא דָּקִיק מִכָּל שְׁאָר אִילָנֵי, אוּף קוּדְשָׁא בְּרִיךְ הוּא כְּתִיב בֵּיהּ (הושע י״ד:ז׳) וְרֵיחַ לוֹ כַּלְּבָנוֹן. מַה תַּפּוּחַ טַעְמֵיהּ מְתִיקָא, אוּף קוּדְשָׁא בְּרִיךְ הוּא כְּתִיב בֵּיהּ (שיר השירים ה׳:ט״ז) חִכּוֹ מַמְתַּקִּים.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ לִכְּנֶסֶת יִשְׂרָאֵל כְּשׁוֹשַׁנָּה, וְהָא אוֹקִימְנָא מִלֵי, אֲמַאי כְּשׁוֹשַׁנָּה, וְהָא אִתְּמַר. רִבִּי יְהוּדָה אָמַר, בְּשַׁעֲתָא דְּאַסְגִּיאוּ זַכָּאֵי בְּעָלְמָא, כְּנֶסֶת יִשְׂרָאֵל סַלְּקָא רֵיחִין טָבִין, וּמִתְבָּרְכָא מִמַּלְכָּא קַדִּישָׁא, וְאַנְפָּהָא נְהִירִין. וּבְזִמְנָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, כִּבְיָכוֹל כְּנֶסֶת יִשְׂרָאֵל לָא סַלְּקָא רֵיחִין טָבִין, וְאַטְעָמַת מִסִּטְרָא אָחֳרָא מְרִירָא. כְּדֵין, כְּתִיב (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ', וְאַנְפָּהָא חֲשׁוֹכָן.</p>\n<p>רִבִּי יוֹסֵי אָמַר, בְּשַׁעֲתָא דְּאַסְגִּיאוּ זַכָּאִין בְּעָלְמָא, כְּתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וּבְזִמְנָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, כְּתִיב (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ. רִבִּי חִזְקִיָּה אָמַר מֵהָכָא, (משלי ט״ז:כ״ח) וְנִרְגָּן מַפְרִיד אַלּוּף, כְּלוֹמַר פָּרִישׁ מַלְכָּא מִן מַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה.</p>"],[9520012155,"<p>רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵי אֲבוֹי, אָמַר לֵיהּ, אִי פְּרַקְלִיטָא בְּעָלְמָא בְּמַטְרוֹנִיתָא אִשְׁתְּכַח, וְאִי קַטֵיגוֹרְיָא בְּעָלְמָא, בְּמַטְרוֹנִיתָא אִשְׁתְּכַח, אֲמַאי. אָמַר לֵיהּ, לְמַלְכָּא דְּהֲוָה לֵיהּ בַּר מִמַטְרוֹנִיתָא, כָּל זִמְנָא דְּהַהוּא בְּרָא עָבִיד רְעוּתָא דְּמַלְכָּא, מַלְכָּא עָבִיד מָדוֹרֵיהּ בְּמַטְרוֹנִיתָא. וְכָל זִמְנָא דְּלָא הֲוָה הַהוּא בַּר עָבִיד רְעוּתָא דְּמַלְכָּא, מַלְכָּא פָּרִישׁ מָדוֹרֵיהּ מִמַּטְרוֹנִיתָא.</p>\n<p>כַּךְ קוּדְשָׁא בְּרִיךְ הוּא וּכְּנֶסֶת יִשְׂרָאֵל, כָּל זִמְנָא דְּיִשְׂרָאֵל עַבְדִּין רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא שַׁוִּי מָדוֹרֵיהּ בִּכְנֶסֶת יִשְׂרָאֵל. וְכָל זִמְנָא דְּיִשְׂרָאֵל לָא עַבְדִין רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא לָא שַׁוִּי מָדוֹרֵיהּ בִּכְּנֶסֶת יִשְׂרָאֵל. מַאי טַעְמָא. בְּגִין דְּיִשְׂרָאֵל הוּא בְּרָא בּוּכְרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל. אִמָּא, דָּא הִיא כְּנֶסֶת יִשְׂרָאֵל דִּכְתִּיב, (משלי יא) וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ.</p>\n<p>תָּא חֲזֵי, כָּל זִמְנָא דְּיִשְׂרָאֵל רָחֲקִין מֵהֵיכָלָא דְּמַלְכָּא, כִּבְיָכוֹל מַטְרוֹנִיתָא אִתְרַחֲקַת עִמְּהוֹן. מַאי טַעְמָא. בְּגִין דְּמַטְרוֹנִיתָא לָא אַקְדִּימַת קִיסְטָא לְהַאי בַּר, לְאַלְקָאָה לֵיהּ, לְמֵיהַךְ בְּאוֹרַח מֵישָׁר. בְּגִין דְּמַלְכָּא לָא אַלְקֵי לִבְרֵיהּ לְעָלְמִין. אֶלָּא שָׁבִיק כֹּלָּא בִּידָא דְּמַטְרוֹנִיתָא, לְאַנְהָגָא הֵיכָלָא, וּלְאַלְקָאָה בְּרָהּ, וּלְדַבְּרָא לֵיהּ בְּאוֹרַח קְשׁוֹט, לָקֳבְלֵיהּ דְּמַלְכָּא.</p>\n<p><Nonei></i>וְרָזָא דְּמִלָּה דִּכְתִּיב, (משלי ל״א:א׳) דִּבְרֵי לְמוֹאֵל מֶלֶךְ מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ (אמו ודאי), דָּא בַּת שֶׁבַע, וְהָא אִתְּמַר כְּתִיב, (משלי י׳:א׳) מִשְׁלֵי שְׁלֹמֹה בֵּן חָכָם יְשַׂמַּח אָב וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי. חָמֵי מַה כְּתִיב, בֵּן חָכָם יְשַׂמַּח אָב, בְּעוֹד דְּהַאי בַּר אָזִיל בְּאוֹרַח מֵישָׁר, וְהוּא חַכִּימָא, יְשַׂמַּח אָב (כלל), דָּא מַלְכָּא קַדִּישָׁא לְעֵילָּא. יְשַׂמַּח אָב סְתָם. אִשְׁתְּכַח הַאי בַּר בְּאוֹרְחָא תְּקָלָא, מַה כְּתִיב וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְרָזָא דְּמִלָּה כְּתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֲכֶם שֻׁלְּחָה אִמְּכֶם.</p>\n<p>תָּא חֲזֵי, לָא אִשְׁתְּכַח חֶדְוָותָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כְּיוֹמָא דְּסָלִיק שְׁלֹמֹה לְחָכְמְתָא, וְאָמַר שִׁיר הַשִּׁירִים. כְּדֵין נְהִירוּ אַנְפּוֹי דְּמַטְרוֹנִיתָא, וְאָתֵי מַלְכָּא לְמִשְׁרֵי מָדוֹרֵיהּ עִמָּהּ. הֲדָא הוּא דִכְתִיב, (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלֹמֹה וְגוֹ'. מַאי וַתֵּרֶב. דְּסַלְּקָא שְׁפִּירוּ דְּמַטְרוֹנִיתָא, וְאִתְרַבִּיאַת בְּדַרְגָּהָא עַל כָּל שְׁאָר דַּרְגִּין, בְּגִין דְּמַלְכָּא שַׁוִּי מָדוֹרֵיהּ בָּהּ. וְכָל כַּךְ לָמָּה. בְּגִין דְּאַפִּיקַת בְּרָא חַכִּימָא דָּא לְעָלְמָא. (נ\"א למלכא)</p>\n<p>וְכַד אַפִּיקַת לֵיהּ לִשְׁלֹמֹה, לְכָל יִשְׂרָאֵל אַפִּיקַת, וְכֻלְּהוּ הֲווֹ בְּדַרְגִּין עִלָּאִין זַכָּאִין כִּשְׁלֹמֹה (ס\"א בשלמא). דְּקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי בְּהוּ, וְאִינּוּן בֵּיהּ. וּבְיוֹמָא דְּשַׁכְלַל שְׁלֹמֹה בֵּיתָא לְתַתָּא, אַתְקִינַת מַטְרוֹנִיתָא בֵּיתָא לְמַלְכָּא. וְשַׁוּוּ מָדוֹרֵיהוֹן כַּחֲדָא, וּנְהִירוּ אַנְפָּהָא בְּחֶדְוָה שְׁלִימוּ. כְּדֵין אִשְׁתְּכַח חֶדְוָותָא לְכֹלָּא, לְעֵילָּא וְתַתָּא. וְכָל כַּךְ לָמָּה. בְּגִין דִּכְתִּיב, מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, דְּדַּבְּרַת לֵיהּ לִרְעוּתָא דְּמַלְכָּא.</p>\n<p>וְכַד הַאי בַּר כְּמָה דַּאֲמֵינָא, (ס\"א דאצטריך) לָא אִתְדְּבַר לִרְעוּתֵיהּ דְּמַלְכָּא. כְּדֵין הִיא עֶרְיָיתָא דְּכֹלָּא, עֶרְיָיתָא דְּכָל סִטְרִין דְּהָא מַלְכָּא פָּרִישׁ מִמַּטְרוֹנִיתָא, וּמַטְרוֹנִיתָא אִתְרַחֲקַת מְהֵיכָלֵיהּ, וּבְגִין כָּךְ עֶרְיָיתָא הִיא דְּכֹלָּא. וְכִי לָא עֶרְיָיתָא הוּא, מַלְכָּא בְּלָא מַטְרוֹנִיתָא, וּמַטְרוֹנִיתָא בְּלָא מַלְכָּא. וְעַל דָּא כְּתִיב, עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה אִמְּךָ הִיא. אִמְּךָ הִיא וַדַּאי, וְשַׁרְיָא עִמָּךְ, בְּגִינֵי כַּךְ לֹא תְגַלֵּה עֶרְוָתָהּ.</p>"],[9520012156,"<p>רַבִּי שִׁמְעוֹן אָקִישׁ יְדוֹי וּבָכָה, וְאָמַר וַוי אִי אֵימָא וְגַלֵינָא רָזָא, וַוי אִי לָא אֵימָא, דְּיֵיבְדוּן חַבְרַיָּיא מִלָּה. (יחזקאל י״א:י״ג) אֲהָהּ יְיָ' אֱלֹהִים כָּלָה אַתָּה עוֹשֶׂה אֵת שְׁאֵרִית יִשְׂרָאֵל. מַאי אֲהָהּ. וּמַאי כָּלָה אַתָּה עוֹשֶׂה. אֶלָּא רָזָא דְּמִלָּה, בְּזִמְנָא דְּה' תַּתָּאָה אִתְתְּרָכַת מֵהֵיכָלָא דְּמַלְכָּא, ה' אָחֳרָא עִלָּאָה בְּגִינָהּ מַנְעַת בִּרְכָתָא. וּכְדֵין כְּתִיב, אֲהָהּ כָּלָה אַתָּה עוֹשֶׂה. בְּגִין דְּכַד אִיהִי (נ\"א האי ה') אִתְמְנָעַת מִבִּרְכָאן, ה' אָחֳרָא מַנְעַת לוֹן מִכֹּלָּא. מַאי טַעֲמָא. בְּגִין דְּבִרְכָּאן לָא מִשְׁתַּכְּחֵי, אֶלָּא בַּאֲתַר דְּשַׁרְיָין דְּכַר וְנוּקְבָּא.</p>\n<p>וְעַל דָּא כְּתִיב, (ירמיהו כ״ה:ל׳) יְיָ' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוִהוּ. עַל נָוִהוּ מַמָּשׁ. דָּא מַטְרוֹנִיתָא, וְדָא הוּא וַדַּאי. וּמַאי אוֹמֵר. אוֹי שֶׁהֱחֶרַבְתִּי אֶת בֵּיתִי וְכוּ'. בֵּיתִי זִוּוּגָא דְּמַטְרוֹנִיתָא. וְדָא הוּא וַדַּאי, עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה. דְּהָא מִכָּל סִטְרִין עֶרְיָיתָא הוּא. וּכְדֵין, (ישעיהו נ׳:ג׳) לָבְשׁוּ שָׁמַיִם קַדְרוּת וְשַׂק הוּשַׂם כְּסוּתָם דְּהָא אֲתַר אַחֲסָנַת בִּרְכָאן דְּמַבּוּעִין דְּנַחֲלִין דַּהֲווֹ נְגִּידִין וְשַׁקְיָין כַּדְקָא חֲזוּ, אִתְמְנָעוּ.</p>\n<p>תָּנֵינָן, כַּד אִתְפְּרַשׁ מַלְכָּא מִמַּטְרוֹנִיתָא, וּבִרְכָּאן לָא מִשְׁתַּכְּחָן, כְּדֵין אִקְרֵי ו\"י. מַאי טַעְמָא ו\"י. דְּתַנְיָא, רֵישָׁא דִּיְּסוֹד י', דְּהָא יְסוֹד ו' זְעֵירָא הוּא, וְקוּדְשָׁא בְּרִיךְ הוּא ו' רַבְרְבָא עִלָּאָה. וְעַל דָּא כְּתִיב וָ\"ו תְּרֵין וָוִין כַּחֲדָא, וְרֵישָׁא דְּהַאי יְסוֹד י' הוּא. וְכַד אִתְרַחֲקַת מַטְרוֹנִיתָא מִמַּלְכָּא, וּבִרְכָּאן אִתְמְנָעוּ מִמַּלְכָּא, וְזִוּוּגָא לָא אִשְׁתְּכַח בְּרֵישָׁא דִּיְּסוֹד, נָטִיל ו' עִלָּאָה לְהַאי רֵישָׁא דִּיְּסוֹד דְּהוּא י', וְנָגִיד לֵיהּ לְגַבֵּיהּ, כְּדֵין הוּא ו\"י, ו\"י לְכֹלָּא, לְעִלָּאִין וְתַתָּאִין.</p>\n<p>וְעַל דָּא תָּנֵינָן, מִיּוֹמָא דְּאִתְחֲרִיב יְרוּשָׁלַם, בִּרְכָאן לָא אִשְׁתְּכָחוּ בְּעָלְמָא, וְלֵית לָךְ יוֹם דְּלָא אִשְׁתְּכַח בֵּיהּ לְוָוטִין, דְּהָא בִּרְכָאן אִתְמְנָעוּ בְּכָל יוֹם. אָמַר לֵיהּ, אוֹ הָכִי, אוֹ\"י אוֹ הוֹ\"י, (נ\"א או וה') מַהוּ.</p>\n<p>אָמַר לֵיהּ, כַּד מִלָּה תַּלְיָא בִּתְשׁוּבָה, וְלָא תַּיְיבִין, כְּדֵין ה' עִלָּאָה נָטִיל לוֹן, וְאַנְגִיד לְוָאו וְי', לְגַבָּהּ, <Nonei></i>בְּגִין דְּלָא תַּיְיבִין, כְּדֵין אִקְרֵי הוֹי. הוֹי כַּד אִסְתַּלָּק מַלְכָּא לְעֵילָּא לְעֵילָּא, וְצַוְוחִין בְּנֵי נָשָׁא וְלָא אַשְׁגַּח בְּהוּ. וְהַהוּא עִלָּאָה אֶהְיֶה טְמִירָא, סָלִיק לְו', וְי' לְגַבֵּיהּ, בְּגִין דְּלָא אִתְקְבִּיל צְלוֹתֵיהּ, כְּדֵין אִקְרֵי אוֹי, דְּהָא א' סָלִיק לְגַבֵּיהּ דְּו' וְי'. (ס\"א דהוא א' סליק גביה לה' ו' לי') וּכְדֵין תְּשׁוּבָה לָא אִשְׁתְּכַח. וְעַל דָּא אִסְתַּלָּק מֵאִלֵּין אַתְוָון ה', דְּהָא בִּתְשׁוּבָה לָא תַּלְיָיא.</p>\n<p>וַדַּאי כַּד אַסְגִּיאוּ חוֹבֵי עָלְמָא טְפֵי, וּתְשׁוּבָה הֲוָה תַּלְיָא בְּקַדְמִיתָא, וְלָא בָּעוּ, כְּדֵין אִסְתַּלָּק ה', וא' סָלִיק לְו' יוֹ\"ד לְגַבֵּיהּ, וְאִקְרֵי אוֹי. וְכַד חָרִיב בֵּי מַקְדְּשָׁא, וּתְשׁוּבָה אִסְתָּלָקַת (ולא מעליא), כְּדֵין צָוְוחוּ וְאָמְרוּ, (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָנָה הַיּוֹם. מַאי כִּי פָנָה הַיּוֹם. דָּא הוּא יוֹמָא עִלָּאָה, דְּאִקְרֵי תְּשׁוּבָה, דְּאִסְתַּלָּק וְאִתְעֲבָר, וְלָא שְׁכִיחַ. הַהוּא יוֹמָא דְּאִשְׁתְּמוֹדַע, לְפַשְׁטָא יְמִינָא לְקַבְּלָא חַיָּיבִין, וְהָא אִתְפְּנֵי מִכֹּלָּא, וְלָא אִשְׁתְּכַח, וְעַל דָּא אָמְרוּ אוֹי, וְלָא הוֹי. כִּי יִנָּטוּ צִלְלֵי עָרֶב, דְּהָא אִתְיְיהִיב רְשׁוּ לְרַבְרְבֵי מְמָנָן דִּשְׁאָר עַמִּין, לְמִשְׁלַט עָלַיְיהוּ.</p>\n<p>תָּאנָא, סָלִיק ו' לְעֵילָּא לְעֵילָּא, וְהֵיכָלָא אִתּוֹקַד, וְעַמָּא אִתְגְּלֵי, וּמַטְרוֹנִיתָא אִתְתְּרָכַת, וּבֵיתָא אִתְחֲרָבַת. לְבָתַר כַּד נָחִית ו\"ו לְאַתְרֵיהּ, אַשְׁגַּח בְּבֵיתֵיהּ וְהָא אִתְחֲרִיב, בָּעֵי לְמַטְרוֹנִיתָא, וְהָא אִתְרַחֲקַת וְאַזְלַת. חָמָא לְהֵיכָלֵיהּ, וְהָא אִתּוֹקַד. בָּעָא לְעַמָּא, וְהָא אִתְגְּלֵי. חָמָא לְבִרְכָּאן דְּנַחֲלִין עֲמִיקִין דַּהֲווֹ נַגְדִּין, וְהָא אִתְמְנָעוּ. כְּדֵין כְּתִיב, (ישעיהו כ״ב:י״ב) וַיִּקְרָא יְיָ' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרְחָה וְלַחֲגוֹר שָׂק. וּכְדֵין לָבְשׁוּ שָׁמַיִם קַדְרוּת.</p>\n<p>כְּדֵין ו' ה' (ס\"א ו' י') אִתְנְגִיד חַד לָקֳבֵיל חַד. וְה' עִלָּאָה, נָגִיד מַבּוּעֵי לְסִטְרָא אָחֳרָא, וּבִרְכָּאן לָא מִשְׁתַּכְּחָן. דְּהָא דְּכַר וְנוּקְבָּא לָא אִשְׁתְּכָחוּ, וְלָא שַׁרְיָין כַּחֲדָא. כְּדֵין (ירמיהו כ״ה:ל׳) שָׁאֹג יִשְׁאַג עַל נָוִהוּ. בָּכָה רַבִּי שִׁמְעוֹן, וּבָכָה רִבִּי אֶלְעָזָר, אָמַר רִבִּי אֶלְעָזָר, בְּכִיָיה תְּקִיעָא בְּלִבָּאִי מִסִּטְרָא חֲדָא, וְחֶדְוָותָא בְּלִבָּאִי מִסִּטְרָא אָחֳרָא. דְּהָא שְׁמַעְנָא מִלִּין, דְּלָא שְׁמַעְנָא עַד הַשְׁתָּא, זַכָּאָה חוּלָקִי.</p>"],[9520012157,"<p>(ויקרא ח\"י) עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה, מַאן אֵשֶׁת אָבִיךָ. אָמַר רַבִּי שִׁמְעוֹן, הָא תָּנֵינָן, כָּל מִלּוֹי דְּאוֹרַיְיתָא סָתִים וְגַלְיָא, כְּמָה דִּשְׁמָא קַדִּישָׁא סָתִים וְגַלְיָא, אוֹרַיְיתָא דְּהִיא שְׁמָא קַדִּישָׁא, הָכִי נָמֵי סָתִים וְגַלְיָא. הָכָא כֹּלָּא בְּאִתְגַּלְיָיא, יְדִיעָא סָתִים כְּמָה דְּאוֹקִימְנָא.</p>\n<p>וְהַאי קְרָא הָכִי הוּא, אֵשֶׁת אָבִיךָ: תָּאנָא, כָּל זִמְנָא דְּמַטְרוֹנִיתָא אִשְׁתְּכַחַת בְּמַלְכָּא, וְיַנְקָא לָךְ, אִקְרֵי אִמֶּךָ. הַשְׁתָּא דְּאִתְגַּלְיָא עִמָּךְ וְאִתְרָחֲקַת מִן מַלְכָּא, אֵשֶׁת אָבִיךָ אִתְקְרֵי. אִנְתּוּ הִיא דְּמַלְכָּא קַדִּישָׁא לָא אִתְפְּטָרַת בְּתִרוּכִין מִנֵּיהּ, אִנְתְּתֵיהּ הִיא וַדַּאי. כְּמָה דִּכְתִּיב, (ישעיהו נ׳:א׳) כֹּה אָמַר יְיָ' אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. אֶלָּא וַדַּאי אִנְתּוּ הִיא דְּמַלְכָּא, אַף עַל גַּב דְּאִתְגַּלְיָיא.</p>\n<p>וְעַל דָּא פָּקִיד עָלָה תְּרֵי זִמְנֵי, כַּד יָתְבָא בְּמַלְכָּא בְּזִוּוּגָא חַד, וְאִתְקְרֵי אִמְּךָ, דִּכְתִּיב עֶרְוַת אִמְּךָ לֹא תְגַלֵּה, לָא תַּעֲבִיד דְּיִתְרַחֲקוּן דָּא מִן דָּא, וְתִשְׁתְּלַח עַל חוֹבָךְ, כְּמָה דִּכְתִּיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵכֶם שֻׁלְחָה אִמְּכֶם. וְחַד, כַּד הִיא בְּגָלוּתָא עִמָּךְ, וְאִתְגַּלְיָיא מֵהֵיכָלָא דְּמַלְכָּא, וְאִתְקְרֵי אִנְתּוּ דְּמַלְכָּא. אַף עַל גַּב דְּאִתְרַחֲקָת מִנֵּיהּ לָא תַּעֲבִיד בְּגִין דְּתַעְדֵי מִבֵּינָךְ, וְיִשְׁלְטוּן בָּךְ שַׂנְאָךְ, וְלָא תִּסְתַּמָר עֲלָךְ בְּגָלוּתָא. הֲדָא הוּא דִכְתִיב עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה. מַאי טַעֲמָא. בְּגִין כִּי עֶרְוַת אָבִיךָ הוּא. אַף עַל גַּב דְּאִתְרַחֲקָת מִן מַלְכָּא, אַשְׁגָּחוּתָא דְּמַלְכָּא בָּהּ תְּדִירָא, וּבַעְיָא לְאִסְתַּמְּרָא לָקֳבְלָה יַתִּיר, וְלָא תֵּיחוּב לְגַבָּהּ.</p>"],[9520012158,"<p>רִבִּי שִׁמְעוֹן פָּתַח, (דברים כ״ג:ט״ו) כִּי יְיָ' אֱלֹהֶיךָ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךָ לְהַצִּילְךָ וְגוֹ'. כִּי יְיָ' אֱלֹהֶיךָ: דָּא שְׁכִינְתָּא, דְּאִשְׁתְּכָחַת בְּהוּ בְּיִשְׂרָאֵל, וְכָּל שֶׁכֵּן בְּגָלוּתָא, לְאַגָּנָא עָלַיְהוּ תְּדִירָא מִכָּל סִטְרִין, וּמִכָּל שְׁאָר עַמִּין, דְּלָא יְשֵׁיצוּן לְהוּ לְיִשְׂרָאֵל.</p>\n<p>דְּתַנְיָא, לָא יַכְלִין <Nonei></i>שַׂנְאֵיהוֹן דְּיִשְׂרָאֵל לְאַבְאָשָׁא לְהוּ, עַד דְּיִשְׂרָאֵל מַחֲלִישִׁין חֵילָא דִּשְׁכִינְתָּא מִקַּמֵּי רַבְרְבֵי מְמָנָן דִּשְׁאָר עַמִּין. כְּדֵין יַכְלִין לְהוֹן שַׂנְאֵיהוֹן דְּיִשְׂרָאֵל, וְשַׁלְטִין עָלַיְיהוּ, וְגַזְרִין עָלַיְיהוּ כַּמָה גְּזֵירִין בִּישִׁין. וְכַד אִינּוּן תַּיְיבִין לָקֳבְלָה, הִיא מְתָבָּרַת חֵילָא וְתּוּקְפָּא דְּכָל אִינּוּן מְמָנָן רַבְרְבִין, וְתַבְרַת חֵילָא וְתּוּקְפָּא דְּשַׂנְאֵיהוֹן דְּיִשְׂרָאֵל, וְאִתְפָּרְעָא לְהוּ מִכֹּלָּא.</p>\n<p>וְעַל דָּא וְהָיָה מַחֲנֶיךָ קָדוֹשׁ, דְּבָעֵי בַּר נָשׁ דְּלָא יִסְתְּאָב בְּחוֹבוֹי, וַיַּעֲבָר עַל פִּתְגָּמֵי אוֹרַיְיתָא. דְּאִי עָבִיד הָכֵי, מְסָאֲבִין לֵיהּ, כְּמָה דִּכְתִּיב וְנִטְמֵתֶם בָּם, בְּלֹא א'. וְתָאנָא, מָאתָן וּתְמַנְיָא וְאַרְבְּעִין שַׁיְיפִין בְּגוּפָא, וְכֻלְּהוּ אִסְתַּאֲבָן, כַּד אִיהוּ אִסְתְּאַב. כְּלוֹמַר, כַּד בָּעֵי לְאִסְתַּאֲבָא. וְעַל דָּא, וְהָיָה מַחֲנֶיךָ קָדוֹשׁ. מַאי מַחֲנֶיךָ, אִלֵּין אִינּוּן שַׁיְיפֵי גּוּפָא. וְלֹא יִרְאֶה בְךָ עֶרְוַת דָּבָר, מַאי עֶרְוַת דָּבָר. עֶרְיָיתָא נוּכְרָאָה לְהַאי (ס\"א דהוי) דָּבָר רָמָז, כְּמָה דְּאוֹקִימְנָא. דְּאִי הָכִי, וְשָׁב מֵאַחֲרֶיךָ וַדַּאי. וְעַל דָּא עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה. מַאי טַעְמָא. בְּגִין דִּכְתִּיב עֶרְוַת אָבִיךָ הוּא, כְּמָה דְּאוֹקִימְנָא.</p>\n<p>תָּאנָא, עַל ג' מִלִּין מִתְעַכְּבִין יִשְׂרָאֵל בְּגָלוּתָא. עַל דְּעַבְדִין קְלָנָא בִּשְׁכִינְתָּא בְּגָלוּתָא. וּמְהַדְּרֵי אַנְפַּיְיהוּ מִן שְׁכִינְתָּא, וְעַל דִּמְסָאֲבֵי גַּרְמַיְיהוּ קָמֵי שְׁכִינְתָּא. וְכֻלְּהוּ אוֹקִימְנָא בְּמַתְנִיתָא דִּילָן.</p>"],[9520012159,"<p>רִבִּי אַבָּא, הֲוָה אָזִיל לְקַפּוּטְקִיָּא, וַהֲוָה עִמֵּיהּ רִבִּי יוֹסֵי. עַד דַּהֲווֹ אַזְלֵי, חָמוּ חַד בַּר נָשׁ, דְּהֲוָה אָתֵי, וּרְשִׁימָא חַד בְּאַנְפּוֹי. אָמַר רִבִּי אַבָּא, נִסְטֵי מֵהַאי אוֹרְחָא, דְּהָא אַנְפּוֹי דְּדֵין אַסְהִידוּ עָלֵיהּ, דְּעָבַר בְּעֶרְיָיתָא דְּאוֹרַיְיתָא, בְּגִינֵי כַּךְ אִתְרְשִׁים בְּאַנְפּוֹי. אָמַר לֵיהּ רִבִּי יוֹסֵי, אִי הַאי רְשִׁימָא הֲוָה לֵיהּ כַּד הֲוָה יַנוּקָא, מַאי עֶרְיָיתָא אִשְׁתְּכַח בֵּיהּ. אָמַר לֵיהּ, אֲנָא חֲמֵינָא בְּאַנְפּוֹי, דְּאַסְהִידוּ בְּעֶרְיָיתָא דְּאוֹרַיְיתָא.</p>\n<p>קָרָא לֵיהּ רִבִּי אַבָּא, אָמַר לֵיהּ אֵימָא מִלָּה, הַאי רְשִׁימָא דְּאַנְפָּךְ, מַה הוּא. אָמַר לוֹן, בְּמָטוֹתָא מִנַּיְיכוּ, לָא תַּעֲנְשׁוּ יַתִּיר לְהַהוּא בַּר נָשׁ, דְּהָא חוֹבוֹי קָא גָּרְמוּ לֵיהּ. אָמַר רִבִּי אַבָּא מַהוּ. אָמַר לֵיהּ, יוֹמָא חַד הֲוִינָא אָזִיל בְּאָרְחָא אֲנִי וַאֲחֹתִי, שָׁרֵינָא בְּחַד אוֹשְׁפִּיזָא, וְרָוִינָא חַמְרָא, וְכָל הַהוּא לֵילְיָא אֲחִידְנָא בַּאֲחֹתִי. בְּצַפְרָא קַמְנָא, וְאוּשְׁפִּיזָאִי קָטַט בְּחַד גַּבְרָא, עָיֵילְנָא בֵּינַיְיהוּ, וְקַטְרוּ לִי דָּא מֵהַאי גִּיסָא, וְדָא מֵהַאי גִּיסָא, וּרְשִׁימָא דָּא הֲוָה עָיֵיל לְבֵי מוֹחָא, וְאִשְׁתְּזַבְנָא עַל יְדָא דְּחַד אַסְיָיא דְּאִית בְּגַוָון.</p>\n<p>אָמַר לֵיהּ, מַאן הוּא אַסְיָיא. אָמַר לֵיהּ, רִבִּי שַׂמְלָאי הוּא. אָמַר לֵיהּ מַאי אַסוּותָא יָהַב לְךָ. אָמַר לֵיהּ אַסוּותָא דְּנַפְשָׁא. וּמֵהַהוּא יוֹמָא אַהֲדַרְנָא בִּתְשׁוּבָה. וּבְכָל יוֹמָא חֲזֵינָא אַנְפָּאִי בְּחַד חֵיזוּ, וּבָכֵינָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּהוּא רִבּוֹן עָלְמִין עַל הַהוּא חוֹבָה. וּמֵאִינּוּן דִּמְעִין אַסְחֵינָא אַנְפָּאִי. אָמַר רִבִּי אַבָּא, אִי לָאו דְּאִתְמְנַע מִנָךְ תְּשׁוּבָה, אַעְבַרְנָא מֵאַנְפָּךְ הַהוּא רְשִׁימָא. אֲבָל קָרֵינָא עָלָיךְ, (ישעיהו ו׳:ז׳) וְסָר עֲוֹנֶךָ וְחַטָּאתְך תְּכוּפָּר. אָמַר לֵיהּ, ג' זִמְנִין אֵימָא. אָמַר לֵיהּ ג' זִמְנִין, וְאִתְעֲבָר רְשִׁימָא.</p>\n<p>אָמַר רִבִּי אַבָּא, וַדַּאי מָארָךְ הָא בָּעָא לְאַעְבְּרָא מִנָךְ, דְּוַדַּאי בִּתְשׁוּבָה אִשְׁתְּכַחַת. אָמַר לֵיהּ, נָדַרְנָא מֵהַאי יוֹמָא לְאִתְעַסְּקָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא. אָמַר לֵיהּ, מַה שְׁמָךְ. אָמַר לֵיהּ אֶלְעָזָר. אָמַר לֵיהּ אֵל עָזַר, וַדַּאי שְׁמָא גָּרִים, דֶּאֱלָהָךְ סִיְּיעָךְ, וַהֲוָה בְּסָעֲדָךְ, שַׁדְרֵיהּ רִבִי אַבָּא וּבַרְכֵיהּ.</p>\n<p>לְזִמְנָא אָחֳרָא, הֲוָה רִבִּי אַבָּא אָזִיל לְגַבֵּי רַבִּי שִׁמְעוֹן, עָאל בְּמָאתֵיהּ, אַשְׁכָּחֵיהּ דְּהֲוָה יָתִיב וְדָרִישׁ, (תהילים צ״ב:ז׳) אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת. אִישׁ בַּעַר לֹא יֵדָע וְגוֹ', כַּמָה טִפְּשִׁין אִינּוּן בְּנֵי עָלְמָא, דְּלָא מַשְׁגִּיחִין וְלָא יַדְעִין וְלָא מִסְתַּכְּלִין לְמִנְדַּע אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, עַל מַה קַיְימִין בְּעָלְמָא. מַאן מְעַכֵּב לְהוּ לְמִנְדַּע, טִפְּשׁוּתָא דִּלְהוֹן. בְּגִין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּאִילּוּ הֲווֹ מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יִנְדְּעוּן אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וּכְסִיל לֹא יָבִין אֶת זֹאת, דְּלָא מִסְתָּכַל וְלָא יָדַע <Nonei></i>נִימוּסֵי דְּזֹאת בְּעָלְמָא. (דאף על גב) דְּדָאִין עָלְמָא בְּדִינוֹי וְחַמָאן לְדִינוֹי דְּהַאי זֹאת, דְּמָטָאן עַל בְּנֵי נָשָׁא דְּאִינּוּן זַכָּאִין, וְלָא מָטָאן עַל רַשִׁיעֲיָיא חַיָּיבִין, דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, דִּכְתִּיב, (תהילים צ״ב:ח׳) בִּפְרוֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. דְּהַאי עָלְמָא יָרְתִין לֵיהּ בְּכָל סִטְרוֹי, וְדִינִין לָא מָטוּן עָלוֹי בְּהַאי עָלְמָא. וְאִלְמָלֵא דְּדָוִד מַלְכָּא אוֹדְעֵיהּ בְּסוֹפֵיהּ דִּקְרָא, לָא יַדְעֵינָן, דִּכְתִּיב לְהִשָּׁמְדָם עֲדֵי עַד, לְשֵׁיצָאָה לְהוֹן מֵהַהוּא עָלְמָא, וּלְמֶהֱוִי עַפְרָא תְּחוֹת רַגְלֵיהוֹן דְּצַדִּיקַיָּיא, דִּכְתִּיב, (מלאכי ג׳:כ״א) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם.</p>\n<p>תּוּ פָּתַח וְאָמַר, (איוב ט״ז:ח׳) וַיָּקָם בִּי כַחֲשִׁי בְּפָנַי יַעֲנֶה. בְּמַאי קָא מַיְירֵי. אֶלָּא, זַכָּאָה חוּלָקֵיהּ דְּבַּר נָשׁ דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, לְמִנְדַע אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, כְּאִלּוּ אִשְׁתָּדַּל בִּשְׁמֵיהּ מַמָּשׁ. מַה שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד נִימוּסִין. אוּף אוֹרַיְיתָא הָכִי נָמֵי. תָּא חֲזֵי, הַאי מַאן דְּעָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, אוֹרַיְיתָא סַלְּקָא וְנַחְתָּא וְעַבְדָא בֵּיהּ בְּבַּר נָשׁ רְשִׁימִין בְּאַנְפּוֹי, בְּגִין דְּיִסְתַּכְּלוּן בֵּיהּ עִלָּאֵי וְתַתָּאֵי, וְכֻלְּהוּ אוֹשְׁדָן לְוָוטִין עַל רֵישֵׁיהּ.</p>\n<p>וְתָאנָא, כָּל אִינּוּן עֵינֵי יְיָ', דְּאַזְלִין וְשָׁאטִין בְּעָלְמָא לְמִנְדַּע אוֹרְחוֹי דִּבְנֵי נָשָׁא, כֻּלְּהוֹן זַקְפִין עַיְינִין, וּמִסְתַּכְּלִין בְּאַנְפּוֹי דְּהַהוּא בַּר נָשׁ, וְחָמָאן לְהוּ, וְכֻלְּהוּ פַּתְחִין עָלֵיהּ וַוי וַוי. וַוי לֵיהּ בְּהַאי עָלְמָא, וַוי לֵיהּ בְּעָלְמָא דְּאָתֵי. אִסְתְּלָקוּ מִסּוֹחֲרָנֵיהּ דִּפְלַנְיָא, דְּהָא סַהֲדוּתָא בְּאַנְפּוֹי, וְרוּחָא דִּמְסָאֲבָא שַׁרְיָא עֲלוֹי. וְכָל אִינּוּן יוֹמִין דְּאִשְׁתְּכַח רְשִׁימוּ בְּאַנְפּוֹי לְסַהֲדוּתָא, אִי אוֹלִיד בַּר, אַשְׁלִיף לֵיהּ רוּחָא מִסִּטְרָא דִּמְסָאֲבָא. וְאִלֵּין אִינּוּן חַיָּיבֵי דָּרָא, תַּקִיפֵי אַנְפִּין, דְּמָארֵיהוֹן שָׁבִיק לְהוֹן בְּהַאי עָלְמָא, לְשֵׁיצָאָה לְהוּ בְּעָלְמָא דְּאָתֵי.</p>\n<p>תָּנֵינָן, הַאי צַדִּיקָא זַכָּאָה דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא מָשִׁיךְ עָלֵיהּ חַד חוּטָא דְּחֶסֶד, וְאִתְרְשִׁים לֵיהּ בְּאַנְפּוֹי, וּמֵהַהוּא רְשִׁימָא דַּחֲלֵי עִלָּאֵי וְתַתָּאֵי. הָכִי נָמֵי מַאן דְּעָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, מַשְׁכָאן עָלֵיהּ רוּחָא דִּמְסָאֲבָא, וְאִתְרְשִׁים לֵיהּ בְּאַנְפּוֹי, וּמִנֵּיהּ עַרְקִין עִלָּאֵי וְתַתָּאֵי. וְכֹלָּא מַכְרְזֵי עָלֵיהּ, אִסְתְּלָקוּ מִסָּחֲרָנֵיהּ דִּפְלַנְיָא, דְּעָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, וְעַל פִּקּוּדֵי דְּמָארֵיהּ, וַוי לֵיהּ, וַוי לְנַפְשֵׁיהּ. הַאי אַשְׁלִיף רוּחָא דִּמְסָאֲבָא, דְּאִשְׁתְּכַח עִמֵּיהּ, וְאוֹרִית לֵיהּ לִבְרֵיהּ, וְהַאי הוּא דְקוּדְשָׁא בְּרִיךְ הוּא לֵית לֵיהּ בֵּיהּ חוּלָקָא, וְשָׁבִיק לֵיהּ, לְשֵׁיצָאָה לֵיהּ לְעָלְמָא דְּאָתֵי.</p>\n<p>אָמַר לֵיהּ רִבִּי אַבָּא, שַׁפִּיר קָאַמְרַת, מְנָא לָךְ הַאי. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא. וְאוֹלִיפְנָא, דְּהַאי יְרוּתָא בִּישָׁא, אַחֲסִינוּן כֻּלְּהוּ בְּנוֹי, אִי לָא יְתוּבוּן, דְּהָא לֵית מִלָּה קַיְּימָא קָמֵי תְּשׁוּבָה. וַאֲנָא הָכִי אוֹלִיפְנָא, דְּאַסוּותָא דָּא יָהֲבוּ לִי זִמְנָא חֲדָא, דַּהֲוִינָא רְשִׁים בְּאַנְפָּאי, וְיוֹמָא חַד הֲוִינָא אָזִיל בְּאוֹרְחָא, וְאִעַרְעָנָא בְּחַד זַכָּאָה, וְעַל יְדוֹי אִתְעַבָּר מִנַּאי הַהוּא רְשִׁימָא. אָמַר לִי, מַה שְׁמָךְ. אָמַר לֵיהּ אֶלְעָזָר, וְקָרֵי עָלַי אֶלְעָזָר אָחֳרָא. אָמַר לֵיהּ, בְּרִיךְ רַחֲמָנָא, דַּחֲמֵינָא לָךְ, וְזָכֵינָא לְמֵחֱמֵי לָךְ בְּהַאי. זַכָּאָה חוּלָקָךְ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, (אמר ליה) אֲנָא הוּא דְּאִעְרַעְנָא לָךְ.</p>\n<p>אִשְׁתָּטַּח קָמֵיהּ, אַיְיתֵיהּ לְבֵיתֵיהּ, אַתְקִין קָמֵיהּ קוּרְטִיסָא (ס\"א טרכוסא) (טרטיסאי) דְּנַהֲמָא, וּבִשְׂרָא דְּעֶגְלָא תְּלִיתָאָה. בָּתַר דְּאָכְלוּ, אָמַר לֵיהּ הַהוּא גַּבְרָא, רִבִּי, אֵימָא לִי חַד מִלָּה, חָדָּא תּוֹרָתָא סוּמָקָא אִית לִי, אִימָּא דְּעֶגְלָא דְּבִישְׂרָא דָּא דַּאֲכִילְנָא, וְיוֹמָא חַד עַד לָא אִתְעַבְּרַת וְאוֹלִידַת, אֲזִילְנָא בַּתְרָאָה לְמַרְעָא לְמַדְבְּרָא, עַד דְּדָבַּרְנָא לָהּ אַעְבָּר קָמַאי חַד גַּבְרָא, אָמַר לֵיהּ, מַה שְׁמָהּ דְּתוֹרָתָא דָּא. אֲמֵינָא, מִן יוֹמָא דְּאִתְיְילִידַת לָא קָרֵינָּא לָהּ בִּשְׁמָא. אָמַר לֵיהּ, בַּת שֶׁבַע אֵם שְׁלֹמֹה אִתְקְרֵי, אִי תִּזְכֶּה לְכַפָּרָה. וַאֲנָא בְּעוֹד דְּאָהָדַרְנָא רֵישָׁאי, לָא חֲמֵינָא לֵיהּ, וְחָיִיכְנָא מֵהַהוּא מִלָּה.</p>\n<p><Nonei></i>וְהַשְׁתָּא דְּזָכִינָא בְּאוֹרַיְיתָא, אִתְּעַרְנָא עַל הַהִיא מִלָּה, וּמִן יוֹמָא דְּאִתְפְּטָר רִבִּי שַׂמְלָאי מֵהָכָא, לָא הֲוָה בַּר נָשׁ דְּיַנְהִיר לָן בְּאוֹרַיְיתָא כְּוָותֵיהּ. וַאֲנָא דָּחִילְנָא לְמֵימַר מִלָּה דְּאוֹרַיְיתָא דְּלָא אוֹלִיפְנָא. וּמִלָּה דָּא דְּאִסְתַּכַּלְנָא דְּמִלָּה דְּחָכְמְתָא הִיא, וְלָא יְדַעְנָא. אָמַר לֵיהּ, וַדַּאי מִלָּה דְּחָכְמְתָא הִיא, וּרְמִיזָא עִלָּאָה הִיא לְעֵילָּא וּלְתַתָּא.</p>"],[9520012160,"<p>אֲבָל תָּא חֲזֵי, בַּת שֶׁבַע אִתְקְרֵי מַמָּשׁ בְּרָזָא דְּחָכְמְתָא. בְּגִין כָּךְ כְּתִיב בָּהּ כֹּלָּא בְּשֶׁבַע. ז' פָּרוֹת. ז' שְׂרֵפוֹת. ז' הֲזָאוֹת. ז' כִּבּוּסִים. ז' טְמֵאִים. ז' טְהוֹרִים. ז' כֹּהֲנִים. וּמֹשֶׁה וְאַהֲרֹן בְּחוּשְׁבְּנָא דְּהָא כְּתִיב, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה וְאַהֲרֹן וְגוֹ'. וְשַׁפִּיר קָאָמַר הַהוּא גַּבְרָא, דְּאָמַר בַּת שֶׁבַע, וְכֹלָּא רָזָא דְּחָכְמְתָא הִיא.</p>\n<p>אָמַר לֵיהּ, בְּרִיךְ רַחֲמָנָא דְּשָׁמַעְנָא מִלָּה דָּא. בְּרִיךְ הוּא דְּהָא אַקְדִּים לִי שְׁלָם בְּקַדְמִיתָא, לְמִזְכֵּי לְהַאי. דִּכְתִּיב (ישעיהו נ״ז:י״ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב אָמַר יְיָ'. אֲנָא כַּד הֲוִינָא רָחוֹק, קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים לִי שְׁלָם לְמֶהֱוִי קָרוֹב. קָרָא עָלֵיהּ רִבִּי אַבָּא, (שמואל א כ״ה:ו׳) אַתָּה שָׁלוֹם וּבֵיתְךָ שָׁלוֹם וְכֹל אֲשֶׁר לְךָ שָׁלוֹם.</p>"],[9520012161,"<p>(ויקרא ח\"י) עֶרְוַת אֲחוֹת אָבִיךָ לֹא תְגַלֵּה. רִבִּי חִיָּיא פָּתַח, וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחוֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְרָאָה אֶת עֶרְוָתָהּ וְגוֹ'. תַּמָּן תָּנֵינָן, מְאָה וּתְלָתִין שְׁנִין, אִתְפְּרַשׁ אָדָם מְאִתְּתֵיהּ, וְלָא הֲוָה אוֹלִיד. מִדְּקָטַל קַיִן לְהֶבֶל, לָא בָּעָא אָדָם לְאִזְדַּוְּוגָא בְּאִתְּתֵיהּ. רִבִּי יוֹסֵי אָמַר, מִשַׁעֲתָא דְּאִתְגְּזַר עָלֵיהּ וְעַל כָּל עָלְמָא מִיתָה, אָמַר, אֲמַאי אֲנָא אוֹלִיד לִבְעַתּוּתָא. מִיַּד אִתְפְּרַשׁ מֵאִתְּתֵיהּ.</p>\n<p>וּתְרֵין רוּחִין נוּקְבִין, הֲווֹ אַתְיָין וְאִזְדַּוְּוגָן עִמֵּיהּ, וְאוֹלִידוּ. וְאִינּוּן דְּאוֹלִידוּ הֲווֹ מַזִּיקִין דְּעָלְמָא, וְאִקְרוּן נִגְעֵי בְּנֵי אָדָם. וְאִלֵּין סָאטָן לִבְנֵי אָדָם, וְשַׁרְיָין בְּפִתְחָא דְּבֵיתָא, וּבְבִירָאֵי, וּבְבָתֵּי כִּסְאֵי. וְעַל דָּא בַּר נָשׁ, דְּאִשְׁתְּכַח בְּפִתְחָא דְּבֵיתֵיהּ שְׁמָא קַדִּישָׁא שַׁדַּי בְּכִתְרִין עִלָּאִין, כֻּלְּהוּ עַרְקָאן וְאִתְרַחֲקָן מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י׳) וְנֶגַע לָא יִקְרַב בְּאָהֳלֶךָ. מַאי וְנֶגַע לָא יִקְרַב. אִלֵּין נִגְעֵי בְּנֵי אָדָם.</p>\n<p>וְתָאנָא, בְּשַׁעֲתָא דְּנָחַת אָדָם בְּדִיּוּקְנָא עִלָּאָה, בְּדִיּוּקְנָא קַדִּישָׁא, וְחָמוּ לֵיהּ עִלָּאֵי וְתַתָּאֵי, כֻּלְּהוּ קְרִיבוּ גַּבֵּיהּ, וְאַמְלְכוּהוּ עַל הַאי עָלְמָא. בָּתַר דְּאָתָא חִוְיָא עַל חַוָּה, וְאָטִיל בָּהּ זוּהֲמָא, לְבָתַר אוֹלִידַת קַיִן. (בראשית קע\"ח ע\"א) מִתַּמָּן (ס\"א נתייחסו) נִתְחַיְיבוּ כָּל דָּרִין חַיָּיבִין דְּעָלְמָא. וּמָדוֹרָא דְּשֵׁדִין וְרוּחִין, מִתַּמָּן אִשְׁתְּכָחוּ, וּמִסִּטְרוֹי. וּבְגִּינֵי כַּךְ כָּל רוּחִין וְשֵׁדִין, פַּלְגּוּתָא אִית בְּהוּ מִבְּנֵי נָשָׁא דִּלְתַתָּא, וּפַלְגּוּתָא מִמַּלְאֲכֵי עִלָּאֵי דִּלְעֵילָּא. וְכֵן כַּד אִתְיְילִידוּ מֵאָדָם אִינּוּן אָחֳרָנִין, כֻּלְּהוּ אִשְׁתְּכָחוּ כְּהַאי גַּוְונָא, פַּלְגוּ מִתַּתָּאֵי, וּפַלְגּוּ מֵעִלָּאֵי.</p>\n<p>בָּתַר דְּאִתְיְילִידוּ מֵאָדָם, (ס\"א אהדרו ליה קצת מאינון רוחין דנפקו מתיאובתיה בחלמא) אוֹלִיד מֵאִינּוּן רוּחֵי בְּנָתָן, דְּדַמְיָן לִשְׁפִּירוּ דְּעִלָאֵי, וּלִשְׁפִּירוּ דְּתַתָּאֵי. וְעַל דָּא כְּתִיב, (בראשית ו׳:ב׳) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טוֹבוֹת הֵנָּה וְגוֹ', וְטָעָן כֹּלָּא בַּתְרַיְיהוּ. וְחַד דְּכוּרָא אִשְׁתְּכַח, דְּאָתָא לְעָלְמָא מִרוּחֵיהּ דְּסִטְרָא דְּקַיִן, וְקָרוּן לֵיהּ תּוּבַל קַיִן. וַחֲדָא נוּקְבָּא נָפְקַת עִמֵּיהּ, וַהֲווּ בִּרְיָין וְטָעָאן בַּתְרָאָה, וְאִתְקְרֵי נַעֲמָ\"ה. מִינָּהּ נַפְקוּ רוּחִין וְשֵׁדִין אָחֳרָנִין. וְאִינּוּן (בראשית צ\"ב ע\"א, י\"ו ע\"א, קמ\"ג ע\"ב, ר\"ה ע\"א) תַּלְיָין בַּאֲוִירָא, וְאוֹדְעִין מִלִּין לְאִינּוּן אָחֳרָנִין דִּשְׁכִיחִין לְתַתָּא.</p>\n<p>וְדָא תּוּבַל קַיִן, אַפִּיק זַיְינֵי קִטּוּלָא לְעָלְמָא. וְדָא נַעֲמָה אִתְרְגִישַׁת בְּרִיגְשָׁהָא, וְאִתְדַּבְּקַת בְּסִטְרָהָא. וְעַד כְּעַן הִיא קַיְּימָא, וּמָדוֹרָהָא בֵּין רִיגְשֵׁי יַמָּא רַבָּא, וְנַפְקַת וְחַיְּיכַת בִּבְנֵי נָשָׁא, וְאִתְחַמְּמַת מִנַּיְיהוּ בְּחֶלְמָא, בְּהַהוּא תִּיאוּבְתָּא דְּבַּר נָשׁ, וְאִתְדַּבְּקַת בֵּיהּ. תִּיאוּבְתָּא נַטְלַת וְלָא יַתִּיר. וּמֵהַהוּא תִּיאוּבְתָּא אִתְעַבְּרַת, וְאַפִּיקַת זַיְנִין אָחֳרָנִין לְעָלְמָא.</p>\n<p>וְאִלֵּין בְּנִין דְּאוֹלִידַת מִבְּנֵי נָשָׁא, מִשְׁתַּכְּחִין לָקֳבְלֵי נוּקְבֵי בְּנֵי נָשָׁא, וּמִתְעַבְּרָן מִנַּיְיהוּ, וְאוֹלִידָן רוּחִין, וְכֻלְּהוּ אַזְלִין לְלִילִית קַדְמִיתָא, וְהִיא מְגַדֶּלֶת לוֹן. וְהִיא נַפְקַת לְעָלְמָא, וּבַעְיָא <Nonei></i>רַבְיָיהָא, וְחָמַת רַבְיֵי בְּנֵי נָשָׁא, וְאִתְדַּבְּקַת בְּהוּ, לְקָטְלָא לְהוּ, וּלְאִשְׁתְּאֲבָא בְּרוּחַיְיהוּ דְּרַבְיֵי בְּנֵי נָשָׁא וְהִיא אַזְלַת בְּהַהוּא רוּחָא (נ\"א רביא), וְאִזְדַמְּנָן תַּמָּן ג' רוּחִין קַדִּישִׁין, וְטָאסִין קַמָּהּ, וְנַטְלִין הַהוּא רוּחָא (נ\"א רביא) מִנָּהּ, וּמַנִיחִין לֵיהּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְתַמָּן מִתְגַּלְּפֵי (ס\"א מתאלפי) קַמֵּיהּ.</p>"],[9520012162,"<p>בְּגִינֵי כַּךְ אוֹרַיְיתָא אַזְהֲרַת לְהוּ לִבְנֵי נָשָׁא, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים וַדַּאי. אִי אִשְׁתְּכַח בַּר נָשׁ קַדִּישָׁא, לָא מִסְתָּפֵי מִינָּהּ, דִּכְדֵין זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִלֵּין ג' מַלְאֲכִין קַדִּישִׁין דְּאַמָרָן, וְנַטְרִין לֵיהּ לְהַהוּא רַבְיָיא, וְהִיא לָא יַכְלָא לְאַבְאָשָׁא לֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י׳) לֹא תְאוּנֶּה אֵלֶיךָ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךָ. מַאי טַעֲמָא לֹא תְאוּנֶּה אֵלֶיךָ רָעָה. בְּגִין כִּי מַלְאָכָיו יְצַוְּה לָּךְ, וּכְתִיב (תהלים צ) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ.</p>\n<p>דְּאִי בַּר נָשׁ לָא אִשְׁתְּכַח קַדִּישָׁא, וְאַשְׁלִיף רוּחָא מִסִּטְרָא דִּמְסָאֲבָא, כְּדֵין הִיא אַתְיָא וְחַיְּיכַת בֵּיהּ בְּהַהוּא רַבְיָא. וְאִי קַטִּילַת לֵיהּ, אִשְׁתְּאֲבַת בְּהַהוּא רוּחָא, וְלָא תַּעְדֵי מִנֵיהּ לְעָלְמִין. וְאִי תֵּימָא אִינּוּן אָחֳרָנִין, דְּקַטִּילַת לוֹן, וְאִזְדָּמְנוּ קַמָּהּ אִינּוּן תְּלָתָא קַדִּישִׁין, וְנַטְלִין מִנָּהּ הַהוּא רוּחָא, הָא לָא בְּסִטְרָא דִּמְסָאֲבָא אִשְׁתְּכָחוּ, אֲמַאי שַׁלְטָא לְקָטְלָא לְהוּ. אֶלָּא, הַאי כַּד בַּר נָשׁ לָא אִתְקַדָּשׁ, אֲבָל לָא אִתְכַּוָּון לְאִסְתַּאֲבָא וְלָא אִסְתְּאַב, בְּגִין כַּךְ יַכְלָא לְשַׁלְּטָאָה בְּגוּפָא, וְלָא בְּרוּחָא.</p>\n<p>וְזִמְנִין אִשְׁתְּכַח דְּנָפְקָת נַעֲמָה לְעָלְמָא, לְאִתְחַמְמָא מִבְּנֵי נָשָׁא, ואִשְׁתְּכַח בַּר נָשׁ בְּקִשְׁרָא (נ\"א בקשויא) דְּתִיאוּבְתָא עִמָּהּ, וְאִתְּעַר מִשֵּׁנָתֵיהּ, וְאָחִיד בְּאִנְתְּתֵיהּ, וְשָׁכִיב עִמָה, וּרְעוּתָא דִילֵיה בְּהַהוּא תִיאוּבְתָא דְּהַוִה לְיֵהּ בְּחַלְמֵיה, כְּדֵין הַהוּא בַּר דְּאוֹלִיד, מִסִּטְרָא דְּנַעֲמָה קָא אַתְיָא, דְּהָא בְּתִיאוּבְתָּא דִּילָהּ אִשְׁתְּכַח הַאי, כַּד נַפְקָא לִילִי\"ת וְחָמָאת לֵיהּ, יַדְעַת מִלָּה, וְהִיא אִתְקְטָרַת בֵּיהּ, וּמַגְדְּלַת לֵיהּ כְּאִינּוּן אָחֳרָנִין בְּנוֹי דְּנַעֲמָ\"ה, וְאִשְׁתְּכָחַת עִמֵּיהּ זִמְנִין סַגִּיאִין, וְלָא קַטָלָא לֵיהּ.</p>\n<p>הַאי הוּא בַּר נָשׁ, דִּבְכָל סִיהֲרָא וְסִיהֲרָא אִתְפְּגִים, וְלָא אִתְיָאֲשָׁא מִנֵּיהּ לְעָלְמִין, דְּהָא בְּכָל סִיהֲרָא וְסִיהֲרָא כַּד אִתְחַדְּשָׁא בְּעָלְמָא, לִילִי\"ת נָפְקָא, וּפַקְדָּא עַל כֻּלְּהוּ דְּהִיא מַגְדְּלַת, וְחַיְּיכָא בְּהוּ, וּכְדֵין הַהוּא בַּר נָשׁ פָּגִים בְּהַהוּא זִמְנָא, זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּמִתְקַדְּשֵׁי בִּקְדוּשָּׁה דְּמַלְכָּא, עָלַיְיהוּ כְּתִיב (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ וְגוֹ'.</p>\n<p>מִלִּין אִלֵּין גַּלֵּי שְׁלֹמֹה מַלְכָּא, בְּסִפְרָא דְּאַשְׁמְדָאי מַלְכָּא, וְאַשְׁכַּחְנָא בֵּיהּ (ע\"ט ע\"א) אֶלַף וְאַרְבַּע מְאָה וַחֲמֵשׁ זִינֵי מְסַאֲבוּתָא, דְּמִסְתַּאֲבֵי בְּהוּ בְּנֵי נָשָׁא. דְּגַלֵּי דָּא אַשְׁמְדָאי לִשְׁלֹמֹה מַלְכָּא.</p>\n<p>וַוי לְהוּ לִבְנֵי נָשָׁא, דְּכֻלְּהוּ אֲטִימִין וּסְתִימִין עַיְינִין, וְלָא יַדְעִין, וְלָא שַׁמְעִין, וְלָא מַשְׁגִּיחִין, הֵיךְ קַיְימִין בְּעָלְמָא. וְהָא עֵיטָא וְאַסְווּתָא קָמַיְיהוּ, וְלָא מִסְתַּכְּלִין. דְּהָא לָא יַכְלִין בְּנֵי נָשָׁא לְאִשְׁתְּזָבָא, אֶלָּא בְּעֵיטָא דְּאוֹרַיְיתָא. דִּכְתִּיב, (דברים כ״ג:י״א) כִּי יִהְיֶה בְךָ אִישׁ אֲשֶׁר לֹא יִהְיֶה טָהוֹר מִקְּרֵה לָיְלָה. אֲשֶׁר לֹא יִהְיֶה טָהוֹר דַּיְיקָא, מִקְּרֵה לָיְלָה דַּיְיקָא, וְהָא אוֹקִימְנָא מִלֵּי, בְּעֵיטָא דְּאוֹרַיְיתָא קַדִּישָׁא. דְּהָכִי כְּתִיב בְּאוֹרַיְיתָא קַדִּישָׁא, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי אֲנִי יְיָ' אֱלֹהֵיכֶם.</p>"],[9520012163,"<p>תָּאנָא, בָּתַר דְּאִסְתָּלָקוּ קַיִן וְהֶבֶל, אִתְהַדָּר אָדָם לְאִנְתְּתֵיהּ, וְאִתְלָבָּשׁ בְּרוּחָא אָחֳרָא, וְאוֹלִיד לְשֵׁת. מִכָּאן אִתְיַיחֲסוּ דָּרֵי דְּצַדִּיקַיָּיא בְּעָלְמָא. וְאַסְגֵּי קוּדְשָׁא בְּרִיךְ הוּא חֶסֶד בְּעָלְמָא, וּבְכָל חַד אִתְיְילִידַת נוּקְבָּא עִמֵּיהּ, לְאִתְיַישְּׁבָא עָלְמָא כְּגַוְונָא דִּלְעֵילָּא. וְהָא אוּקְמוּהָ חַבְרַיָּיא בִּסְתִּימָאָה דְּמַתְנִיתִין, דִּכְתִּיב, (ויקרא כ׳:י״ז) וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחוֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְגוֹ', חֶסֶד הוּא. חֶסֶד הוּא ודַּאי, וּבָתַר דְּשָׁארִי חֶסֶד, גִּזְעִין וְשָׁרָשִׁין נָפְקִין מִתְּחוֹת לְעֵילָּא, וְאִתְפָּרְשָׁן עַנְפִּין, וְקָרִיב אִתְרְחַק. כְּדֵין עַנְפָּא אַסְגֵּי, וְאָתֵי לְאִתְחַבְּרָא בְּזִוּוּגָא חַד בְּאִילָנָא. הַאי בְּקַדְמִיתָא, הַאי בִּסְתִּימָא דְּעָלְמָא. בְּגִין דִּכְתִּיב, (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִכָּאן וּלְהָלְאָה בְּנֵי נָשָׁא דְּיִשְׁתַּכְחוּן בֵּיהּ, וְנִכְרְתוּ לְעֵינֵי בְּנֵי עַמָּם.</p>"],[9520012164,"<p><Nonei></i>תָּאנָא עֶרְוַת אֲחוֹת אָבִיךָ, כְּמָה דְּאִתְגַּלְיָיא בִּסְתִּימָא. כְּתִיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ' וְצַדִּיקִים יֵלְכוּ בָם וְגוֹ', זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּיַדְעֵי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאַזְלִין בְּהוּ, וְאִשְׁתְּמוֹדְעָן גַּבַּיְיהוּ. זַכָּאָה חוּלָקֵיהוֹן.</p>\n<p>תָּאנָא, אִתְעַבְּרַת הֵ\"א עִלָּאָה בִּרְחִימוּתָא וַחֲבִיבוּתָא דְּלָא מִתְפְּרַשׁ מִנָּהּ יוֹ\"ד לְעָלְמִין. אִתְעַבְּרַת וְאַפִּיקַת וָא\"ו, לְבָתַר קָאִים קַמָּהּ, וְיַנְקָא לֵיהּ. וְדָא (נ\"א ודאין בעלמא) וָא\"ו כַּד נָפְקָא, בַּת זוּגוֹ נַפְקָא עִמֵּיהּ. אַתְיָא חֶסֶד אִתְּעַר גַּבֵּיהּ, וּפָרִישׁ לוֹן, וְנַפְקוּ גִּזְעִין מִתְּחוֹת לְעֵילָּא, וְאִתְפָּשָּׁטוּ עַנְפִין, וְאַסְגִּיאוּ, וְאִתְעָבִידַת הֵ\"א תַּתָּאָה. וְאִתְרַבִּיאַת בְּעַנְפָּהָא לְעֵילָּא לְעֵילָּא, עַד דְּאִזְדַּוְּוגַת בְּאִילָנָא עִלָּאָה, וְאִתְחַבָּרוּ וָא\"ו עִם הֵ\"א, מַאן גָּרִים לוֹן. חֶסֶד הוּא. חֶסֶד הוּא וַדַּאי. דְּחִבֵּר לוֹן כַּחֲדָא.</p>\n<p>יוֹ\"ד עִם הֵ\"א עִלָּאָה. לָא תַּלְיָא חִבּוּרָא דִּלְהוֹן בְּחֶסֶד, אֶלָּא בְּמַזָּלָא תַּלְיָיא חִבּוּרָא דִּלְהוֹן, וַחֲבִיבוּתָא דִּלְהוֹן, דְּלָא (ס\"א ע\"ב) מִתְפָּרְשָׁן לְעָלְמִין. יוֹ\"ד אִתְקָשַׁר בְּהֵ\"א, וְהֵ\"א אִתְקָשַׁר בְּוָא\"ו, וָא\"ו אִתְקָשַׁר בְּהֵ\"א, וְהֵ\"א אִתְקָשַׁר בְּכֹלָּא. וְכֹלָּא חַד קִשּׁוּרָא הוּא, וְחַד מִלָּה. לָא אִתְפְּרָשׁוּ דָּא מִן דָּא לְעָלְמִין. כִּבְיָכוֹל, מַאן דְּגָרִים פִּרוּדָא, כְּאִלּוּ חָרִיב עָלְמָא, וְאִקְרֵי עֶרְיָיתָא דְּכֹלָּא.</p>"],[9520012165,"<p>וּלְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאָתָבָא שְׁכִינְתָּא לְאַתְרָהָא, וּלְאִשְׁתַּכְּחָא כֹּלָּא בְּזִוּוּגָא חַד דִּכְתִּיב (זכריה י״ד:כ׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וְגוֹ'. וְאִי תֵּימָא הַשְׁתָּא לָאו הוּא אֶחָד. לָא, דְּהָא הַשְׁתָּא חַיָּיבֵי עָלְמָא גָּרְמוּ, דְּלָא אִשְׁתְּכַח חַד. דְּהָא מַטְרוֹנִיתָא אִתְרָחֲקַת מִן מַלְכָּא, וְלָא מִשְׁתַּכְּחֵי בְּזִוּוּגָא. אִמָּא עִלָּאָה אִתְרָחֲקַת מִן מַלְכָּא וְלָא יַנְקָא לֵיהּ.</p>\n<p>בְּגִין דְּמַלְכָּא בְּלָא מַטְרוֹנִיתָא, לָא מִתְעַטֵּר בְּעִטְרוֹי עִמָּהּ (ס\"א דאמא), כְּמָה בְּקַדְמִיתָא כַּד אִתְחַבָּר בְּמַטְרוֹנִיתָא, דְּעַטְּרָא לֵיהּ, בְּכַמָּה עִטְרִין, בְּכַמָּה זְהִירִין בְּעִטְרִין קַדִּישִׁין עִלָּאִין. דִּכְתִּיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן (ס\"א ע\"ב, שמות פ\"ד ע\"א) בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ', דְּאִזְדְּוַּוג בְּמַטְרוֹנִיתָא, כְּדֵין עַטְּרָא לֵיהּ אִימָּא עִלָּאָה כְּדְקָא יֵאוֹת. וְהַשְׁתָּא דְּלָא אִשְׁתְּכַח מַלְכָּא בְּמַטְרוֹנִיתָא, כְּדֵין אִימָּא עִלָּאָה נַטְלַת כִּתְרָאָה (נ\"א עטראה) וּמָנָעַת מִנֵּיהּ מַבּוּעֵי דְּנַחֲלִין, וְלָא אִשְׁתְּכַח בְּקִשּׁוּרָא חַד. כִּבְיָכוֹל לָא אִשְׁתְּכַח חַד.</p>\n<p>וּבְזִמְנָא דְּתֵיתוּב מַטְרוֹנִיתָא לַאֲתַר הֵיכָלָא, וּמַלְכָּא יִזְדַּוִּוג עִמָּהּ בְּזִוּוּגָא חַד. כְּדֵין, יִתְחַבָּר כֹּלָּא כַּחֲדָא, בְּלָא פִּרוּדָא, וְעַל דָּא כְּתִיב, בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד. בַּיוֹם הַהוּא: בְּזִמְנָא (קע\"א) דִּיְתוּב מַטְרוֹנִיתָא לְהֵיכָלָא, כְּדֵין כֹּלָּא אִשְׁתְּכַח חַד בְּלָא פִּרוּדָא. וּכְדֵין (עובדיה א׳:כ״א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפּוֹט וְגוֹ'.</p>\n<p>דְּתַנְיָא, אָמַר רִבִּי שִׁמְעוֹן, לָא תֵּיעוּל מַטְרוֹנִיתָא בְּחֶדְוָותָא בְּהֵיכָלֵיהּ עַד דְּיִתְדָּן מַלְכוּתָא דְּעֵשָׂו, וְתִיסַב מִנֵּיהּ נוּקְמִין דְּגַרְמָא כָּל הַאי. לְבָתַר תִּזְדַּוִּוג בְּמַלְכָּא, וִיהֵא חֵדוּ שְׁלִים, הֲדָא הוּא דִכְתִיב, וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפּוֹט אֶת הַר עֵשָׂו בְּקַדְמִיתָא, וּלְבָתַר וְהָיְתָה לַיְיָ' הַמְּלוּכָה. מַאן מְלוּכָה, דָּא מַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב, וְהָיְתָה לַיְיָ' הַמְּלוּכָה. וּלְבָתַר דְּיִזְדַּוְּוגֻן כַּחֲדָא, מַה כְּתִיב. וְהָיָה יְיָ' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9520012166,"<p>(ויקרא ח\"י) עֶרְוַת אֲחִי אָבִיךָ לֹא תְגַלֵּה. תָּאנֵי רִבִּי יְהוּדָה, דָּא יִשְׂרָאֵל לְתַתָּא. וַאֲחוֹת אִמְּךָ: דָּא יְרוּשָׁלַם דִּלְתַתָּא. דִּבְחוֹבִין אִלֵּין, יִגְלוּן יִשְׂרָאֵל בֵּינֵי עֲמְמַיָיא, וְיִתְחֲרִיב יְרוּשָׁלַ ם לְתַתָּא. וְעַל דָּא תָּנֵינָן, רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּקָרָא לְיִשְׂרָאֵל אַחִים, שֶׁנֶּאֱמַר (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא וְגוֹ'. (ואוקימנא מילין ותמן (ס\"א מילי תמן) בת בנה ובת בתה וכו' ואף על גב דאינון באתגלייא ובאתכסיא וכן בתריה. דהא עלמא איצטריך לון, ואינון ישובא דעלמא כמה דכתיב (משלי כ\"ז) רעך ורע אביך) וְהַאי רָזָא דְמִלָה. דְּאָמַר רַבִּי שִׁמְעוֹן</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי אַחַי לָמָּה רֵעַי, וְאִי רֵעַי לָמָּה אַחַי. אֶלָּא תָּאנָא, הַהוּא מִלָּה דְּלָא אִתְעָדֵי לְעָלְמִין, אִקְרֵי רֵעַ, כְּמָה דְאַתְּ אָמֵר רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב. וְהַאי רָזָא דְּמִלָּה דְּאָמַר רַבִּי שִׁמְעוֹן, אִימָא עִלָּאָה, רַעְיָא אִקְרֵי, בְּגִין דְּלָא אִתְעָדֵי (ס\"א ע\"ב) רְחִימוּתָא דְּאַבָּא מִנָּהּ <Nonei></i>לְעָלְמִין. וְאִימָא תַּתָּאָה כַּלָה אִקְרֵי, וְאִקְרֵי אֲחוֹת, כְּמָה דְּאוֹקִימְנָא (שיר השירים ח׳:ח׳) אֲחוֹת לָנוּ קְטַנָּה.</p>\n<p>וְהַיְינוּ סְתָם מַתְנִיתָא דִּילָן, דִּכְתִּיב הָכָא, עֶרְוַת אֲחוֹתְךָ בַת אָבִיךָ אוֹ בַת אִמֶּךָ, כֵּיוָן דְּאָמַר בַת אָבִיךָ, מַאי אוֹ בַת אִמֶּךָ. אֶלָּא, אִי מִסִּטְרָא דְּאַבָּא אִשְׁתְּכַחַת, חָכְמָה אִתְקְרֵי. וְאִי מִסִּטְרָא דְּאִימָא, בִּינָה אִתְקְרֵי. וְעַל כָּל פָּנִים בֵּין הַאי וּבֵין הַאי, מֵאִימָא וְאַבָּא אִשְׁתְּכַחַת. דְּהָא יוֹ\"ד לָא אִתְעָדֵי מִן ה' לְעָלְמִין. וְדָא הוּא רָזָא דְּמִלָּה, מוֹלֶדֶת בַּיִת: מִסִּטְרָא דְּאַבָּא. אוֹ מוֹלֶדֶת חוּץ: מִסִּטְרָא דְּאִימָא.</p>"],[9520012167,"<p>רִבִּי אַבָּא אָמַר, (משלי כ״ד:ג׳) בְּחָכְמָה יִבָּנֶה בָּיִת, מַאן הוּא בַּיִת דְּאִתְבְּנֵי בְּחָכְמָה. הֲוִי אֵימָא דָּא נָהָר דְּנָפִיק מְעֵדֶן, בְּגִינֵי כַּךְ מוֹלֶדֶת בַּיִת. אוֹ מוֹלֶדֶת חוּץ. כַּד נַפְקַת מִן ו', כְּמָה דִּכְתִּיב, (בראשית ב׳:כ״ג) עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי. וּכְתִיב (בראשית ב׳:כ״א) וַיִקַּח אַחַת מִצַּלְעוֹתָיו, וְדָא הוּא מוֹלֶדֶת חוּץ, מֵאֲתַר דִּזְעֵיר אַנְפִּין אִשְׁתְּכַח, כְּמָה דְּאִתְּמַר.</p>\n<p>וְעַל דָּא אָמַר רִבִּי יְהוּדָה, יִשְׂרָאֵל אָחִין אִקְרוּן לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא אַעְדֵּי רְחִימוּתָא דִּלְהוֹן לְעָלְמִין. יְרוּשָׁלַם דִּלְתַתָּא אָחוֹת אִמְּךָ אִתְקְרֵי, כְּמָה דִּכְתִּיב, (תהילים קכ״ב:ג׳) יְרוּשָׁלַ ם הַבְּנוּיָה כְּעִיר שֶׁחוּבְּרָה לָהּ יַחְדָּיו וְגוֹ'. מַאי שֶׁחוּבְּרָה לָהּ יַחְדָּיו. בְּגִין דְּאִזְדְּוַּוג בָּהּ מַלְכָּא מִשִּׁית סִטְרִין, בְּכָל סִטְרֵי מַלְכָּא, בְּדַרְגָּא דְּצַדִּיק, וְכָל כִּתְרֵי מַלְכָּא כְּלִילָן בֵּיהּ. וְהַיְינוּ שֶׁחוּבְּרָה לָהּ יַחְדָּיו.</p>\n<p>רִבִּי יִצְחָק אָמַר, (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ. מַאן שְׁבָטִים. אִלֵּין תְּרֵיסָר תְּחוּמִין, דְּמִתְפָּרְשָׁן מֵהַהוּא אִילָנָא רַבָּא וְתַקִּיף, דְּאַחֲסִין לוֹן מִסִּטְרָא דְּאַבָּא וְאִימָּא. הֲדָא הוּא דִכְתִיב שִׁבְטֵי יָהּ, מִשְׁפַר סַהֲדוּתָא, דְּאַסְהִיד בְּרָא קַדִּישָׁא (רצ\"ה) (נ\"א דאסהיד אבא ואימא בברא קדישא) דִּכְתִּיב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, וְאִינּוּן נַהֲרִין עֲמִיקִין, דְּנַגְדִּין וְאִתְמַשְּׁכָן מִן יָהּ. וְכֹלָּא (ס\"א וכל כך למה). לְהוֹדוֹת לְשֵׁם יְיָ'. (ס\"א ובגין כך) כִּי שָׁמָּה יָשְׁבוּ כִסְאוֹת לְמִשְׁפָּט כִּסְאוֹת לְבֵית דָּוִד, לְאַחְסְנָא מַלְכוּתָא קַדִּישָׁא הוּא וּבְנוֹי לְדָרֵי דָּרִין, וְדָא הִיא שִׁירָתָא דְּאָמַר דָּוִד עַל מָלְכוּ עִלָּאָה קַדִּישָׁא.</p>\n<p>רִבִּי חִזְקִיָּה אָמַר, כֹּלָּא בְּרָזָא עִלָּאָה הוּא, לְאַחֲזָאָה דְּמַאן דְּפָגִים לְתַתָּא, פָּגִים לְעֵילָּא. עֶרְוַת כַּלָּתְךָ לֹא תְגַלֵּה, דְּתָנֵינָן עוֹנָתָן שֶׁל תַּלְמִידֵי חֲכָמִים מִשַּׁבָּת לְשַׁבָּת. בְּגִין דְּיַדְעִין רָזָא דְּמִלָּה, וִיכַוְּונוּן לִבָּא, וְיִשְׁתְּכַּח רְעוּתְהוֹן שְׁלִים. וּבְנִין דְּאוֹלִידוּ אִקְרוּן בְּנִין דְּמַלְכָּא. וְאִי אִלֵּין פְּגִימוּ מִלָּה לְתַתָּא, כִּבְיָכוֹל פַּגְמִין אִינּוּן בְּכַלָּה דִּלְעֵילָּא, כְּדֵין כְּתִיב עֶרְוַת כַּלָּתְךָ לֹא תְגַלֵּה. דָּא בְּגִין אִינּוּן דְּיַדְעִין אוֹרְחִין דְּאוֹרַיְיתָא. שְׁאָר עַמָּא הַהוּא דְּאִתְגַּלְיָא, כַּלָּתְךָ מַמָּשׁ, וּבְחוֹבָא דָּא שְׁכִינְתָּא אִסְתְּלָקַת מִבֵּינַיְיהוּ.</p>"],[9520012168,"<p>תָּאנָא, אִתְגַלִיף שְׁמָא קַדִּישָׁא בְּסִטְרִין יְדִיעָן, בְּאַתְוָון רְשִׁימִין דְּעֶשְׂרִין וּתְרֵין (ס\"א י' בא', א' בי', י' בב', ב' בי', י' בא', ב' בה', ו' בג', י' בה', י' בג', ה' בי', ג' בה', ה' בד' אלו השני נוסחאות מצאנו בהעתקות אשר לפנינו) י' בְּא', א' בְּי'. י' בְּב', ב' בְּי'. ו' בְּא' ה' בְּג', יו\"ד בְּה\"א, יו\"ד בְּגימ\"ל, ה\"א בְּיו\"ד גימ\"ל בְּה\"א, ה\"א בְּדל\"ת (י' בד', ד' בי'. י' בה'. י' בג'. ה' בי'. ג' בי'. ו' בי'). כֻּלְּהוּ מִתְגַּלְּפֵי בְּיוֹ\"ד, יוֹ\"ד סָלִיק לוֹן.</p>\n<p>הֵ\"א כָּלִיל בְּיוֹ\"ד, מִנֵּיהּ נָפְקַת, כְּדֵין מְעַטְּרִין לַאֲבָהָן. אִתְפַּתְּחַת הֵ\"א בְּנַחְלוֹי, וְאַעְטַּר לְרֵישָׁא דְּו', דְּתַמָּן שַׁרְיָין אֲבָהָן.</p>\n<p>ו' כָּלִיל שִׁית אַתְוָון, וְכֻלְּהוּ כָּלִיל יוֹ\"ד. י' (יו\"ד) אִתְגְּלִיף בְּגִלוּפוֹי, וְסָלִיק לְאִתְעַטְּרָא בִּתְרֵיסַר אַתְוָון אָחֳרָנִין, מִנֵּיהּ נַפְקוּ עֶשֶׂר אֲמִירָן בְּגִלוּפוֹי, וְכֻלְּהוּ שְׁבִילִין דְּאוֹרְחָא עִלָּאָה, (ס\"א דאורחן דאורייתא) יַקִּירָא דְּכֹלָּא. כְּדֵין הֵ\"א אָחֳרָא אִתְכְּלִילַת מִן כֻּלְּהוּ, גְּלִיפָא מִסִּטְרָא מְתִיחָא (ס\"א מתייחדא) טְמִירָא, לְאוֹלָדָא לְתַתָּא.</p>\n<p>אִתְגְּלִיפוּ (ס\"א אתפליגו) כֻּלְּהוּ בְּאַרְבְּעִין וּתְרֵין אַתְוָון, וְכֻלְּהוּ פָּרִישְׁנָא בְּמַתְנִיתָא דִּידָן, וְכֻלְּהוּ סַלְקָן בְּרֵישָׁא דְּמַלְכָּא.</p>\n<p>שֶׁבַע שַׁבָתִּין שְׁלֵימִין, מִתְפָּרְשִׁין בְּשִׁבְעִין אַתְוָון. שִׁבְעִין וּתְרֵין אִסְתְּלָקוּ, וְאִסְתְּלָּקוּ בְּאוֹת ו' (ס\"א יו\"ד), רְשִׁימָן בפ' וַיְהִי בְּשַׁלַּח פַּרְעֹה בְּקְרָא וַיִּסַּע וַיָּבֹא וַיֵּט. כַּד נַטְלַת שְׁכִינְתָּא, וְז' רְשִׁימִין אִתְרְשִׁימוּ בֵּיהּ, שִׁבְעָה אִסְתְּלָקוּ <Nonei></i>מִנֵּיהּ, בְּאַתְוָון רְשִׁימִין. תָּאנָא, אִסְתְּלָקוּ אַתְוָון בִּרְשִׁימִין יְדִיעָן, וְאָרְחִין סְתִימִין, בַּר לְזַכָּאֵי קְשׁוֹט, סַמְכֵי עָלְמָא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר, תָּא חֲזֵי, הָנֵי עֶשְׂרִין וּתְרֵין אַתְוָון דִּגְלִיפִין בְּאוֹרַיְיתָא, כֻּלְּהוּ מִתְפָּרְשָׁן בְּהָנֵי (נ\"א מאלין) עֶשֶׂר אֲמִירָן. כָּל אֲמִירָה וַאֲמִירָה מֵאִלֵּין עֶשֶׂר, דְּאִינּוּן כִּתְרֵי מַלְכָּא כֻּלְּהוּ גְּלִיפִין בְּאַתְוָון יְדִיעָן (ד\"א אחרנין), בְּגִינֵי כַּךְ שְׁמָא קַדִּישָׁא אִתְכַּסְּיָיא בְּאַתְוָון אָחֳרָנִין, וְכָל אֲמִירָה, אוֹזִיף לַאֲמִירָה עִלָּאָה מִנָּהּ אַתְווֹי, בְּגִין דְּאִתְכְּלִיל הַאי בְּהַאי. וְעַל דָּא שְׁמָא קַדִּישָׁא, גָּלִיפְנָא לֵיהּ בְּאַתְוָון אָחֳרָנִין, בְּגִין דְּאִתְכַּסְיָין דָּא בְּדָא, וְדָא בְּדָא, עַד דְּמִתְקַשְּׁרָן כֻּלְּהוּ כַּחֲדָא.</p>\n<p>וּמַאן דְּבָעֵי לְמִנְדַּע צִרוּפֵי שְׁמָהָן קַדִּישִׁין, לִינְדַע אִינּוּן אַתְוָון דִּרְשִׁימִין בְּכָל כִּתְרָא וְכִתְרָא, וּכְדֵין לִינְדַע וְיִתְקְיָּים בְּכֹלָּא. וְהָא גָּלִיפְנָא לוֹן, בְּכָל אִינּוּן אַתְוָון דִּרְשִׁימָן וִידִיעָן בְּכָל כִּתְרָא וְכִתְרָא, מִסִּפְרָא עִלָאָה דִּשְׁלֹמֹה. וְהָכִי סָלִיק בִּידָן, וְחַבְרַיָּיא גְּלִיפִין לוֹן, (ס\"א ולחברייא גלינן לון) וְשַׁפִּיר הוּא, דְּהָא כָּל כִּתְרָא וְכִתְרָא אוֹזִיף לְחַבְרֵיהּ אַתְווֹי, כְּמָה דְּאוֹקִימְנָא, וּלְזִמְנִין דְּלָא אִצְטְרִיךְ אֶלָּא, בְּאַתְווֹי אִינּוּן דִּרְשִׁימִין בֵּיהּ. וְכֻלְּהוּ יְדִיעָן לְגַבֵּי חַבְרַיָּיא וְהָא אוֹקִימְנָא לוֹן.</p>\n<p>זַכָּאִין אִינּוּן צַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן, וּמְגַּלֵי לְהוֹן רָזִין עִלָּאִין דִּשְׁמֵיהּ קַדִּישָׁא, דְּלָא גַּלֵּי לְעִלָּאִין קַדִּישִׁין, וְעַל דָּא יָכִיל מֹשֶׁה, לְאִתְעַטְּרָא בֵּינֵי קַדִּישִׁין, וְכֻלְּהוּ לָא יַכְלֵי לְמִקְרַב בַּהֲדֵיהּ, כְּנוּרָא יָקִידְתָּא, וְגוּמְרֵי דְּאֶשָּׁא. דְּאִי לָאו הָכִי, מַאן הֲוָה לֵיהּ לְמֹשֶׁה, לְמֵיקָם בֵּינַיְיהוּ. אֶלָּא זַכָּאָה חוּלָקָא דְּמֹשֶׁה, דְּהָא כַּד שָׁארֵי לְמַלְּלָא עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, בָּעָא לְמִנְדַּע שְׁמֵיהּ קַדִּישָׁא (ס\"א שמוי קדישין), סָתִים וְגַלְיָא, בְּכָל חַד וְחַד כַּדְקָא חֲזֵי, וּכְדֵין אַדְבַּק וְיָדַע יַתִּיר מִכָּל בְּנֵי עָלְמָא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּסָלִיק מֹשֶׁה גּוֹ עֲנָנָא יַקִּירָא, עָאל בֵּינֵי קַדִּישִׁין. פָּגַע בֵּיהּ חַד מַלְאָכָא בְּשַׁלְהוֹבֵי נוּרָא, בְּעַיְינִין מְלַהֲטָן, וְגַדְפּוֹי מוֹקְדָן, בָּעָא לְשַׁאֲפָא לֵיהּ בְּגַוִּויהּ. וְהַהוּא מַלְאָכָא גַּבְרִיאֵל (ס\"א גזריא\"ל) (ס\"א גזרנא\"ל) (קמוא\"ל) שְׁמֵיהּ, כְּדֵין אַדְכַּר מֹשֶׁה חַד שְׁמָא קַדִּישָׁא. דְּהֲוָה גָּלִיף בִּתְרֵיסַר אַתְוָון, וְאִזְדַּעְזָע וְאִתְרְגַשׁ, עַד דְּסָלִיק מֹשֶׁה בֵּינַיְיהוּ. וְכֵן לְכָל חַד וְחַד, זַכָּאָה חוּלָקֵיהּ (שמות נח ע\"א) וְהָא אוֹקִימְנָא מִלֵי.</p>"],[9520012169,"<p>עֶרְוַת אִשָּׁה, וּבִתָּהּ לֹא תְגַלֵּה. תָּאנָא, בְּתִקּוּנֵי מַטְרוֹנִיתָא אוֹקִימְנָא אִלֵּין עֶרְיָין, אַף עַל גַּב דְּאִינּוּן (נ\"א עריין אינון) בְּאִתְגַּלְיָיא וּבִסְתִּימָא, וְתַמָּן בַּת בְּנָהּ וּבַת בִּתָּהּ. דְּהָא עָלְמָא אִצְטְרִיךְ לוֹן, וְאִינּוּן יִשּׁוּבָא דְּעָלְמָא, כְּמָה דְּאוֹקִימְנָא. וּמַאן דְּגַלֵּי חַד עֶרְיָיתָא מִנַּיְיהוּ, וַוי לֵיהּ, וַוי לְנַפְשֵׁיהּ, דְּהָא גַּלֵּי בְּגִין דָּא עֶרְיָין אָחֳרָנִין.</p>\n<p>וְתַנְיָא מִלָּה בַּתְרָאָה דְּעֶשֶׂר אַמִירָן דְּאוֹרַיְיתָא, (שמות כ׳:י״ד) לֹא תַחְמוֹד אֵשֶׁת רֵעֶךָ, בְּגִין דְּהַאי כְּלָלָא דְּכֻלְּהוּ. וּמַאן דְּחָמִיד אִתְּתָא אָחֳרָא, כְּאִלּוּ אַעְבָּר עַל אוֹרַיְיתָא כֻּלָּא. בְּרַם לָא אִית מִלָּה דְּקַיְּימָא קָמֵי תְּשׁוּבָה. וְכָּל שֶׁכֵּן אִי קַבִּיל עוֹנְשֵׁיהּ כְּדָוִד מַלְכָּא. אָמַר רִבִּי יוֹסֵי, תָּנֵינָן, כָּל מַאן דְּחָב וְאִתְפְּרַשׁ מֵהַהוּא חוֹבָא, תְּשׁוּבָה קָא מְעַלְּיָיא לֵיהּ טְפֵי. וְאִי לָאו, לָא סָלִיק בִּידֵיהּ תְּשׁוּבָה, וְלָא מְעַלְּיָיא לֵיהּ. אִי הָכִי, דָּוִד הֵיךְ לָא אִתְפְּרַשׁ מִבַּת שֶׁבַע לְבָתַר. אָמַר לֵיהּ, בַּת שֶׁבַע דִּידֵיהּ הֲוַת, וְדִידֵיהּ נָטִיל, דְּהָא מִית בַּעְלָהּ.</p>\n<p>דְּתַנְיָא, אִזְדַּמְּנַת הֲוַת בַּת שֶׁבַע לְדָוִד, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, וּמָה עַכְּבַא לֵיהּ. דְּנָטַל בְּרָתֵיהּ דְּשָׁאוּל מַלְכָּא, וְהַהוּא יוֹמָא נָטַל לָהּ אוּרִיָּה בְּרַחֲמֵי, אַף עַל גַּב דְּלָא הֲוַת דִּילֵיהּ. לְבָתַר אָתָא דָּוִד, וְנָטִיל דִּילֵיהּ, וְעַל דְּדָוִד דָּחִיק שַׁעֲתָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא לְקָטְלָא לְאוּרִיָּה וּלְמֶעְבַּד הָכִי. אַבְאִישׁ קָמֵיהּ, וְאַעְנָשׁ לֵיהּ לְדָוִד, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאָתָבָא לֵיהּ לְדָוִד, לְקַיְּימָא לֵיהּ מַלְכוּתָא קַדִּישָׁא עִלָּאָה. וְכַד תָּאַב, לְדִידֵיהּ תָּאַב.</p>\n<p>תָּאנָא, אָמַר רִבִּי יוֹסֵי, מַאי דִּכְתִּיב אֲנִי יְיָ'. אֲנִי יְיָ': עָתִיד לִיתֵּן שָׂכָר טוֹב לַצַדִּיקִים לֶעָתִיד לָבֹא. אֲנִי יְיָ' עָתִיד לְהִפָּרַע מִן הָרְשָׁעִים לֶעָתִיד לָבֹא. אִינּוּן דִּכְתִּיב בְּהוּ (ישעיהו ס״ו:כ״ד) הַפּוֹשְׁעִים בִּי. כְּתִיב אֲנִי יְיָ', וּכְתִיב (דברים ל״ב:ל״ט) אֲנִי אָמִית וַאֲחַיֶּה. אַף עַל פִּי <Nonei></i>שֶׁאֲנִי בְּמִדַּת הָרַחֲמִים, הָרְשָׁעִים הוֹפְכִים אוֹתִי לְמִדַּת הַדִין. דְּתַנְיָא, שֵׁם מָלֵא: יְיָ' אֱלֹהִים. זָכוּ יְיָ', וְאִי לָאו אֱלֹהִים. אָמַר רִבִּי שִׁמְעוֹן, חַיָּיבִין עַבְדֵי פְּגִימוּתָא לְעֵילָּא. מַאי פְּגִימוּתָא. כְּמָה דְּאוֹקִימְנָא פְּגִימוּתָא מַמָּשׁ, וְהָא אִתְּמַר.</p>"],[9520012170,"<p>תָּאנָא כְּתִיב וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ, תָּנֵי רִבִּי יְהוּדָה, דָּרָא דְּרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי שָׁארֵי בְּגַוִּיהּ, כֻּלְּהוּ זַכָּאִין, חֲסִידִין, כֻּלְּהוּ דַּחֲלֵי חַטָּאָה נִינְהוּ. שְׁכִינְתָּא שַׁרְיָא בֵּינַיְיהוּ, מַה דְּלֵית כֵּן בְּדָרִין אָחֳרָנִין. בְּגִינֵי כַּךְ מִילִּין אִינּוּן מִתְפָּרְשָׁן, וְלָא אִתְטַמְּרָן. בְּדָרִין אָחֳרָנִין לָאו הָכִי, וּמִלִּין דְּרָזֵי עִלָּאָה לָא יַכְלִין לְגַלָּאָה, וְאִינּוּן דְּיַדְעֵי מִסְתָּפוּ. דְּרַבִּי שִׁמְעוֹן כַּד הֲוָה אָמַר רָזָא דְּהַאי קְרָא, חַבְרַיָּיא כֻּלְּהוּ עֵינֵיהוֹן נַבְעִין דִּמְעִין, וְכֻלְהוּ מִילִּין דְּאָמַר הֲווֹ בְּעֵינַיְיהוּ גַּלְיָין, כְּמָה דִּכְתִּיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֵּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת.</p>"],[9520012171,"<p>דְּיוֹמָא חַד שָׁאִיל רִבִּי יֵיסָא אָמַר, בֵּיעָא דְּקוּשְׁטָא (ס\"א דקוסטא), דְּנָפְקָא מֵעוֹפָא דְּשַׁרְיָא (ס\"א דשדי) בְּנוּרָא, וְאִתְבָּקַע לְאַרְבַּע סִטְרִין. תְּרֵין סַלְּקִין מִנַּיְיהוּ, וְחַד מָאִיךְ, וְחַד רְבִיעַ בִּרְבִיעָא (ס\"א נביעי נביעא) דְּיַמָּא רַבָּא. אָמַר רִבִּי אַבָּא, עַבְדַת קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, קֹדֶשׁ חוֹל, דְּהָא כְּתִיב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, עַד לָא יִתְבְּקַע בֵּיעָא, (שמות ס\"א ע\"ב, קע\"ד ע\"א) תִּסְתָּלַּק מֵעָלְמָא. וְכַךְ הֲוָה בְּאִדָּרָא דְּרַבִּי שִׁמְעוֹן.</p>\n<p>תָּאנָא, בְּיוֹמוֹי דְּרַבִּי שִׁמְעוֹן הֲוָה אָמַר בַּר נָשׁ לְחַבְרֵיהּ, פְּתַח פִּיךָ וְיָאִירוּ דְּבָרֶיךָ. בָּתַר דְּשָׁכִיב רַבִּי שִׁמְעוֹן, הֲווֹ אַמְרֵי (קהלת ה׳:ה׳) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ.</p>"],[9520012172,"<p>תַּנְיָא אָמַר רַבִּי שִׁמְעוֹן, אִי בְּנֵי עָלְמָא מִסְתַּכְּלָן בְּמָה דִּכְתִּיב בְּאוֹרַיְיתָא, לָא יֵיתוּן לְאַרְגָּזָא קָמֵי מָארֵיהוֹן. תָּאנָא, כַּד מִתְעָרִין דִּינִין קַשְׁיָין לְאַחֲתָא בְּעָלְמָא, וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ וְגוֹ', הָכָא כְּתִיב (תהלים כה) סוֹד יְיָ' לִירֵאָיו, (ר\"צ ע\"ב ובאדרא ס\"א ובהאי דרא) וּבְאִדָרָא קַדִּישָׁא אִתְּמַר, הָכָא אִצְטְרִיכְנָא לְגַלָּאָה, דְּהָא לַאֲתַר דָּא אִסְתַּלָּק.</p>\n<p>דְּתָנֵינָן, בְּשַׁעֲתָא דְּחִוְיָא תַּקִּיפָא דִּלְעֵילָּא אִתְּעַר, בְּגִין חוֹבֵי עָלְמָא, שָׁארֵי וְאִתְחַבָּר עִם נוּקְבָּא, וְאָטִיל בָּהּ זוּהֲמָא, אִתְפְּרַשׁ דְּכוּרָא מִינָּהּ, בְּגִין דְּהָא אִסְתְּאָבַת, וְאִתְקְרִיאַת מִסְאֲבָא, וְלָא אִתְחֲזֵי לִדְכוּרָא לְמִקְרַב בַּהֲדָהּ, דְּוַוי אִי אִסְתְּאַב הוּא בַּהֲדָהּ, בְּזִמְנָא דְּאִיהִי אִסְתְּאָבַת.</p>"],[9520012173,"<p>וְתָאנָא, (תשא קצ\"ב) מְאָה וְעֶשְׂרִין וַחֲמֵשׁ זִינֵי מְסַאֲבוּתָא נַחְתּוּ לְעָלְמָא, דְּמִתְאַחֲדָן מִסִּטְרָא דְּחִוְיָא תַּקִּיפָא, וְשִׁבְעָה וְעֶשְׂרִין רַבְרְבִין מִנַּיְיהוּ, מִתְאַחֲדָן בְּנוּקְבֵי, וְאִתְדַּבְּקָן בְּהוּ. וַוי לְמַאן דְּיִקְרַב בַּהֲדָהּ בְּהַהוּא זִמְנָא, דְּמַאן דְּיִקְרַב בַּהֲדָהּ, אַחְזֵי פְּגִימוּתָא לְעֵילָּא, דְּהָא בְּחוֹבָא דָּא, אִתְּעַר חִוְיָא תַּקִּיפָא לְעֵילָּא, וְאַשְׁדֵּי זוּהֲמָא בַּאֲתַר דְּלָא אִצְטְרִיךְ, וְאִתְחַבָּר בְּנוּקְבָּא, וְאִתְרַבֵּי שַׂעֲרֵיהּ לִדְכוּרָא, בְּנוּקְבָּא אִסְתְּאָבַת, וְשַׂעְרָהָא רַבָּא, וְטוּפְרָהָא סַגִיאוּ, וּכְדֵין דִּינִין שַׁרְיָין לְאִתְּעָרָא בְּעָלְמָא, וְיִסְתַּאֲבוּן כֹּלָּא. הֲדָא הוּא דִכְתִיב, (במדבר י״ט:כ׳) כִּי אֶת מִקְדַּשׁ יְיָ' טִמֵּא, מִקְדַּשׁ יְיָ' אִסְתְּאַב, בְּחוֹבַיְיהוּ דִּבְנֵי נָשָׁא.</p>\n<p>תָּאנָא, מַאי דִּכְתִּיב, (בראשית ג׳:ט״ו) וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה, אַרְבָּעָה וְעֶשְׂרִים זִינֵי מְסַאֲבוּתָא אַטִּיל חִוְיָא בְּנוּקְבָּא, כַּד אִתְחַבָּר עִמָּהּ, כְּחוּשְׁבָּן וְאֵיבָה, וְעֶשְׂרִין וְד' זִינִין (ס\"א דינין) מִתְעָרִין לְעֵילָּא, וְעֶשְׂרִין וְאַרְבַּע לְתַתָּא. וְשַׂעֲרָא רַבָּא, וְטוּפְרִין סְגִיאוּ, וּכְדֵין דִּינִין מִתְעָרִין בְּכֹלָּא. וְתָאנָא כַּד בָּעַת אִתְּתָא לְאִתְדַכְּאָה, בַּעְיָא לְסַפְּרָא הַהוּא שַׂעֲרָא דְּרַבֵּי בְּיוֹמָא דְּאִיהִי מִסְאֲבָא, וּלְסַפְּרָא טוּפְרָהָא, וְכָל הַהוּא זוּהֲמָא דִּי בְּהוֹן.</p>"],[9520012174,"<p>דְּתָאנָא בְּרָזֵי דִּמְסָאֲבוּתָא, זוּהֲמָא דְּטוּפְרִין, יִתְּעַר זוּהֲמָא אָחֳרָא, וּבְגִּינֵי כַּךְ, בַּעְיָין גְּנִיזָא, וּמַאן דְּאַעְבָּר לוֹן לְגַמְרֵי, כְּאִלּוּ אִתְּעַר חֶסֶד בְּעָלְמָא. דְּתַנְיָא לָא לִבְעֵי לֵיהּ לְאִינִישׁ לְמֵיהַב דּוּכְרָנָא לְזִינִין בִּישִׁין. דְּתָנֵינָן (ע\"ז ע\"א) אֶלַף וְאַרְבַּע מְאָה וְה' זִינִין בִּישִׁין, מִתְאַחֲדָן בְּהַהוּא זוּהֲמָא, דְּאָטִיל חִוְיָא תַּקִּיפָא, וְכֻלְּהוּ מִתְעָרִין בְּהַהוּא זוּהֲמָא דְּטוּפְרִין.</p>\n<p>וַאֲפִילּוּ מַאן דְּבָעֵי, יַעְבִיד בְּהוּ חַרְשִׁין לִבְנֵי נָשָׁא, מִשּׁוּם אִינּוּן דְּתַּלְיָין בְּהוּ, וּמַאן דְּאַעְבָּר <Nonei></i>לוֹן, כְּאִלּוּ אַסְגֵּי חֶסֶד בְּעָלְמָא, וְדִינִין בִּישִׁין לָא מִשְׁתַּכְּחִין. וְיַּעְבַּר הַהוּא זוּהֲמָא וְטוּפְרָהָא דְּרָשִׁים בֵּיהּ. דְּתַנְיָא, מַאן דְּדָרִיךְ בְּרַגְלֵיהּ, אוֹ בִּמְסָאנֵיהּ עָלַיְיהוּ, יָכִיל לְאִתְזְקָא. וּמַה בְּהַאי שִׁיּוּרֵי דְּשִׁיּוּרֵי דְּזוּהֲמָא דִּלְעֵילָּא כַּךְ, אִתְּתָא דִּמְקַבְּלָא וְאִתְחֲבָּרַת בְּחִוְיָא, וְאָטִיל בָּהּ זוּהֲמָא, עַל אַחַת כַּמָּה וְכַמָּה. וַוי לְעָלְמָא דִּמְקַבְּלָא מִינָּהּ מֵהַהוּא זוּהֲמָא, בְּגִינֵי כַּךְ וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִּקְרַב.</p>"],[9520012175,"<p>אָמַר רִבִּי שִׁמְעוֹן, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, הָבִיאוּ עָלַי כַּפָּרָה בְּרֹאשׁ חֹדֶשׁ. עָלַי וַדַּאי, בְּגִין דְּיִתְעַבָּר הַהוּא חִוְיָא, וְיִתְבָּסַם מַאן דְּבַעְיָא. עָלַי: כְּמָה דִּכְתִּיב, (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ. וְעַל דָּא כְּתִיב בְּקֹרַח, (במדבר טז) הַנּוֹעָדִים עַל יְיָ', דִּבְגִינֵיהוֹן אִתְעַר מַאן דְּאִתְעַר דְּאַתֵי מִסִטְרַיְיהוּ. אוּף הָכָא הָבִיאוּ עָלַי כַּפָרָה, עָלַי מַמָשׁ. בְּגִין דְּיִתְבְּסַם וְיִתְעֲבָר וְלָא אִשְׁתְּכַח חִוְיָא בַּאֲתַר דְּשָׁארֵי. וְכָּל כַּךְ לָמָּה. עַל שֶׁמִּעַטְתִּי אֶת הַיָּרֵחַ, וְשַׁלְטָא בָּהּ מַאן דְּלָא אִצְטְרִיךְ. וּבְגִין כָּךְ כְּתִיב וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִקְרַב.</p>\n<p>זַכָּאָה דָּרָא, דְּרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי שָׁארֵי בְּגַוִּיהּ. זַכָּאָה עַדְבֵיהּ בֵּין עִלָּאִין וְתַתָּאִין. עָלֵיהּ כְּתִיב, (קהלת י׳:י״ז) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין. מַהוּ בֶּן חוֹרִין. דְּזָקִיף רֵישָׁא לְגַלָּאָה, וּלְפָרְשָׁא מִלִּין וְלָא דָּחִיל. כְּהַאי דְּאִיהוּ בֶּן חוֹרִין, וְיֵימָּא מַאי דְּבַעְיָא וְלָא דָּחִיל. מַהוּ מַלְכֵּךְ. דָּא הוּא רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, מָארֵיהּ דְּאוֹרַיְיתָא, מָארֵיהּ דְּחָכְמְתָא. דְּכַד הֲוָה רִבִּי אַבָּא וְחַבְרַיָּיא חָמָאן לְרִבִּי שִׁמְעוֹן, הֲווֹ רַהֲטֵי אֲבַתְרֵיהּ, וְאַמְרֵי, (הושע י) אַחֲרֵי יְיָ' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג.</p>"],[9520012176,"<p>אָמַר רִבִּי שִׁמְעוֹן, כְּתִיב (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ, אֲמַאי שָׁקִיל דָּא בְּדָא. אֶלָּא כֹּלָּא בְּחַד דַּרְגָּא סְלִיקוּ, דָּא אִזְדְּוַּוג בְּדָא. וְחֶדְוָותָא דְּדָא בְּדָא לָא אִשְׁתְּכַח, אֶלָּא כַּד אִתְגְּלֵי עַתִּיקָא קַדִּישָׁא, וּכְדֵין חֶדְוָותָא דְּכֹלָּא. וְתָנֵינָן, כְּתִיב (תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, לְיוֹם הַשַׁבָּת מַמָּשׁ. שְׁבָחָא דְּקָא מְשַׁבָּח קוּדְשָׁא בְּרִיךְ הוּא. כְּדֵין חֶדָוָותָא אִשְׁתְּכַח, וְנִשְׁמְתָא אִתּוֹסֶפֶת. דְּהָא עַתִּיקָא אִתְגְּלֵי וְזִוּוּגָא יִזְדָּמַן.</p>\n<p>אוּף הָכִי בְּחַדְתּוּתֵי סִיהֲרָא, דְּהָא נָהִיר לָהּ שִׁמְשָׁא בְּחֶדְוָותָא דִּנְהִירוּ דְעַתִּיקָא לְעֵילָּא. בְּגִינֵי כַּךְ הַאי קָרְבְּנָא הוּא לְעֵילָּא, בְּגִין דְּיִתְבְּסַם כֹּלָּא, וְיִשְׁתְּכַּח חֶדְוָותָא בְּעָלְמָא, וְעַל דָּא הָבִיאוּ עָלַי כַּפָּרָה, דַּיְיקָא מִלָּה.</p>\n<p>תָּאנָא, כְּתִיב (במדבר כ״ח:י׳) עוֹלַת שַׁבַּת בְּשַׁבַּתוֹ עַל עוֹלַת הַתָּמִיד, דְּבָעֵי לְכַוְּונָא לִבָּא לְעֵילָּא לְעֵילָּא, יַתִּיר מִשְּׁאַר יוֹמִין. וְעַל דָּא עַל עוֹלַת הַתָּמִיד דַּיְיקָא. תַּנְיָא, כְּתִיב בְּחַנָּה (שמואל א א) וַתִּתְפַּלֵּל עַל יְיָ', עַל דַּיְיקָא, בְּגִין דִּבְנִין בְּמַזָּלָא קַדִּישָׁא תַּלְיָין, כְּמָה דְּאוֹקִימְנָא וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת זְעֵירָא בְּאוֹרַיְיתָא. דְּלָא רְמִיזָא בְּחָכְמְתָא עִלָּאָה, וְתַלְיָין מִנֵּיהּ תִּלֵי תָּלִין רָזִין דְּחָכְמְתָא עִלָּאָה, הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:י״א) קְווּצּוֹתָיו תַּלְתַּלִּים, וְהָא אִתְּמַר.</p>"],[9520012177,"<p>רִבִּי יוֹסֵי אַשְׁכָּחֵיהּ לְרִבִּי אַבָּא, דְּהֲוָה יָתִיב וְקָארִי, הַאי קְרָא דִּכְתִּיב, (תהילים נ״ה:כ״ג) הַשְׁלֵךְ עַל יְיָ' יְהָבְךָ, עַל דַּיְיקָא, דְּהָא מְזוֹנֵי בְּמַזָּלָא תַּלְיָין. רִבִּי יְהוּדָה הֲוָה קָארֵי, (תהילים ל״ב:ו׳) עַל זֹאת יִתְפַּלֵּל כָּל חָסִיד אֵלֶיךָ לְעֵת מְצֹא. עַל זֹאת וַדַּאי. לְעֵת מְצֹא, הָא אוֹקִימְנָא. אֲבָל לְעֵת מְצֹא, כְּמָה דִּכְתִּיב, (ישעיהו נ״ה:ו׳) דִּרְשׁוּ יְיָ' בְּהִמָצְאוֹ קְרָאוּהוּ בִּהְיוֹתוֹ קָרוֹב. דָּבָר אַחֵר לְעֵת מְצֹא, בְּשַׁעֲתָא דְּנַהֲרִין נַגְדִּין וְאִתְמַשְׁכָאן, וּמִסְתַּפְּקֵי אֲבָהָן, וּמִתְבַּרְכָאן כֹּלָא. רַק לְשֵׁטֶף מַים רַבִּים, מַאן שֵׁטֶף מַים רַבִּים, דָּא עַמִיקָא דְּמַבּוּעִין וְנַהֲרִין, דְּמַאן יִזְכֶּה לֵיהּ, וּמַאן יִזְכֶּה לְקָרְבָא וּלְסַלְּקָא תַּמָּן. הֲדָא הוּא דִכְתִיב בֵּיהּ, (תהילים ל״ב:ו׳) רַק לְשֵׁטֶף מַיִם רַבִּים אֵלָיו לֹא יַגִּיעוֹ דְּהָא לָא זַכָּאָן, וְלָא יַכְלִין.</p>\n<p>רִבִּי יִצְחָק אָמַר, כְּתִיב (תהילים כ״ז:ד׳) אַחַת שָׁאַלְתִּי מֵאֵת יְיָ' אוֹתָהּ אֲבַקֵּשׁ וְגוֹ'. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּכַמָּה גְּנִיזִין עִלָּאִין טְמִירִין לְהוּ בְּהַהוּא עָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּהוּ בְּאִינוּן עָלְמִין, כְּמָה דְּאוֹקִימְנָא בְּנֹעַם יְיָ', וְהָא אִתְּמַר. רִבִּי חִזְקִיָּה אָמַר מֵהָכָא, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. יַעֲשֶׂה, תַּעֲשֶׂה מִבָּעֵי לֵיהּ. אֶלָּא יַעֲשֶׂה וַדַּאי, הַיְינוּ (ישעיהו ל״ח:ה׳) יוֹסִיף עַל יָמֶיךָ חֲמֵשׁ עֶשְׂרֵה שָׁנָה. וְהַיְינוּ הַשְׁלֵךְ עַל ה' יְהָבְךָ. וּכְתִיב וַתִּתְפַּלֵּל עַל יְיָ'. וְכֹלָּא חַד.</p>\n<p>זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, בְּעָלְמָא דֵּין וּבְעָלְמָא <Nonei></i>דְּאָתֵי, עָלַיְיהוּ כְּתִיב (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךָ אוֹהֲבֵי שְׁמֶךָ. וּכְתִיב (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ. וּכְתִיב (תהילים ט׳:י״א) וְיִבְטְחוּ בְךָ יוֹדְעֵי שְׁמֶךָ כִּי לֹא עָזַבְתָּ דוֹרְשֶׁךָ יְיָ'. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9520012178,"<p>(ויקרא י״ט:א׳-ב׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה לֵאמֹר. דַּבֵּר אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵיהֶם קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ' אֱלֹהֵיכֶם. רִבִּי אֶלְעָזָר פָּתַח, (תהילים ל״ב:ט׳) אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין וְגוֹ'. בְּכַמָּה זִמְנִין אוֹרַיְיתָא אַסְהִידַת בְּהוּ בִּבְנֵי נָשָׁא, כַּמָה זִמְנִין אֲרִימַת קָלִין, לְכָל סִטְרִין לְאִתְּעָרָא לְהוּ, וְכֻלְּהוּ דְּמִיכִין בְּשֵׁינָתָא בְּחוֹבֵיהוֹן (ס\"א בחוריהון), לָא מִסְתַּכְּלִין, וְלָא מַשְׁגִּיחִין, בְּהֵיךְ אַנְפִּין יְקוּמוּן לְיוֹמָא דְּדִינָא עִלָּאָה, כַּד יִתְבַּע לוֹן מַלְכָּא עִלָּאָה עֶלְבּוֹנָא דְּאוֹרַיְיתָא, דִּצְוַוחַת לָקֳבְלֵיהוֹן, וְלָא אָהַדְרוּ אַנְפִּין לָקֳבְלָהּ, דְּכֻלְּהוּ פְּגִימִין בְּכֹלָּא, דְּלָא יָדְעוּ מְהֵימְנוּתָא דְּמַלְכָּא עִלָּאָה, וַוי לוֹן, וַוי לְנַפְשֵׁהוֹן.</p>\n<p>דְּהָא אוֹרַיְיתָא בֵּיהּ אַסְהִידַת, וְאַמְרַת (משלי ט׳:ד׳) מִי פֶתִי יָסוּר הֵנָּה חֲסַר לֵב (ס\"א ואמרה) אָמְרָה לוֹ. מַהוּ חֲסַר לֵב. דְּלֵית לֵיהּ מְהֵימְנוּתָא, דְּמַאן דְּלָא אִשְׁתָּדַּל בְּאוֹרַיְיתָא, לָאו בֵּיהּ מְהֵימְנוּתָא, וּפָגִים הוּא מִכֹּלָּא (ס\"א ואמרה) אָמְרָה לוֹ, אוֹמְרָה לוֹ מִבָּעֵי לֵיהּ, כְּמָה דְאַתְּ אָמֵר (תהילים מ״ב:י׳) אוֹמְרָה לְאֵל סַלְעִי, מַהוּ אָמְרָה. אֶלָּא לְאַכְלְלָא וּלְאִתּוֹסְפָא אוֹרַיְיתָא דִּלְעֵילָּא, דְּהִיא קַרְיָיהּ לֵיהּ חֲסַר לֵב, פָּגִים מִמְּהֵימְנוּתָא.</p>\n<p>דְּהָכִי תָּנֵינָן, כָּל מַאן דְּלָא אִשְׁתָּדַּל בְּאוֹרַיְיתָא, אָסִיר לְמִקְרַב לְגַבֵּיהּ, לְאִשְׁתַּתְּפָא בַּהֲדֵּיהּ, וּלְמֶעְבַּד בֵּיהּ סְחוֹרְתָּא, וְכָּל שֶׁכֵּן לְמֵהַךְ עִמֵּיהּ בְּאוֹרְחָא. דְּהָא לֵית בֵּיהּ מְהֵימְנוּתָא. (ועל דא) תָּנֵינָן כָּל בַּר נָשׁ דְּאָזִיל בְּאוֹרְחָא, וְלֵית עִמֵּיהּ מִלֵּי דְּאוֹרַיְיתָא, אִתְחַיָּיב בְּנַפְשֵׁיהּ. כָּל שֶׁכֵּן מַאן דְּאִזְדַּוָּוג בְּאוֹרְחָא, עִם מַאן דְּלֵית בֵּיהּ מְהֵימְנוּתָא, דְּלָא חָשִׁיב לִיקָרָא דְּמָארֵיהּ וְדִידֵיהּ דְּלָא חָס עַל נַפְשֵׁיהּ.</p>\n<p>רִבִּי יְהוּדָה אוֹמֵר, מַאן דְּלָא חָס עַל נַפְשֵׁיהּ, הֵיךְ יִשְׁלוֹף נַפְשָׁא דְּכַשְׁרָא לִבְרֵיהּ. אָמַר רִבִּי אֶלְעָזָר, תַּוַּוהְנָא עַל דָּרָא, וְהָא אִתְּמַר מִלָּה וְכוּ'. וְעַל דָּא כְּתִיב אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְיַדְעִין אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וּמְקַדְּשֵׁי גַּרְמַיְיהוּ בִּקְדוּשָׁא דְּמַלְכָּא, וְאִשְׁתְּכָחוּ קַדִּישִׁין בְּכֹלָּא, וּבְגִין כָּךְ מְשַׁלְּפֵי רוּחָא דְּקוּדְשָׁא מִלְּעֵילָּא, וּבְנַיְיהוּ כֻּלְּהוּ זַכָּאֵי קְשׁוֹט, וְאִקְרוּן בְּנֵי מַלְכָּא בְּנִין קַדִּישִׁין. (זכאין אינון אברים וכו' עד למהוי בנדתה, מהרעיא מהימנא נדפס בפרשת פנחס מאמר מתחיל אלא פגיעה רכ\"ה ע\"ב).</p>\n<p>וַוי לְהוֹן לְרַשִׁיעַיָּיא, דְּכֻלְּהוּ חֲצִיפִין, וְעוֹבָדַיְיהוּ חֲצִיפִין. בְּגִינֵי כַּךְ יָרְתִין בְּנַיְיהוּ נַפְשָׁא חֲצִיפָא, מִסִּטְרָא דִּמְסָאֲבָא. כְּמָה דִּכְתִּיב וְנִטְמֵתֶם בָּם, אָתָא לְאִסְתַּאֲבָא, מְסָאֲבִין לֵיהּ. אַל תִּהְיוּ כְּסוּס כְּפֶרֶד, דְּאִינּוּן מָארֵי זְנוּתָא (ס\"א דמסאבותא) עַל כֹּלָּא. אֵין הָבִין, דְּלָא יִשְׁתַּדְּלוּן בְּנֵי נָשָׁא בְּאָרְחָא דָּא, דְּאִי הָכֵי, כְּתִיב הָכָא אֵין הָבִין, וּכְתִיב הָתָם (ישעיהו נ״ו:י״א) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְהֵמָה רוֹעִים לֹא יָדְעוּ הָבִין. כְּלוֹמַר יֵהוֹן מִזְדַּמְּנִין אִינּוּן דְּאִקְרוּן עַזֵּי נֶפֶשׁ. מַאי טַעֲמָא. מִשּׁוּם דְּלָא יָדְעוּ הָבִין.</p>\n<p>וְהֵמָה רוֹעִים, מַאי <Nonei></i>רוֹעִים, אִלֵּין אִינּוּן מַדְבְּרֵי וּמַנְהִגֵי לְבַּר נָשׁ בַּגֵיהִנָּם. לֹא יָדְעוּ שָׂבְעָה, כְּמָה דְאַתְּ אָמֵר (משלי ל׳:ט״ו) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב, בְּגִין כָּךְ דְּאִינּוּן הַב הַב, לָא יָדְעוּ שָׂבְעָה. כֻּלָּם לְדַרְכָּם פָּנוּ אִישׁ לְבִצְעוֹ מִקָּצֵהוּ. דְּהָא תַּיָּירֵי דְּגֵיהִנָּם אִינּוּן. וְכָל דָּא מַאן גָּרִים לְהוּ. בְּגִין דְּלָא אִתְקַדָּשׁוּ בְּהַהוּא זִוּוּגָא כְּמָה דְּאִצְטְרִיךְ. וְעַל דָּא כְּתִיב, קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ'. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מִכָּל שְׁאָר עַמִּין לָא רַעְיָתִי לְאַדְבְּקָא בִּי, אֶלָּא יִשְׂרָאֵל, דִּכְתִּיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ', אַתּוּן, וְלָא שְׁאָר עַמִּין. (ועל דא כתיב הכא קדוש) בְּגִין כָּךְ, (קדושים תהיו דייקא).</p>"],[9520012179,"<p>(ויקרא י״ט:ב׳) קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ'. רִבִּי יִצְחָק פָּתַח, (ישעיהו י״ח:א׳) הוֹי אֶרֶץ צִלְצַל כְּנָפָיִם וְגוֹ'. וְכִי בְּגִין דְּהִיא אֶרֶץ צִלְצַל כְּנָפָיִם, קִנְטוּרָא בֵּיהּ אִשְׁתְּכַח, דִּכְתִּיב הוֹי אֶרֶץ. אֶלָּא אָמַר רִבִּי יִצְחָק, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרָא עָלְמָא, וּבָעָא לְגַלָּאָה עֲמִיקְתָא מִגּוֹ מְסַתְּרָתָא, וּנְהוֹרָא מִגּוֹ חֲשׁוֹכָא, הֲווֹ כְּלִילָן דָּא בְּדָא, וּבְגִין כַּךְ, מִגּוֹ חֲשׁוֹכָא נָפַק נְהוֹרָא, וּמִגּוֹ מְסַתְּרָתָא, נָפַק וְאִתְגַּלְיָיא עֲמִיקָא, וְדָא נָפְקָא מִן דָּא. דְּמִגּוֹ טַב, נָפִיק בִּישׁ. וּמִגּוֹ רַחֲמֵי, נָפִיק דִּינָא. וְכֹלָּא אִתְכְּלִיל דָּא בְּדָא. יֵצֶר טוֹב וְיֵצֶר רָע, יְמִינָא וּשְׂמָאלָא, יִשְׂרָאֵל וּשְׁאָר עַמִּין, חִוָּור וְאוּכָם, וְכֹלָּא חַד בְּחַד תַּלְיָא.</p>\n<p>תָּאנָא אָמַר רִבִּי יִצְחָק אָמַר רִבִּי יְהוּדָה, כָּל עָלְמָא כֻּלְּהוּ לָא אִתְחָזֵי, אֶלָּא בְּחַד עֲטִירָא דְּקוּטְפָא (ס\"א דקיזטופא) בְּקִיטְרוֹי כַּד אִתְּדָּן עָלְמָא בְּדִינָא כָּלִיל בְּרַחֲמֵי אִתְּדָּן. וְאִי לָאו, לָא יָכִיל עָלְמָא לְקַיְּימָא, אֲפִילּוּ רִגְעָא חֲדָא, וְהָא אוֹקִימְנָא מִלֵּי, כְּמָה דִּכְתִּיב, (ישעיהו כ״ו:ט׳) כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךָ לָאָרֶץ צֶדֶק לָמְדוּ יוֹשְׁבֵי תֵּבֵל.</p>\n<p>וְתָאנָא בְּהַהוּא זִמְנָא דְּדִינָא תַּלְיָא בְּעָלְמָא, וְצֶדֶק אִתְעַטְּרָא בְּדִינוֹי, כַּמָה מָארֵי דְּגַדְפִּין מִתְעָרֵי, לָקֳבְלֵי מָארֵי דְּדִינָא קַשְׁיָא, לְשַׁלְּטָאָה בְּעָלְמָא. פַּרְסִין גַּדְפִּין מֵהַאי סִטְרָא, וּמֵהַאי סִטְרָא, לְאִשְׁתַּטְּחָא (ס\"א לאשגחא) בְּעָלְמָא. כְּדֵין מִתְעָרִין גַּדְפִּין לְמִפְרַס לוֹן, וּלְאִשְׁתַּאֲבָא (נ\"א ולאשתתפא) בְּדִינָא קַשְׁיָא, וְשָׁאטִין בְּעָלְמָא לְאַבְאָשָׁא. כְּדֵין כְּתִיב, הוֹי אֶרֶץ צִלְצַל כְּנָפָיִם. אָמַר רִבִּי יְהוּדָה, חַמִינָא בְּנֵי עָלְמָא בְּחַצִיפוּתָא, בַּר אִינוּן זַכָּאִי קְשׁוֹט. וּבְגִין כָּךְ, כִּבְיָכוֹל, כֹּלָא הָכִי אִשְׁתָּכַח, אָתָא לְאִתְדַכָּאָה, מְסַיְיעִין לֵיהּ. אָתָא לְאִסְתָאַבָא, כְּמָה דְאוֹקִימְנָא, וְנִטְמֵתֶם בָּם.</p>"],[9520012180,"<p>רִבִּי יוֹסֵי הֲוָה אָזִיל בְּאוֹרְחָא, פָּגַע בֵּיהּ רִבִּי חִיָּיא, אָמַר לֵיהּ הַאי דְּאוּקְמוּהָ חַבְרַיָּיא, דִּכְתִּיב בְּעֵלִי, (שמואל א ג׳:י״ד) וְלָכֵן נִשְׁבַּעְתִּי לְבֵית עֵלִי אִם יִתְכַּפֵּר עֲוֹן בֵּית עֵלִי בְּזֶבַח וּמִנְחָה עַד עוֹלָם. בְּזֶבַח וּמִנְחָה אֵינוֹ מִתְכַּפֵּר, אֲבָל מִתְכַּפֵּר הוּא בְּדִבְרֵי תּוֹרָה. אֲמַאי. בְּגִין דְּדִבְרֵי תּוֹרָה, סַלְּקִין עַל כָּל קָרְבְּנִין דְּעָלְמָא. כְּמָה דְּאוּקְמוּהָ דִּכְתִּיב, (ויקרא ז׳:ל״ז) זֹאת הַתּוֹרָה לָעוֹלָה לַמִּנְחָה וְלַחַטָּאת וְלָאָשָׁם וְלַמִּלּוּאִים, שָׁקִיל אוֹרַיְיתָא לָקֳבֵיל כָּל קָרְבְּנִין דְּעָלְמָא. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, דְּכָל מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, אַף עַל גַּב דְּאִתְגְּזַר עָלֵיהּ עוֹנְשָׁא מִלְעֵילָּא, נִיחָא לֵיהּ מִכָּל קָרְבְּנִין וְעִלָּוָון, וְהַהוּא עוֹנְשָׁא אִתְקְרַע. (ובגין דלעי בה לשמה, קודשא בריך הוא אתפייס בהדיה)</p>\n<p>וְתָּא חֲזֵי, לָא אִתְדָּכֵי בַּר נָשׁ לְעָלְמִין, אֶלָּא בְּמִלִּין דְּאוֹרַיְיתָא. בְּגִינֵי כַּךְ מִלִּין דְּאוֹרַיְיתָא לָא מְקַבְּלִין טוּמְאָה, בְּגִין דְּאִיהִי (משלי ג) קַיְּימָא לְדַכְּאָה לְאִלֵּין מִסְאֲבֵי, וְאַסְוּותָא בְּאוֹרַיְיתָא אִשְׁתְּכַח. דִּכְתִּיב, רִפְאוּת תְּהִי לְשָׁרֶךָ וְשִׁקּוּי לְעַצְמוֹתֶיךָ. וְדַכְיוּתָא אִשְׁתְּכַח בְּאוֹרַיְיתָא, דִּכְתִּיב, (תהילים י״ט:י׳) יִרְאַת יְיָ' טְהוֹרָה עוֹמֶדֶת לָעַד. מַאי עוֹמֶדֶת לָעַד. דְּקַיְּימָא תְּדִירָא בְּהַהוּא דַּכְיוּתָא, וְלָא אִתְעָדֵי מִנֵּיהּ לְעָלְמִין.</p>\n<p>אָמַר לֵיהּ יִרְאַת יְיָ' כְּתִיב, וְלָא תּוֹרָה. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, דְּהָא אוֹרַיְיתָא מִסִּטְרָא דִּגְבוּרָה קָא אַתְיָיא. אָמַר לֵיהּ, וּמֵהָתָם נָפְקָא, מֵהָכָא נָפְקָא, דִּכְתִּיב, (תהילים קי״א:י׳) רֵאשִׁית חָכְמָה יִרְאַת יְיָ', וּכְתִיב יִרְאַת יְיָ' טְהוֹרָה.</p>\n<p>וְאוֹרַיְיתָא קְדוּשָּׁה אִתְקְרֵי, דִּכְתִּיב כִּי קָדוֹשׁ אֲנִי יְיָ', וְדָא אוֹרַיְיתָא, דְּהִיא שְׁמָא קַדִּישָׁא עִלָּאָה. וְעַל דָּא, <Nonei></i>מַאן דְּאִשְׁתְּדַּל בָּהּ אִתְדָּכֵי, וּלְבָתַר אִתְקַדָּשׁ, דִּכְתִּיב קְדוֹשִׁים תִּהְיוּ, קְדוֹשִׁים הֱיוּ לָא כְּתִיב, אֶלָּא תִּהְיוּ. תִּהְיוּ וַדַּאי. אָמַר לֵיהּ הָכִי הוּא, וּמִקְרָא כְּתִיב, (שמות י״ט:ו׳) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ, וּכְתִיב אֵלֶּה הַדְּבָרִים וְגוֹ'.</p>\n<p>תָּאנָא, קְדוּשָּׁה דְּאוֹרַיְיתָא, קְדוּשָּׁה דִּסְלִיקַת עַל כָּל קִדּוּשִׁין. וּקְדוּשָּׁה דְּחָכְמְתָא עִלָּאָה סְתִימָא, סַלְּקָא עַל כֹּלָּא. אָמַר לֵיהּ לָאו אוֹרַיְיתָא בְּלָא חָכְמְתָא, וְלָאו חָכְמְתָא בְּלָא אוֹרַיְיתָא, וְכֹלָּא בְּחַד דַּרְגָּא הוּא, וְכֹלָּא חַד, אֶלָּא אוֹרַיְיתָא בְּחָכְמָה עִלָּאָה אִשְׁתְּכַחַת, וּבָה קַיְּימָא, וּבָה אִתְנְטָעוּ שָׁרְשָׁהָא מִכָּל סִּטְרִין.</p>\n<p>עַד דַּהֲווֹ אַזְלֵי, אַשְׁכָּחוּ חַד בַּר נָשׁ, בִּלְקִינְטָא דְּקוּסְטָא, (ס\"א בלקיטנא דקיסחא) רָכִיב עַל סוּסְיָא, אַשְׁמִיט יְדוֹי לְחָד עַנְפָּא דְּאִילָנָא. אָמַר רִבִּי יוֹסֵי, הַאי הוּא דִּכְתִּיב וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים. אָדָם מְקַדֵּשׁ עַצְמוֹ מִלְּמַטָּה, מְקַדְּשִׁין אוֹתוֹ מִלְּמַעְלָה. הֲדָא הוּא דִכְתִיב, קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ'.</p>\n<p>תָּאנֵי רִבִּי אַבָּא, פַּרְשְׁתָּא דָּא כְּלָלָא דְּאוֹרַיְיתָא הִיא, וְחוֹתָמָא דְּקוּשְׁטָא דְּגוּשְׁפַּנְקָא הִיא. בְּפַרְשְׁתָּא דָּא אִתְחַדָּשׁוּ רָזִין עִלָּאִין דְּאוֹרַיְיתָא, בְּעֶשֶׂר אֲמִירָן, וְגִזְרִין וְעוֹנָשִׁין, וּפִקּוּדִין עִלָּאִין, דְּכַד מָטָאן חַבְרַיָּיא לְפַרְשְׁתָּא דָּא, הֲווֹ חַדָּאן.</p>\n<p>אָמַר רִבִּי אַבָּא, מַאי טַעְמָא פַּרְשְׁתָּא דַּעֲרָיוֹת, וּפַרְשְׁתָּא דִּקְדוֹשִׁים תִּהְיוּ, סְמוּכִין דָּא לְדָא. אֶלָּא הָכִי תָּאנָא, כָּל מַאן דְּאִסְתָּמַר מֵאִלֵּין עֶרְיָין, בִּקְדוּשָּׁה אִתְעָבִיד וַדַּאי. וְכָּל שֶׁכֵּן אִי אִתְקַדָּשׁ בִּקְדוּשָּׁה דְּמָארֵיהּ. וְהָא אַתְּעֲרוּ חַבְרַיָּיא.</p>\n<p>אֵימָתַי עוֹנָתָן דְּכֹלָּא, לְאִתְקַדָּשׁ בַּר נָשׁ. תָּא חֲזֵי, מַאן דְּבָעֵי לְאִתְקַדְּשָׁא בִּרְעוּתָא דְּמָארֵיהּ, לָא לִישַׁמֵּשׁ אֶלָּא מִפַּלְגוּת לֵילְיָא וְאֵילָךְ, אוֹ בְּפַלְגוּת לֵילְיָא. דְּהָא בְּהַהִיא שַׁעֲתָא, קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בְּגִנְתָּא דְּעֵדֶן, וּקְדוּשָּׁה עִלָּאָה אִתְּעַר, וּכְדֵין שַׁעֲתָא הִיא לְאִתְקַדְּשָׁא. הַאי לִשְׁאָר בְּנֵי נָשָׁא, תַּלְמִידֵי חֲכָמִים דְּיַדְעִין אוֹרְחוֹי דְּאוֹרַיְיתָא, בְּפַלְגוּת לֵילְיָא שַׁעֲתָא דִּלְהוֹן לְמֵיקָם לְמִלְעֵי בְּאוֹרַיְיתָא, לְאִזְדַּוְּוגָא בִּכְּנֶסֶת יִשְׂרָאֵל, לְשַׁבְּחָא לִשְׁמָא קַדִּישָׁא, לְמַלְכָּא קַדִּישָׁא.</p>\n<p>בְּלֵילְיָא דְּשַׁבְּתָא, דִּרְעוּתָא דְּכֹלָּא אִשְׁתְּכַח, זִוּוּגָא דִּלְהוֹן בְּהַהִיא שַׁעֲתָא. לְאַפָּקָא רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּכְּנֶסֶת יִשְׂרָאֵל, כְּמָה דְּאִתְּמַר דִּכְתִּיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם. וְאִלֵּין אִקְרוּן קַדִּישִׁין, דִּכְתִּיב קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ'. וּכְתִיב (תהילים א׳:ג׳) וְהָיָה כְּעֵץ שָׁתוּל עַל פַּלְגֵי מָיִם אֲשֶׁר פִּרְיוֹ יִתֵּן בְּעִתּוֹ וְגוֹ'.</p>\n<p>קְדוֹשִׁים תִּהְיוּ, רִבִּי אַבָּא פָּתַח, (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ, תָּא חֲזֵי, בְּכָל עַמִּין דְּעָלְמָא, לָא אִתְרְעֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, בַּר בְּיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, וְעָבִיד לוֹן עַמָּא יְחִידָאָה בְּעָלְמָא, וְקָרָא לוֹן גּוֹי אֶחָד כִּשְׁמֵיהּ. וְאַעְטַּר לוֹן בְּכַמָּה עִטְרִין, וְכַמָּה פִּקוּדִין, לְאִתְעַטְּרָא בְּהוּ. וְעַל דָּא תְּפִילִין דְּרֵישָׁא וּתְפִילִּין דִּדְרוֹעָא, לְאִתְעַטְּרָא בְּהוּ בַּר נָשׁ כְּגַוְונָא דִּלְעֵילָּא. וּלְאִשְׁתַּכְּחָא חַד שְׁלִים בְּכֹלָּא.</p>\n<p>וּבְהַהִיא שַׁעֲתָא דְּאִתְעַטָּר בְּהוּ בַּר נָשׁ, וְאִתְקַדָּשׁ בְּהוּ, אִתְעָבִיד שְׁלִים, וְאִקְרֵי אֶחָד, דְּאֶחָד לָא אִקְרֵי אֶלָּא כַּד אִיהוּ שְׁלִים. וּמַאן דְּפָגִים, לָא אִקְרֵי אֶחָד. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי אֶחָד, בִּשְׁלִימוּ דְּכֹלָא, בִּשְׁלִימוּ דַּאֲבָהָן, בִּשְׁלִימוּ דִּכְנֶסֶת יִשְׂרָאֵל. בְּגִין כָּךְ יִשְׂרָאֵל לְתַתָּא אִקְרוּן אֶחָד. דְּכַד בַּר נָשׁ אֲנָח תְּפִילִין, וְאִתְחֲפֵּי בְּכִסּוּיָיא דְּמִצְוָה, כְּדֵין אִתְעֲטָּר בְּעִטְרִין קַדִּישִׁין כְּגַוְונָא דְּלְעֵילָּא, וְאִקְרֵי אֶחָד.</p>\n<p>וּבְגִּינֵי כַּךְ, לֵיתֵי אֶחָד, וְיִשְׁתְּדַל בְּאֶחָד. קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ אֶחָד, יִשְׁתְּדַל בְּאֶחָד. דְּהָא לֵית מַלְכָּא מִשְׁתָּדַּל, אֶלָּא בְּמַאי דְּאִתְחֲזֵי לֵיהּ. וּבְגִין כָּךְ כְּתִיב, (איוב כ״ג:י״ג) וְהוּא בְאֶחָד וּמִי יְשִׁיבֶנּוּ, לָא שָׁארֵי קוּדְשָׁא בְּרִיךְ הוּא וְלָא אִשְׁתְּכַח אֶלָּא בְּאֶחָד. בְּאֶחָד, אֶחָד מִבָּעֵי לֵיהּ אֶלָּא בְּמַאן דְּאִתְתְּקַן בִּקְדוּשָּׁא עִלָּאָה לְמֶהֱוִי חַד. כְּדֵין הוּא שַׁרְיָא בְּאֶחָד, וְלָא בַּאֲתַר אָחֳרָא.</p>\n<p>וְאֵימָתַי אִקְרֵי בַּר נָשׁ אֶחָד. בְּשַׁעֲתָא דְּאִשְׁתְּכַח דְּכַר וְנוּקְבָּא, וְאִתְקַדָּשׁ בִּקְדוּשָּׁה (ס\"א בעטרין) עִלָּאָה, וְאִתְכְּוָון לְאִתְקַדְּשָׁא. וְתָּא חֲזֵי, בְּזִמְנָא <Nonei></i>דְּאִשְׁתְּכַח בַּר נָשׁ בְּזִוּוּגָא חַד דְּכַר וְנוּקְבָּא, וְאִתְכַּוִון לְאִתְקַדְּשָׁא כְּדְקָא יֵאוֹת. כְּדֵין הוּא שְׁלִים, וְאִקְרֵי אֶחָד בְּלָא פְּגִימוּ.</p>\n<p>בְּגִינֵי כַּךְ, בָּעֵי בַּר נָשׁ לְמֶחְדֵּי לְאִתְּתֵיהּ בְּהַהִיא שַׁעֲתָא, לְזַמְּנָא לָהּ בִּרְעוּתָא חֲדָא עִמֵּיהּ. וְיִתְכַּוְּונוּן תַּרְוַויְיהוּ כְּחַד לְהַהִיא מִלָּה. וְכַד מִשְׁתַּכְּחֵי תַּרְוַויְיהוּ כְּחַד, כְּדֵין כֹּלָּא חַד בְּנַפְשָׁא וּבְגוּפָא. בְּנַפְשָׁא: לְאַדְבְּקָא דָּא בְּדָא בִּרְעוּתָא חֲדָא. וּבְגוּפָא: כְּמָה דְּאוֹלִיפְנָא דְּבַר נָשׁ דְּלָא נָסִיב, הוּא כְּמַאן דְּאִתְפְּלִיג, וְכַד מִתְחַבְּרָן דְּכַר וְנוּקְבָּא, כְּדֵין אִתְעָבִידוּ חַד גּוּפָא. אִשְׁתְּכַח דְּאִינְהוּ חַד נַפְשָׁא, וְחַד גּוּפָא, וְאִקְרֵי בַּר נָשׁ אֶחָד. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא שָׁארֵי בְּאֶחָד, וְאַפְקִיד רוּחָא דִּקְדוּשָּׁה בְּהַהוּא אֶחָד.</p>\n<p>וְאִלֵּין אִקְרוּן בְּנִין דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאִתְּמַר. וּבְגִּינֵי כַּךְ קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ'. זַכָּאִין אִינּוּן יִשְׂרָאֵל דְּלָא אוֹקִים מִלָּה דָּא בַּאֲתַר אָחֳרָא, אֶלָּא בֵּיהּ מַמָּשׁ, דִּכְתִּיב כִּי קָדוֹשׁ אֲנִי יְיָ'. בְּגִין לְאִתְדַּבְּקָא בֵּיהּ, וְלָא בְּאָחֳרָא. וְעַל דָּא קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי יְיָ' אֱלֹהֵיכֶם.</p>"],[9520012181,"<p>(ויקרא י״ט:ג׳) אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְגוֹ'. הָא תָּנֵינָן, דְּפַרְשְׁתָּא דָּא כְּלָלָא דְּאוֹרַיְיתָא. מַקִּישׁ דְּחִילוּ דְּאַבָּא וְאִימָא לְשַׁבְּתוֹתַי. אֶלָּא אָמַר רִבִּי יוֹסֵי, כֹּלָּא חַד, מַאן דְּדָחִיל מֵהַאי, נָטִיר לְהַאי.</p>\n<p>אִישׁ אִמּוֹ, אַקְדִּים אִמּוֹ לְאָבִיו בִּדְחִילוּ מַאי טַעְמָא. כְּמָה דְּאוּקְמוּהָ. אֲבָל אִימָּא דְּלֵית רְשׁוּ בִּידָהָא כָּל כַּךְ כְּאָבִיו (ס\"א אבל תא חזי אמו דא כנסת ישראל ובגין דבה שריא יראה ואיהי יראת ה' אתקרי) אַקְדִּים דְּחִילוּ דִּילָהּ.</p>\n<p>רִבִּי יִצְחָק אָמַר, מַה כְּתִיב לְעֵילָּא, קְדוֹשִׁים תִּהְיוּ. אָתֵי בַּר נָשׁ לְאִתְקַדְּשָׁא בְּאִתְּתֵיהּ כְּחַד. מִמַּאן הוּא שְׁבָחָא יַתִּיר בְּהַהִיא קְדוּשָּׁה. הֲוִי אֵימָּא מִנוּקְבָּא. בְּגִין כַּךְ אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ.</p>\n<p>רִבִּי יְהוּדָה אָמַר, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, כְּהַאי גַּוְונָא, (בראשית ב׳:ד׳) בְּיוֹם עֲשׂוֹת יְיָ' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. וּבַאֲתַר אָחֳרָא, אַקְדִּים שָׁמַיִם לָאָרֶץ. אֶלָּא לְאַחֲזָאָה דְּתַרְוַויְיהוּ כַּחֲדָא אִתְעָבִידוּ. אוּף הָכָא אַקְדִּים אִימָּא לְאַבָּא, וּבַאֲתַר אָחֳרָא אַקְדִּים אַבָּא לְאִימָּא, לְאַחֲזָאָה דְּתַרְוַויְיהוּ כַּחֲדָא אִשְׁתָּדָלוּ בֵּיהּ.</p>\n<p>וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ, שָׁקִיל דָּא לְדָא, וְכֹלָּא כַּחֲדָא אִתְּקָלוּ בְּמַתְקְלָא חַד. דִּכְתִּיב, (שמות ל״א:י״ד) וּשְׁמַרְתֶּם אֶת הַשַׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם, וּכְתִיב (שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. אֶלָּא חַד לְאַבָּא, וְחַד לְאִימָּא. כְּתִיב הָכָא אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ. וּכְתִיב הָתָם (ויקרא כ״ו:ב׳) אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ וּמִקְדָּשִׁי תִּירָאוּ. מַהוּ מִקְדָּשִׁי. <Nonei></i>כְּמַשְׁמָעוֹ. תּוּ מִקְדָּשִׁי אִלֵּין אִינּוּן דִּמְקַדְּשֵׁי גַּרְמַיְיהוּ בְּהַהִיא שַׁעֲתָא. כְּגַוְונָא דָּא, (יחזקאל ט׳:ו׳) וּמִמִּקְדָּשִׁי תָּחֵלּוּ. אַל תִּקְרֵי מִמִּקְדָּשִׁי, אֶלָּא מִמְּקוּדָּשָׁי. מַה לְהַלָּן מִמְּקוּדָּשָׁי, אַף כָּאן מִמְּקוּדָּשָׁי, דְּאִינּוּן אַבָּא וְאִימָּא.</p>\n<p>(ויקרא י״ט:ג׳) אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ. רַבִּי שִׁמְעוֹן אָמַר, כְּתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' וְגוֹ'. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּמִתְדַּבְּקָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, (אינון ולא אומין עובדי כוכבים ומזלות) וּבְגִין דְּאִינּוּן מִתְדַּבְּקָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, כֹּלָּא אִתְדְּבָקוּ כַּחֲדָא דָּא בְּדָא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַּר נָשׁ מְקַדֵּשׁ לְתַתָּא, כְּגוֹן חַבְרַיָּיא דִּמְקַדְּשֵׁי גַּרְמַיְיהוּ מִשַּׁבָּת לְשַׁבָּת, בְּשַׁעֲתָא דְּזִוּוּגָא עִלָּאָה אִשְׁתְּכַח, דְּהָא בְּהַהִיא שַׁעֲתָא רַעֲוָא אִשְׁתְּכַח, וּבִרְכָתָא אִזְדַּמְּנַת. כְּדֵין מִתְדַּבְּקָן כֻּלְּהוּ כְּחַד, נַפְשָׁא דְּשַׁבָּת, וְגוּפָא דְּאִזְדְּמַן בְּשַׁבָּת. וְעַל דָּא כְּתִיב, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, דְּאִינּוּן זִוּוּגָא חַד בְּגוּפָא, בְּהַהִיא שַׁעֲתָא (לאתקדשא) דְּאִתְקַדְּשָׁא. וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ. דָּא שַׁבָּת עִלָּאָה וְשַׁבָּת תַּתָּאָה, דְּאִינּוּן מְזַמְּנֵי לְנַפְשָׁא בְּהַהוּא גּוּפָא, מֵהַהוּא זִוּוּגָא עִלָּאָה. וְעַל דָּא וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ, תְּרֵי וְכֹלָּא אִתְדְּבַק דָּא בְּדָא, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ, לְאַזְהָרָה לְאִינּוּן דִּמְחַכָּן לְזִוּוּגַיְיהוּ מִשַּׁבָּת לְשַׁבָּת, וְהָא אוֹקִימְנָא, כְּמָה דִּכְתִּיב, (ישעיהו נ״ו:ד׳) לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי. מַאן סָרִיסִים. אִלֵּין אִינּוּן חַבְרַיָּיא דִּמְסָרְסָן גַּרְמַיְיהוּ כָּל שְׁאָר יוֹמִין, בְּגִין לְמִלְעֵי בְּאוֹרַיְיתָא. וְאִינּוּן מְחַכָּאן מִשַּׁבָּת לְשַׁבָּת. הֲדָא הוּא דִכְתִיב אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי, כְּמָה דְאַתְּ אָמֵר (בראשית ל״ז:י״א) וְאָבִיו שָׁמַר אֶת הַדָּבָר. וּבְגִין כָּךְ וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ. אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, דָּא גּוּפָא. וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ, דָּא נַפְשָׁא. וְכֹלָּא אִתְדְּבַק דָּא בְּדָא. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל.</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ. פִּקּוּדָא דָּא, שָׁקִיל דָּא לְדָא. שָׁקִיל יְקָרָא דְּאָב וְאֵם, לִיקָרָא דְּשַׁבָּת. לְאַבָּא אַקְדִּים כָּבוֹד, וְהַאי אִיהוּ דְּאָמַר קְרָא, (מלאכי א׳:ו׳) וְאִם אָב אָנִי אַיֵּה כְבוֹדִי וְאִם אֲדוֹנִים אָנִי אַיִּה מוֹרָאִי. כְּבוֹדִי סָלִיק בְּחוּשְׁבָּן עֶשֶׂר אֲמִירָן, ול\"ב אֱלֹהִים דְּעוֹבָדָא דִּבְרֵאשִׁית.</p>\n<p>וּבְכָל אֲתַר (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ, וְאוּקְמוּהָ רַבָּנָן, אֵין כָּבוֹד אֶלָּא תּוֹרָה. בְּגִין דְּאִינּוּן לֵ\"ב אֱלֹהִים דְּתוֹרָה, יְקָרָא דִּילֵיהּ. וְאִלֵּין (אינון) חֲכָמִים דְּאוֹרַיְיתָא, חֲכָמִים בְּחָכְמָה, יָרְתִין הַאי כָּבוֹד וְלָא טִפְּשֵׁי, דְּעָלַיְיהוּ אִתְּמַר, (משלי ג׳:ל״ה) וּכְסִילִים מֵרִים קָלוֹן. וּמְנָלָן דְּמַאן דְּלָא יָדַע בְּאוֹרַיְיתָא אִקְרֵי כְּסִיל, דִּכְתִּיב, (תהילים צ״ב:ז׳) וּכְסִיל לֹא יָבִין אֶת זֹאת. וְאֵין זֹאת, אֶלָּא תּוֹרָה, דִּכְתִּיב, (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה.</p>\n<p>רַעְיָא מְהֵימָנָא. בְּגִין דַּחֲלִישָׁתָא, פָּתַחְנָא לְפַרְשְׁתָּא בְּאִלֵּין פִּקוּדִין, לְמֶהֱוִי מְעַט עֶזֶר לָךְ. אִתְתָּקַּף בָּךְ, דְּהָא מַשִּׁרְיָין דִּמְתִּיבְתָּאן אָתָאן לְגַבָּךְ, בְּפִקּוּדָא בָּתַר דָּא, דְּאִיהוּ פִּקּוּדָא לְהַעֲמִיד עָלֶיךָ מֶלֶךְ לְעֵילָּא. וְקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָךְ מֶלֶךְ בְּעִלָּאִין וְתַתָּאִין בְּדִיוּקְנֵיהּ. בְּגִין דְּרַבָּנָן דִּמְתִיבְתָּא, עָלַיְיהוּ שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה. וְקוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ בְּאֶמְצָּעִיתָא, אָחִיד בְּעִלָּאִין וְתַתָּאִין הָכִי אַנְתְּ תְּהֵא בְּדִיוּקְנֵיהּ, בְּרָא דִּילֵיהּ, קוּם בִּיקָרָא דְּמַלְכָּא.</p>\n<p>קָם רַעְיָא מְהֵימָנָא, וְסָלִיק יְדוֹי לְעֵילָּא, וְאָמַר, יְהֵא רַעֲוָא דִּילָךְ עִלַּת הָעִלּוֹת, דְּאַנְתְּ מִתְעַלֶּה מֵעִלּוּי לְעִלּוּי, עַד דְּלֵית עִלּוּי. אֶלָּא <Nonei></i>דְּאַנְתְּ לְעֵילָּא מִכָּל עִלּוּי. לְמֵיהַב לִי חֵילָא, לְמֶעְבַּד רְעוּתָךְ בְּדַרְגִּין דִּילָךְ, דְּאִינּוּן אַבָּא וְאִימָּא, וַאֲנָא בְּרָא דִּלְהוֹן. וּבְיִחוּדָךְ תַּרְוַויְיהוּ אֶחָד. וְאַנְתְּ שַׁקְלַת דְּחִילוּ דְּאַבָּא וְאִימָא, לִדְחִילוּ דִּילָךְ, בָּתַר דְּאַנְתְּ בְּאֶמְצָּעִיתָא חַד, וְלָא תְּרֵין, בְּלָא שׁוּתָּפוּ, אַף עַל גַּב דְּאִינּוּן חַד בְּשׁוּתָּפוּ דִּילָךְ, אֲבָל אַנְּתְּ חַד בְּלָא שׁוּתָּפוּ דְּתִנְיָינָא. וּבְגִין דָּא אִתְּמַר בָּךְ, (דברים ל״ב:ל״ט) וְאֵין אֱלֹהִים עִמָּדִי.</p>\n<p>הַב לִי חֵילָא, לְאִתְּעָרָא בִּיקָרָךְ בְּקַדְמִיתָא. וּלְבָתַר בִּיקָרָא דְּאָבִי וְאִמִי דְּבִשְׁמַיָּא, דְּאוּקְמוּהָ עָלַיְיהוּ, (משלי כ״ח:כ״ד) גּוֹזֵל אָבִיו וְאִמּוֹ וְאוֹמֵר אֵין פָּשַׁע חָבֵר הוּא לְאִישׁ מַשְׁחִית. וְאוּקְמוּהָ מָארֵי מַתְנִיתִין, אֵין אָבִיו, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאֵין אִמּוֹ, אֶלָּא כְּנֶסֶת יִשְׂרָאֵל. וִיקָרָא דִּילָךְ אַבָּא חָכְמָה, דְּכָלִיל עֶשֶׂר סְפִירוֹת מִתַּתָּא דִּילֵיהּ לְעֵילָּא, וְתַרְוַויְיהוּ אִינּוּן כּוּרְסְיָיא סַפְסָל תְּחוֹתָךְ לִיקָרָךְ.</p>\n<p>וְהָכִי תַּקִּינוּ, לְמֶהֱוִי קָטָן לַגָּדוֹל מְכַבֵּד דִּלְעֵילָּא מִנֵּיהּ. אַבָּא, אִיהוּ חָכְמָה, הֲלֹא אָב אֶחָד לְכֻלָּנוּ, לְמֶהֱוִי מְשַׁמֵשׁ תְּחוֹתָךְ, וְאַנְתְּ כֶּתֶר עֶלְיוֹן עַל רֵישֵׁיהּ. וְלֵית כֶּתֶר עֲלָךְ, וְלֵית אֱלָהָא אָחֳרָא. וְאִימָּא, לְשַׁמְּשָׁא לְאַבָּא. דְּאִיהוּ תְּחוֹתֵיהּ לְמֶהֱוִי כִּסֵּא תְּחוֹתֵיהּ.</p>\n<p>וַיֹּאמֶר אִיהוּ, בְּכָל מַאֲמָר, עַד תְּלָתִין וּתְרֵין, יְהִי כֵּן, וַיְהִי כֵן. וְאִיהִי, עֲבִידַת מַאֲמָרֵיהּ מִיַּד. וּבְגִין דְּעֲבִידַת מַאֲמָרֵיהּ וְצִּוּוּיֵהּ בְּלָא עִכּוּבָא כְּלַל, בל\"ב שְׁבִילִין דִּבְהוֹן אִתְבְּרֵי כָּל דִּבְרֵאשִׁית, עוֹבָדָא אִתְקְרִיאַת כָּבוֹד, (תהילים כ״ט:ט׳) וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד. (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ. אַיִּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצּוֹ.</p>\n<p>וְתַרְגּוּם כְּבוֹד אָבִיו, יְקָרָא דַּאֲבוּהִי. וְדָא (תהלים יט) תּוֹרַת יְיָ' תְּמִימָה, עָלָהּ אִתְּמַר (משלי ג) יְקָרָה הִיא וְיִשְׂרָאֵל מִפְּנִינִים. דְּאִתְקְרִיאוּ בָּנִים, בִּכְלַל בֵּן וּבַת, מִסִּטְרָא דְּתִפְאֶרֶת וּמַלְכוּת. דְּאִינּוּן בֵּן וּבַת, יְקָרָא דְּאָבִיו וְאִמּוֹ, לְמֶעְבַּד צִּוּוּיֵיהּ, וְצִּווּי דִּילֵיהּ, אִינּוּן פִּקוּדִין דַּעֲשֵׂה. וְהָא אוּקְמוּהָ מָארֵי מַתְנִיתִין, יֵשׁ מְצּוּוְּה וְעוֹשֶׂה. וּבְגִין כָּךְ אִיהוּ נַעֲשֶׂה וְנִשְׁמָע. וְהַאי אִיהוּ כָּבוֹד דְּאַבָּא וְאִימָא, דִּיצַּוְּה לִבְרֵיהּ דְּיֶעְבַּד הָכֵי וְאִיהוּ עָבִיד מִיַּד, בְּלָא עִכּוּבָא כְּלַל.</p>\n<p>וְעִלַּת עַל כֹּלָּא, אֲנָא בָּעֵי לְאִשְׁתַּדְּלָא בִּיקָרָךְ, לְתַקֵּן מִדּוֹת דְּאַבָּא וְאִימָּא, לִיקָרָךְ. תְּהֵא בְּעֶזְרִי לְסַדְּרָא כֹּלָּא כְּדְקָא יִאוֹת. וְאַנְתְּ תְּסַדֵר לִי, וּלְכָל מָארֵי מְתִיבְתָּאן עֵילָּא וְתַתָּא, וּמַשִּׁרְיָין דְּמַלְאָכִין עִלָּאִין וְתַתָּאִין, לְמֶהֱוִי מְתַקְּנִין וּמְסַדְּרִין לִיקָרָא דִּילָךְ, וְלִיקָרָא דְּאַבָּא וְאִימָּא, לְמֶהֱוִי סַפְסָל תְּחוֹת רַגְלוֹי. וּלְמֶעְבַּד צִּוּוּיֵיהּ בְּכָל פִּקוּדִין דִּילֵיהּ. וּלְמִדְחַל מִנֵּיהּ בְּכָל פִּקוּדִין דְּלָא תַּעֲשֶׂה.</p>\n<p>וְהַאי אִיהוּ <Nonei></i>אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, וְסָמִיךְ לֵיהּ וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ. וּבִקְרָא אַחֲרִינָא וְאֶת מִצְּוֹתַי תַּעֲשׂוּ. מִסִּטְרָא דְּפִקּוּדִין דַּעֲשֵׂה דְּאִינּוּן כָּבוֹד, אַקְדִּים אַבָּא לְאִימָּא, וְדָא י\"ה. מִסִּטְרָא דְּלָא תַּעֲשֶׂה, אַקְדִּים אִימָּא לְאַבָּא, וְדָא הֵ\"י. וְהַיְינוּ כְּבוֹד אֱלֹהִים הַסְתֵּר דָּבָר. לְאִלֵּין דְּלָא מִשְׁתַּדְּלֵי בְּהַאי כָּבוֹד, הַסְתֵּר דָּבָר מִנַּיְיהוּ.</p>\n<p>וְעָלַיְיהוּ אִתְּמַר, (משלי ג׳:ל״ה) וּכְסִילִים מֵרִים קָלוֹן. אִלֵּין אִינּוּן עַמֵּי הָאָרֶץ, בָּתַר דְּלָא מִשְׁתַּדְּלִין בְּהַאי כָּבוֹד דְּאוֹרַיְיתָא, וְאֵיךְ אָמְרִין אָבִינוּ שֶׁבַּשָּׁמַיִם שְׁמַע קוֹלֵנוּ חוּס וְרַחֵם עָלֵינוּ וְקַבֵּל תְּפִלָּתֵנוּ. הָא אִיהוּ לֵימָּא לוֹן, וְאִם אָב אָנִי אַיֵּה כְבוֹדִי, אַיִּה אִשְׁתַּדְּלוּתָא דִּלְכוֹן בְּאוֹרַיְיתָא, וּבְפִקּוּדִין דִּילִי, לְמֶעְבַּד צִּוּוּיַי, דְּמַאן דְּלָא יָדַע בְּצִּוּוּיָיה דְּמָארֵיהּ, אֵיךְ יַעְבִיד לֵיהּ.</p>\n<p>בַּר מִמַּאן דְּשָׁמַע מֵחֲכָמִים וְעָבִיד, וְהַאי אִיהוּ דְּקַבִּיל נַעֲשֶׂה וְנִשְׁמָע. וְעִם כָּל דָּא, מַאן דְּלָא קַבִּיל מִמָּארֵיהּ, אֶלָּא מִשְלוּחֵיהּ, אִיכָּא אַפְרָשׁוּתָא. וּמַאי אַפְרָשׁוּתָא אִית בֵּין דָּא לְדָא. דְּהָא כְּתִיב, מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי, וּלְבָתַר וּמְסָרָהּ לִיהוֹשֻׁעַ. אֲנָא קַבִּילְנָא, וּלְבָתַר מוֹסַרְנָא לְכֻלְּהוּ. וְהָכִי מַאן דִּמְקַבֵּל מֵאָחֳרָא, כְּקַבָּלַת סִיהֲרָא וְכֹכָבַיָּיא מִשִּׁמְּשָׁא, וּבְהַאי קִבּוּל אִתְמְלֵי. וּמַאן דִּמְקַבֵּל יָכִיל לְאִסְתַּלְּקָא מִנֵּיהּ נְבִיעוּ, כְּמָה דַּחֲזֵינָא בְּשִׁמְשָׁא וְסִיהֲרָא, דְּאִסְתַּלְּקַת נְהוֹרָא דִּלְהוֹן, בְּלֵילְיָא, דְּלָא נָהִיר שִׁמְשָׁא, אֶלָּא בִּימָמָא. וְסִיהֲרָא בְּלֵילְיָא.</p>\n<p>וְאִי תֵּימָא דְּהַהוּא נְהוֹרָא דְּסִיהֲרָא מִשִּׁמְּשָׁא אִיהוּ, דְּאַף עַל גַּב דְּאִתְכְּנִישׁ, נָהִיר בְּסִיהֲרָא וְכֹכָבַיָּא, הָא חֲזֵינָן מִסִּטְרָא אָחֳרָא בְּלָקוּתָא דְּסִיהֲרָא וְשִׁמְּשָׁא דְּאִסְתְּלַּק נְהוֹרַיְיהוּ, וְאִשְׁתָּאָרוּ כְּגוּפָא בְּלָא נִשְׁמְתָא, דְּאִית אָדוֹן עֲלֵיהֶם מַחֲשִׁיךְ מְאוֹרֵיהֶם. אֲבָל עִקָּרָא דִּנְהוֹרָא, הַהוּא אֲתַר דִּנְבִיעַ דְּלֵית פְּסָק לִנְהוֹרָא דִּילֵיהּ, וְלָא אִית עָלֵיהּ אֱלָהָא אָחֳרָא לְמִפְסַק מִנֵּיהּ נְהוֹרֵיהּ.</p>\n<p>וְעִלַּת הָעִלּוֹת, בָּתַר דְּאַנְתְּ תַּמָּן, לֵית פְּסָק לִנְבִיעוּ דִּנְהוֹרָא דְּאוֹרַיְיתָא. יְהֵא רַעֲוָא דִּילָךְ דְּלָא תָּזוּז מֵאַבָּא וְאִימָּא דִּילִי, וְלָא מִבְּנוֹי. וְהָכִי מַאן דְּאָמִית גַּרְמֵיהּ עַל אוֹרַיְיתָא, דְּהִיא יְקָרָה, אִתְקַיְּימַת בֵּיהּ, וְלָא מַפְסְקַת מִנֵּיהּ. מַה דְּלָאו הָכִי, מַאן דְּלָא יִשְׁתַּדֵּל בָּה, אֶלָּא אַף עַל גַּב דְּעָבַד צִּוּוּי חֲכָמִים, אִיהוּ שַׁמָּשׁ דִּלְהוֹן, עֶבֶד וְלָא בֵּן, אֲבָל אִי אִיהוּ מְהֵימָנָא, מָארֵיהּ אַשְׁלִיט לֵיהּ בְּכָל דִּילֵיהּ.</p>\n<p>אֲבָל מַאן דְּלָא אִשְׁתְּדַּל בְּאוֹרַיְיתָא, וְלָא מְשַׁמֵּשׁ חֲכָמִים, לְמִשְׁמַע מִנַּיְיהוּ פִּקוּדִין, לְקַיֵּים נַעֲשֶׂה וְנִשְׁמָע. אֶלָּא דְּסָּרַח וְעָבַר עַל לֹא תַּעֲשֶׂה, אִיהוּ שָׁקִיל לְאוּמִין דְּעָלְמָא עוֹבְדֵי עֲבוֹדָה זָרָה, בְּנוֹי דְּסָמָאֵ\"ל וְנָחָשׁ, דְּאִתְּמַר בְּהוּ, (משלי ג׳:ל״ה) וּכְסִילִים מֵרִים קָלוֹן, דְּלָא בָּעוּ לְקַבְּלָא אוֹרַיְיתָא, דְּכָל דְּלֵית בֵּיהּ תּוֹרָה, לֵית בֵּיהּ כָּבוֹד, דְּאִתְּמַר בָּהֶם (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ.</p>"],[9520012182,"<p>וְעִם כָּל דָּא מָארֵי מְתִיבְתָּא, לָא כָּל כָּבוֹד שָׁוְה, דְּהָא (מלאכי א׳:ו׳) בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדוֹנָיו. בֵּן יְכַבֵּד, עַל מְנָת דְּלָא לְקַבְּלָא אַגְרָא, אֲבָל מְצּוּוְּה הוּא בִּכְבוֹד אַבָּא וְאִימָּא. וְאִי לָא בָּעֵי לְמֶעְבַּד צִּוּוּיֵיהּ, יִכְתַּשׁ לֵיהּ אַבָּא וְאִימָּא, עַד דְּיַעֲבִד עַל כָּרְחֵיהּ. וְאִי הֲוִי בְּרָא רַבְרְבָא, בֵּית דִּין כּוֹפִין לֵיהּ. דְּאִי לָא בָּעֵי לְמֶעְבַּד מַה כְּתִיב בֵּיהּ, (דברים כ״א:כ׳) בְּנֵנוּ זֶה סוֹרֵר וּמוֹרֶה אֵינֶנּוּ שׁוֹמֵעַ בְּקוֹלֵנוּ, וְדָנִין לֵיהּ בִּסְקִילָה. אֲבָל עֶבֶד דִּמְשַׁמֵּשׁ עַל מְנָת לְקַבֵּל פְּרָס, אִי לָא עָבִיד צִּוּוּיֵיהּ דְּרַבֵּיהּ, מָארֵיהּ אַעְבָּר לֵיהּ מִגּוֹ בֵּיתֵיהּ, וְיִטוֹל אָחֳרָא. מַה דְּלָא הֲוָה יָכִיל לְמֶעְבַּד הָכִי לִבְרֵיהּ, אֶלָּא אוֹ יַעְבֵיד צִּוּוּיֵיהּ אוֹ יִקְטוֹל לֵיהּ.</p>\n<p>אָמַר לֵיהּ בּוּצִּינָא קַדִּישָׁא, מַאן גָּרִים דְּלָא יַעְבֵיד צִּוּוּיֵיהּ, הוֹאִיל וּבְרֵיהּ הוּא. אָמַר רַעְיָא מְהֵימָנָא, וַדַּאי תַּעֲרוֹבֶת דְּרַע, וְרָזָא דָּא גָּרַם לְיִשְׂרָאֵל, לְמֶחֱטֵי גַּבֵּי אֲבוּהוֹן דְּבִשְׁמַיָּא. וְרָזָא דָּא, (תהילים ק״ו:ל״ה) וַיִּתְעָרְבוּ בַגּוֹיִם. וְדָא גָּרַם קִטוּלָא לְיִשְׂרָאֵל, וְחָרִיב בֵּי מַקְדְּשָׁא. וּבְגִין דָּא, אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ, אֶלָּא (דברים ל״ב:י״ב) יְיָ' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר.</p>\n<p>דְּיִשְׂרָאֵל אִינּוּן מֵאִילָנָא דְּחַיִּי, עֶבֶד טוֹב וְעֶבֶד רָע, מִסִּטְרָא דִּמְטַטְרוֹ\"ן עֶבֶד טוֹב, עֶבֶד נֶאֱמָן לְרַבֵּיהּ. עֶבֶד רָע סָמָאֵ\"ל. מַאן דְּאִיהוּ מֵאִילָנָא דְּחַיִּי, אִיהוּ בֶּן העוֹלָם הַבָּא, בֶּן מִסִּטְרָא דְּבֵן יָ\"הּ, בִּינָ\"ה. וְיָרִית מַלְכוּתָא דְּאִיהִי ה'. וְאֵיךְ יָרִית לָהּ. אִי עָבִיד צִּוּוּיֵיהּ דְּאַבָּא וְאִימָא, בְּגִין דְּאִיהוּ מַלְכוּתָא מִצְּוַת הַמֶּלֶךְ, וְעָלֵיהּ אִתְּמַר, (אסתר ג׳:ג׳) מַדּוּעַ אַתָּה עוֹבֵר אֵת מִצְּוַת הַמֶּלֶךְ. אִיהִי מִצְּוָה, וְצִּוּוּיַיא דְּמַלְכָּא עַל עֲשֵׂה וְלֹא תַּעֲשֶׂה.</p>\n<p>מִצְּוָה מִדְּאוֹרַיְיתָא, דְּאִיהִי תִּפְאֶרֶת. וְהָכָא לֵית תַּמָּן פִּרוּדָא, קוּדְשָׁא בְּרִיךְ הוּא אֱמֶת, תּוֹרָתוֹ תּוֹרַת אֱמֶת, אִיהוּ תּוֹרָתוֹ וּמִצְּוָתוֹ. כְּגַוְונָא דְּבִינָה, תּוֹרָתוֹ וּמִצְּוָתוֹ דְּחָכְמָה. דְּאִית תּוֹרָה דִּבְרִיאָה, וְחָכְמָה דִּבְרִיאָה, וּבִינָה דִּבְרִיאָה, וְהָכִי בְּכָל מִדּוֹת. בְּהַאי, יָכִיל בֵּן בְּהַאי אוֹרַיְיתָא, לְמֶהֱוִי בְּלָא מִצְּוָה, וּמִצְּוָה בְּלָא תּוֹרָה בְּפֵרוּדָא. וּמֵהָכָא, <Nonei></i>בֵּן סוֹרֵר וּמוֹרֶה. אֲבָל מִסִּטְרָא דַּאֲצִּילוּת, לֵית אַפְרְשׁוּתָא, תַּמָּן, וְכֵן מִתַּמָּן אֵין חֵטְא בָּא עַל יָדוֹ וְלֵית בָּהּ עוֹנֶשׁ וְלָא שָׂכָר וְלָא מִיתָה.</p>\n<p>וּבְגִין דָּא, אוֹרַיְיתָא דָּא אִילָנָא דְּחַיִּי, שְׂכַר הָעוֹלָם הַבָּא, וְאִילָנָא דָּא, אִילָנָא דְּחַיֵּי אִתְקְרֵי, וְאִתְקְרֵי הָעוֹלָם הַבָּא, וְלָא אִתְקְרֵי בֵּיהּ שָׂכָר. בְּגִין דְּאִיהוּ בֵּן. מִתַּמָּן, לָא אִשְׁתְּדַּל בְּאוֹרַיְיתָא לְקַבְּלָא אַגְרָא, לָא בְּמַעֲשֵׂה וְלָא בְּדִיבּוּר וְלָא בְּמַחֲשָׁבָה.</p>"],[9520012183,"<p>אָתָא בּוּצִּינָא קַדִּישָׁא, לְנַשְּׁקָא לֵיהּ יְדֵיהּ. אָמַר, וַדַּאי אַנְתְּ הוּא בֵּן מִתַּמָּן, בְּדִיּוּקְנָא דִּבְרָא בּוּכְרָא דִּילֵיהּ, תִּפְאֶרֶת בְּרָא דְּאַבָּא וְאִימָא עִלָּאָה, אֲצִּילוּת דִּילֵיהּ בְּלָא הַפְסָקָה, לָא קְדָמָךְ בְּרָא אָחֳרָא, לָא בְּמַחֲשָׁבָה, וְלָא בְּדִבּוּר, וְלָא בְּמַעֲשֶׂה. אָמַר רַעְיָא מְהֵימָנָא, וְאַנְתְּ, וְחַבְרַיָּיא, וְרָאשֵׁי מָארֵי מְתִיבְתָּאן, דִּמְזַמְּנִין הָכָא, אִתִּי, בְּלָא הַפְסָקָה כְּלַל, וּבְלָא תַּעֲרוֹבֶת. נַשְׁקוּ כֻּלְּהוּ דָּא לְדָא, וְאִשְׁתְּמוֹדָעוּ בְּאַחְוָה, וּבָכוּ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, עִם כָּל דָּא, בְּרָא בּוּכְרָא חַיָּיבִין כָּל אֲחוּי בִּיקָרֵיהּ, דְּהָא כְּתִיב (שמות כ׳:י״ב) כַּבֵּד אֶת אָבִיךָ, וְאוּקְמוּהָ רַבָּנָן, אֶת לְרַבּוֹת אָחִיךְ הַגָּדוֹל. וַאֲפִילּוּ מִכָּל סִטְרָא אִיהוּ מְפֹרָשׁ עֲלָךְ בְּאוֹרַיְיתָא, בְּשַׁגַּ\"ם זֶה הֶבֶל. וְלָא הֲוָה לְאָדָם קַדְמָאָה בְּרָא קַדְמָאָה מִנֵּיהּ, וְאוּקְמוּהָ רַבָּנָן, בְּשַׁגַּם, זֶה מֹשֶׁה. דִּבְּרָא דְּמַלְכָּא בְּכָל אֲתַר, אַנְתְּ בּוּכְרָא מִסִּטְרָא דְּאִילָנָא דְּחַיֵּי דְּטוֹב וָרָע, אַנְתְּ הוּא טוֹב. (בוכרא) הֲדָא הוּא דִכְתִיב, (בראשית א׳:ד׳) וַיַרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, (שמות ב׳:כ״ה) וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא.</p>\n<p>וּמִתַּמָּן קָרָא יָתָךְ קוּדְשָׁא בְּרִיךְ הוּא עֶבֶד נֶאֱמָן. לְבָתַר סְלִיקַת לְמֶהֱוִי מַלְכָּא, הֲדָא הוּא דִכְתִיב, (דברים ל״ג:ה׳) וַיְהִי בִישׁוּרוּן מֶלֶךְ. לְבָתַר בֶּן בַּיִת לְעֵילָּא. מֶלֶךְ מִסִּטְרָא דְּמַלְכוּת דִּבְרִיאָה. בֶּן בַּיִת, מִסִּטְרָא דְּבִינָה דִּבְרִיאָה. כְּעַן אַנְתְּ מֶלֶךְ, מִסִּטְרָא דְּאִילָנָא דְּמַלְכוּת דַּאֲצִּילוּת. בֶּן בַּיִת, מִסִּטְרָא דְּבֶ\"ן יָ\"הּ, תִּפְאֶרֶת דַּאֲצִּילוּת, זַכָּאָה חוּלָקָךְ. וּמַאן גָּרִים לָךְ דָּא, בְּגִין דְּאִשְׁתְּדָּלוּתָךְ בַּתּוֹרָה וּבַמִצְּוָה, לְיַחֲדָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, לְאַעֲלָא מַלְכָּא עַל אַתְרֵיהּ, וְעַל מַשִׁרְיָיתֵיהּ לְעֵילָּא, וְעַל יִשְׂרָאֵל לְתַתָּא.</p>\n<p>וּבְגִין כַּךְ (ס\"א ובגינך) יָרְתִין כֻּלְּהוּ נִשְׁמָתִין דַּאֲצִּילוּת מִנֵּיהּ, וְאִתְקְרִיאוּ בְּנִין דִּילֵיהּ, מִשֵׁם יְדוָֹ\"ד דַּאֲצִּילוּת, דְּלֵית תַּמָּן פִּרוּד וְקִצּוּץ. דִּבְקַדְמֵיתָא אִתְּמַר בְּהוּ בְּנִין לְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, מִצַּד יְהוָֹ\"ה דִּבְרִיאָה, דְּאִתְּמַר בֵּיהּ בְּרָאתִיו יְצַּרְתִּיו אַף עֲשִׂיתִיו, וּכְעַן בָּנִים לַיְדוָֹ\"ד דַּאֲצִּילוּת.</p>"],[9520012184,"<p>וּבָךְ אִתְקַיָּים פִּקּוּדָא, דְּאִיהִי מִצְּוָה עַל יִשְׂרָאֵל, לְהַעֲמִיד עֲלֵיהֶם מֶלֶךְ. הֲדָא הוּא דִכְתִיב, (דברים י״ז:ט״ו) שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ. וְאִתְקַיָּים בָּךְ (דברים ל״ג:ה׳) וַיְהִי בִישׁוּרוּן מֶלֶךְ, כַּד בְּקַדְמִיתָא. וְכֻלְּהוּ מִתְנַהֲגִין אֲבַתְרָךְ, כָּאֵבָרִין דְּמִתְנַהֲגִין כֻּלְּהוּ בִּתְנוּעָה דְּנִשְׁמְתָא, דְּאִתְפַּשְּׁטָא עַל כָּל אֵבֶר. בְּגִין דְּכֶתֶר עֶלְיוֹן אַנְתְּ תְּהֵא מְעוּטָר בֵּיהּ, דְּבֵיהּ עִלַּת הָעִלּוֹת אִיהוּ כֶּתֶר עַל כֹּלָּא, טָמִיר וְגָנִיז מִלְּגָיו מִנֵּיהּ. וּמִנֵּיהּ אִתְפְּשָׁט עַל כָּל סְפִירָן, וּמְסַדֵּר לוֹן לְמֶהֱוִי דָּא רַב, וְדָא זְעֵיר, וְדָא בֵּינוֹנִי, וְאַנְהִיג לוֹן לִרְעוּתֵיהּ, וְנָהִיר בְּהוּ, וּמְקַשֵׁר לוֹן, וּמְיַחֵד לוֹן.</p>\n<p>הָכִי אַנְתְּ תְּהֵא מַנְהִיג לְיִשְׂרָאֵל, בְּכָל מִדּוֹת טָבִין דִּילֵיהּ, וּתְסַדֵּר כָּל חַד כִּדְחֲזֵי לֵיהּ, הַבְּכוֹר כִּבְכוֹרָתוֹ, וְהַצָּעִיר כִּצְּעִירֻתוֹ, וּבֵינוֹנִי כְּפוּם דַּרְגֵּיהּ. וּתְקַשֵׁר לוֹן קֶשֶׁר אֶחָד לְגַבֵּי אֲבוּהוֹן דְּבִשְׁמַיָּא. לְמֶהֱוִי כֻּלְּהוּ בְּשָׂפָה בְּרוּרָה, לְבָרְכָא לְּקוּדְשָׁא בְּרִיךְ הוּא. וּלְקַדְּשֵׁיהּ, וּלְיַיחֲדֵיהּ, בְּדַרְגָּא דִּילָךְ, בְּמַחֲשָׁבָה דִּילָךְ, בַּאֲצִּילוּת דִּילָךְ, דְּאִתְקָיָּים בָּךְ (במדבר י״א:י״ז) וְאָצַּלְתִּי מִן הָרוּחַ אֲשֶׁר עָלֶיךָ וְשַׂמְתִּי עֲלֵיהֶם. קוּם אִתְּעַר בְּפִקּוּדָא, לְהַכְרִית זַרְעוֹ שֶׁל עֲמָלֵק. (פרשת תצא רפ\"א ע\"ב שייך לנשא קמ\"ה ע\"א)</p>\n<p>(ויקרא י״ט:ג׳) אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְגוֹ' פִּקּוּדָא דָא, לְכַבֵּד אָב וְאֵם, דְּאִצְּטְרִיךְ בַּר נָשׁ לְמִדְחַל מֵאָבוֹי וּמֵאִמֵיהּ, וּלְאוֹקִיר לוֹן. כְּמָה דְּאִצְּטְרִיךְ בַּר נָשׁ לְאוֹקִיר לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא. מִסִּטְרָא דְּרוּחָא דְּיָהַב בְּגַוִיהּ. וּלְמִדְחַל מִנֵּיהּ. הָכִי אִצְּטְרִיךְ לֵיהּ לְאוֹקִיר לַאֲבוֹי וּלְאִמֵּיהּ, מִסִּטְרָא דְּגוּפָא דִּילֵיהּ, וּלְמִדְחַל מִנְּהוֹן, דְּהָא אִינּוּן מִשְׁתַּתְּפִין בְּקוּדְשָׁא בְּרִיךְ הוּא, וְעַבְדֵּי לֵיהּ גּוּפָא, וְהוֹאִיל וְאִינּוּן שׁוּתָּפִין בְּעוֹבָדָא, לִיהֱווּ שׁוּתָּפִין בִּדְחִילוּ וִיקָרָא.</p>\n<p>כְּגַוְונָא דָּא, ג' שׁוּתָּפִין אִשְׁתְּכָחוּ לְעֵילָּא בְּרָזָא דְּאָדָם. אָדָם קַדְמָאָה, אַף עַל גַּב דְּגוּפָא דִּילֵיהּ הֲוָה מֵעַפְרָא, לָאו מֵעַפְרָא דְּהָכָא הֲוָה אֶלָּא מֵעַפְרָא דְּבֵי מַקְדְשָׁא דִּלְעֵילָּא. אַבָּא וְאִימָּא אִשְׁתְּכָחוּ, וּמַלְכָּא עִלָּאָה אִשְׁתְּתַּף בַּהֲדַיְיהוּ, וְשָׁדַר בֵּיהּ רוּחָא דְּחַיִּי, וְאִתְבְּרֵי. וּכְגַוְונָא דָּא, אִשְׁתְּכַּח כֹּלָּא עֵילָּא וְתַתָּא. וְעַל דָּא אִצְּטְרִיךְ לֵיהּ לְבַּר נָשׁ לְמִדְחַל לְקוּדְשָׁא בְּרִיךְ הוּא, וּלְמִדְחַל לַאֲבוּי וּלְאִמֵּיהּ.</p>"],[9520012185,"<p>בְּסִתְרֵי תּוֹרָה, אָדָם קַדְמָאָה לָא הֲוָה לֵיהּ מֵהַאי עָלְמָא כְּלוּם. חַד צַּדִּיק עֲבַד שִׁמּוּשָׁא בְּנוּקְבֵיהּ, וְאִתְעָבִיד מֵהַהוּא שִׁמּוּשָׁא גּוּפָא חֲדָא, דִּנְהִירוּ דִּילֵיהּ יַתִיר מִכָּל אִינּוּן מַלְאֲכִין שְׁלִיחָן לְעֵילָּא. וְכַד אִתְבְּרֵי הַהוּא גּוּפָא מַלְכָּא עִלָּאָה, שָׁדַר בְּהַהוּא צַּדִיק כ\"ב אַתְוָון, וְאִשְׁתְּתַּף בַּהֲדַיְיהוּ, וְנָפַק לְעָלְמָא.</p>\n<p>כֵּיוָן דְּנָפַק, חָמוּ לֵיהּ שִׁמְשָׁא וְסִיהֲרָא, וְאַסְתִּימוּ <Nonei></i>נְהוֹרַיְיהוּ, דְּתַפּוּחָא דְּרַגְלֵיהּ אַחְשִׁיךְ נְהוֹרָא דִּלְהוֹן. מַאי טַעֲמָא. בְּגִין דְּמֵעוֹבָדָא דְּשִׁמְשָׁא וְסִיהֲרָא עִלָּאָה נָפַק. כֵּיוָן דְּחָטָא, אִתְחֲשָׁךְ, וְאַזְעִיר גַּרְמֵיהּ, וְאִצְּטְרִיךְ לְגוּפָא אָחֳרָא בְּמִשְׁכָא וּבְבִשְׂרָא. דִּכְתִיב, (בראשית ג׳:כ״א) וַיַּעֲשׂ יְיָ' אֱלֹהִים לָאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם. כְּהַהוּא שִׁמּוּשָׁא דַּעֲבַד הַהוּא צַּדִיק בְּנוּקְבֵיהּ, לָא אִשְׁתְּכַח מִקַּדְמַת דְּנָא, וּלְבָתַּר דְּנָא, דְּהָא עַד לָא נָפַק לְצּוֹרֵף אוּמָנָא.</p>\n<p>עַד דְּאָתָא חֲנוֹךְ, וְנָטִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵאַרְעָא, וְאַבְרִיר פְּסוֹלֶת וְקַסְטוּרָא מִכַּסְפָא, וְכֵן בְּכָל אִינּוּן צַּדִּיקַיָּיא דִּי בְּאַרְעָא. לְבָתַר אִתְתָּקַּן הַהוּא אֲתַר, וְאִתְעָבִידוּ רוּחִין וְנִשְׁמָתִין בְּשִׁמּוּשַׁיְיהוּ וְגוּפָא מִתַּתָּא בְּאַרְעָא. וְעַל דָּא בְּשׁוּתָּפוּ דִּלְעֵילָּא וְתַתָּא, בַּר נָשׁ אָתֵי לְעָלְמָא, וְאִצְּטְרִיךְ לְמִדְחַל לְאִינּוּן שׁוּתָּפִין, וּלְאוֹקִיר לוֹן, כְּמָה דְּאִתְּמַר (ע\"כ רעיא מהימנא)</p>\n<p>(ויקרא י״ט:ד׳) אַל תִּפְנוּ אֶל הָאֱלִילִים וִאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם. רִבִּי חִיָּיא פָּתַח, (דברים ט׳:כ״ז) אַל תֵּפֶן אֶל קְשִׁי הָעָם הַזֶּה וְגוֹ'. אַל תֵּפֶן. וְכִי מַאן הוּא דְּיֵימָּא לְמַלְכָּא, אַל תֵּפֶן. וְהָא כְּתִיב (איוב ל״ד:כ״א) כִּי עֵינָיו עַל דַּרְכֵי אִישׁ. וּכְתִיב (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם יְיָ', וְהָא בְּכֹלָּא אַשְׁגַּח קוּדְשָׁא בְּרִיךְ הוּא וְכָל עוֹבָדִין מִסְתָּכַּל, וְעָיִיל בְּדִינָא עַל כֻּלְּהוּ, אִם טַב וְאִם בִּישׁ, כְּמָה דְאַתְּ אָמֵר, (קהלת י״ב:י״ד) הָאֱלֹהִים יָבִיא בְמִשְׁפָּט עַל כָּל נֶעְלָם אִם טוֹב וְאִם רָע. וּמֹשֶׁה אָמַר אַל תֵּפֶן.</p>\n<p>אֶלָּא, כַּמָה בָּעֵי בַּר נָשׁ לְאִסְתַּמְּרָא מְחוֹבוֹי, בְּגִין דְּלָא יֶחטֵי קָמֵי מַלְכָּא קַדִּישָׁא. תָּא חֲזֵי, בַּר נָשׁ דְּעָבִיד מִצְוָה, הַהִיא מִצְוָה סַלְּקָא, וְקַיְּימָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאָמְרָה אֲנָא מִפְּלַנְיָיא דְּעָבַד לִי. וְקוּדְשָׁא בְּרִיךְ הוּא מָנֵי לָהּ קַמֵּיהּ, לְאַשְׁגְּחָא בָּהּ כָּל יוֹמָא לְאוֹטָבָא לֵיהּ בְּגִינָהּ. עָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, הַהִיא עֲבֵירָה סַלְּקָא קָמֵיהּ, וְאָמְרָה אֲנָא מִפְּלַנְיָיא דַּעֲבַד לִי, וְקוּדְשָׁא בְּרִיךְ הוּא מָנֵי לָהּ, וְקַיְּימָא תַּמָּן לְאַשְׁגְּחָא בָּהּ, לְשֵׁיצָאָה לֵיהּ. הֲדָא הוּא דִכְתִיב, (דברים ל״ב:י״ט) וַיַּרְא יְיָ' וַיִנְאָץ מִכַּעַס בָּנָיו וּבְנוֹתָיו. מַהוּ וַיַּרְא. הַהוּא דְּקַיְּימָא קַמֵּיהּ.</p>\n<p>תָּב בִּתְשׁוּבָה, מַה כְּתִיב. (שמואל ב י״ב:י״ג) גַּם יְיָ' הֶעֱבִיר חַטָּאתְךָ לֹא תָמוּת. דְּאַעְבָּר הַהוּא חוֹבָא מִקַּמֵּיהּ, בְּגִין דְּלָא יִסְתָּכַּל בֵּיהּ. לְאוֹטָבָא לֵיהּ. וְעַל דָּא אַל תֵּפֶן אֶל קְשִׁי הָעָם הַזֶּה וְאֶל רִשְׁעוֹ וְאֶל חַטָּאתוֹ. אָמַר רִבִּי יוֹסֵי, וְכֵן מֵהָכָא מַשְׁמַע, דִּכְתִּיב, (ירמיהו ב׳:כ״ב) נִכְתָּם עֲוֹנֵךְ לְפָנַי.</p>"],[9520012186,"<p>רִבִּי יוֹסֵי זְעֵירָא, עָאל קָמֵיהּ דְּרִבִּי שִׁמְעוֹן יוֹמָא חַד, אַשְׁכְּחֵיהּ דְּהֲוָה יָתִיב וְקָאֲרִי, כְּתִיב, (בראשית ג׳:י״ב) וַיֹּאמֶר הָאָדָם הָאִשָּׁה אֲשֶׁר נָתַתָּ עִמָּדִי הִיא נָתְנָה לִּי מִן הָעֵץ וָאוֹכֵל. מַשְׁמַע דְּאָדָם וְחַוָּה כַּחֲדָא אִתְבְּרִיאוּ, וּבְגוּפָא חֲדָא. דִּכְתִּיב אֲשֶׁר נָתַתָּ עִמָּדִי, וְלָא כְּתִיב אֲשֶׁר נָתַתָּ לִי, אָמַר לֵיהּ, אִי הָכִי, וְהָכְּתִיב (שמואל א א׳:כ״ו) אֲנִי הָאִשָּׁה הַנִּצֶּבֶת עִמְּכָה בָּזֶה. וְלָא כְּתִיב הַנִּצֶּבֶת לְפָנֶיךָ. אָמַר לֵיהּ, אִי כְּתִיב הַנִּתֶּנֶת עִמְּךָ, הֲוָה אֲמֵינָא הָכֵי, כְּדִכְתִיב אֲשֶׁר נָתַתָּ עִמָּדִי, אֲבָל הַנִּצֶּבֶת כְּתִיב.</p>\n<p>אָמַר לֵיהּ, וְהָא כְּתִיב (בראשית ב׳:י״ח) וַיֹּאמֶר יְיָ' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. אֶעֱשֶׂה לּוֹ הַשְׁתָּא. אָמַר לֵיהּ הָכִי הוּא ודַּאי, דְּאָדָם לְבַדּוֹ הֲוָה, דְּלָא הֲוָה לֵיהּ סֶמֶךְ מִנּוּקְבֵיהּ, בְּגִין דַּהֲוַת בְּסִטְרוֹי כְּמָה דְּאוֹקִימְנָא. וּמַה דְּאָמַר אֶעֱשֶׂה לוֹ עֵזֶר, הָכִי הוּא, דְּלָא כְּתִיב אֶבְרָא לוֹ עֵזֶר, בְּגִין דִּכְתִּיב, (בראשית ה׳:ב׳) זָכָר וּנְקֵבָה בְּרָאָם. אֲבָל אֶעֱשֶׂה כְּתִיב. וּמַהוּ אֶעֱשֶׂה. אַתָקֵן. מַשְׁמַע דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיל לָהּ מִסִּטְרוֹי, וְתָקִין לָהּ בְּתִקּוּנָא, וְאַיְיתֵי לָהּ קַמֵּיהּ. וּכְדֵין אִשְׁתָּמַּשׁ אָדָם בְּאִנְתְּתֵיהּ, וַהֲוָה לֵיהּ סֶמֶךְ.</p>\n<p>וְתָנֵינָן, שְׁפִּירוּ דְּאָדָם קַדְתִּירָא דְּקִיטְרָא עִלָּאָה, מִזִּיהֲרָא דְּנַהֲרָא. שְׁפִּירוּ דְּחַוָּה, דְּלָא הֲווֹ יַכְלִין כָּל בִּרְיָין לְאִסְתַּכְּלָא בָּהּ. וַאֲפִילּוּ אָדָם לָא הֲוָה אִסְתְּכַּל בָּהּ, עַד הַהוּא זִמְנָא דְּחָאבוּ, וְאַעְדִּיאַת (ס\"א ואזעירת) שְׁפִּירוּ דִּלְהוֹן. כְּדֵין אִסְתָּכַּל בָּהּ אָדָם, וְאִשְׁתְּמוֹדַע בָּהּ לְשַׁמְּשָׁא בָּהּ. הֲדָא הוּא דִּכְתִּיב, (בראשית ד׳:כ״ה) וַיֵּדַע אָדָם עוֹד אֶת אִשְׁתּוֹ. וַיֵּדַע: בְּכֹלָּא. וַיֵּדַע: בְּתַשְׁמִישׁ. וַיֵּדַע: דְּאִשְׁתְּמוֹדַע בָּהּ וְאִסְתָּכַּל בָּהּ.</p>"],[9520012187,"<p>וְתָנֵינָן, אָסִיר לֵיהּ לְבַּר נָשׁ לְאִסְתַּכְּלָא בִּשְׁפִּירוּ דְּאִנְתְּתָא, בְּגִין דְּלָא יֵיתֵי בְּהִרְהוּרָא בִּישָׁא, וְיִתְעַקָּר <Nonei></i>לְמִלָּה אָחֳרָא. וְכַךְ הֲוָה רַבִּי שִׁמְעוֹן עָבִיד, כַּד הֲוָה אָזִיל בְּמָתָא, וַהֲווּ חַבְרַיָּיא אַזְלִין אֲבַתְרֵיהּ, וְחָמָא לְאִינְתּוּ שְׁפִּירָאן, מָאִיךְ עֵינֵיהּ, וַהֲוָה אָמַר לְחַבְרַיָּיא אַל תִּפְנוּ.</p>\n<p>וְכָל מַאן דְּיִסְתָּכַּל בִּשְׁפִּירוּ דְּאִנְתְּתָא בִּימָמָא, אָתֵי לְהַרְהוּרֵי בְּלֵילְיָא. וְאִי סָלִיק הַהוּא הִרְהוּרָא בִּישָׁא עִלָּוִיהּ, אַעְבָּר מִשּׁוּם וִאלהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם. תּוּ, אִי שִׁמֵּשׁ בְּאִנְתְּתֵיהּ בְּזִמְנָא דְּסָלִיק בֵּיהּ הַהוּא הִרְהוּרָא בִּישָׁא, אִינּוּן בְּנִין דְּאוֹלִידוּ אֱלֹהֵי מַסֵּכָה אִקְרוּן. וְעַל דָּא כְּתִיב, (ויקרא י״ט:ד׳) אַל תִּפְנוּ אֶל הָאֱלִילִים וִאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם. רִבִּי אַבָּא אָמַר, אָסִיר לֵיהּ לְבַּר נָשׁ לְאִסְתַּכְּלָא בֶּאֱלִילֵי עֲבוֹדָה זָרָה, וּבְנָשֵׁי דְּעַמִּין, וְלָא לְאִתְהַנְיָיא מִנַּיְיהוּ, וְלָא לְאִתְרַפְּאָה בְּהוּ, דְּאָסִיר לֵיהּ לְבַּר נָשׁ לְאִסְתַּכְּלָא בַּאֲתַר דְּלָא אִצְטְרִיךְ.</p>"],[9520012188,"<p>רִבִּי אַבָּא פָּתַח, (תהילים פ״ו:ט״ז) פְּנֵה אֵלַי וְחָנֵּנִי תְּנָה עֻזְּךָ לְעַבְדֶּךָ, פְּנֵה אֵלַי וְחָנֵּנִי, וְכִי לָא הֲוָה לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא שַׁפִּירָא כְּדָוִד, דְּאִיהוּ אָמַר פְּנֵה אֵלַי וְחָנֵּנִי. אֶלָּא הָכִי תָּנֵינָן, דָּוִד אָחֳרָא אִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהוּא מְמָנָא עַל כַּמָה אוּכְלוּסִין עִלָאִין וּמַשִּׁרְיָין. וְכַד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְרַחֲמָא עַל עָלְמָא, אִסְתָּכַּל בְּהַאי דָּוִד, וְנָהִיר לֵיהּ אַנְפִּין, וְהוּא נָהִיר לְעָלְמִין, וְחָיֵיס עָלְמָא.</p>\n<p>וּשְׁפִּירוּ דְּהַאי דָּוִד, נָהִיר לְעָלְמִין כֻּלְּהוּ, רֵישֵׁיהּ גּוּלְגַלְתָּא דְּדַהֲבָא, אִתְרְקִימַת בְּשִׁבְעָה תַּכְשִׁיטֵי זִינִין דְּדַהֲבָא. וְהָא (תיקון קכ\"ב, יתרו ע\"ג) אוּקְמוּהָ. וַחֲבִיבוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לָקֳבְלֵיהּ, וּמִסְּגִיאוּת רְחִימוּתָא דִּילֵיהּ גַּבֵּיהּ, אָמַר לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּיֶהְדַּר עֵינוֹי לָקֳבְלֵיהּ, וְיִסְתְּכַּל בֵּיהּ. בְּגִין דְּאִינּוּן שְׁפִּירָן בְּכֹלָּא, כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו׳:ה׳) הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי וְגוֹ'. הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי דִּבְשַׁעֲתָא דְּאִלֵּין עַיְינִין מִסְתַּכְּלִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, כְּדֵין מִתְעָרִין בְּלִבֵּיהּ קִסְטִין דִּבְלִסְטְרָאֵי, בִּרְחִימוּתָא עִלָּאָה, וּבִסְגִּיאוּת שַׁלְהוֹבִיתָא דִּרְחִימוּ עִלָּאָה לְגַבֵּיהּ, אָמַר הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי, אַסְחַר עֵינֵיךְ לִסְטַר אָחֳרָא מִנִּי, דְּאִינּוּן מוֹקְדִין לִי בְּשַׁלְהוֹבֵי רְחִימוּתָא. וְעַל דָּא כְּתִיב בֵּיהּ בְּדָוִד, (שמואל א ט״ז:י״ב) וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינָיִם וְטוֹב רֹאִי. וּבְגִין הַהוּא דָּוִד עִלָּאָה שַׁפִּירָא, רְחִימְנָא וְתִיאוּבְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא לְאַדְבְּקָא בֵּיהּ. אָמַר דָּוִד פְּנֵה אֵלַי וְחָנֵּנִי.</p>\n<p>כְּגַוְונָא דָּא, (בראשית כ״ז:כ״ז) וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ'. מַשְׁמַע דְּעָאל עִמֵּיהּ עִם יַעֲקֹב גִּנְתָּא דְּעֵדֶן, דְּאִיהוּ שָׂדֶה דְּתַפּוּחִין קַדִּישִׁין. וְכִי הֵיךְ יָכִיל גִּנְתָּא דְּעֵדֶן לְאַעֲלָא עִמֵּיהּ, דְּהָא גִּנְתָּא דְּעֵדֶן כַּמָה רַב הוּא בְּפוּתְיָא וּבְאַרְכָּא. כַּמָה זִינִין דְּבָיְיתִין עִלָּאִין קַדִּישִׁין, דַּרְגִּין עַל דַּרְגִּין, מָדוֹרִין עַל מָדוֹרִין אִית תַּמָּן.</p>\n<p>אֶלָּא (שמות ר\"י ע\"ב) גִּנְתָּא אָחֳרָא עִלָּאָה קַדִּישָׁא אִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהַהוּא גִּנְתָּא רְחִימוּתָא דִּילֵיהּ, וְאִתְדְּבַק בֵּיהּ, וְלָא אִתְנְטִיר אֶלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, דְּהוּא עָיֵיל בֵּיהּ. וְדָא אַחֲסִין קוּדְשָׁא בְּרִיךְ הוּא לְאִשְׁתַּכְּחָא תָּדִיר עִמְּהוֹן דְּצַדִּיקַיָּיא. וְכָּל שֶׁכֵּן לְאִשְׁתַּכְּחָא בֵּיהּ בְּיַעֲקֹב, וְדָא זַמִּין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַעְלָאָה עִמֵּיהּ לְסַיְּיעָא לֵיהּ.</p>\n<p>כְּגַוְונָא דָּא, (בראשית כ״ח:י״ג) אֲנִי יְיָ' אֱלֹהֵי אַבְרָהָם אָבִיךָ וִאלֹהֵי יִצְחָק הָאָרֶץ וְגוֹ'. תְּנָן, מְלַמֵּד שְׁנִתְקַפְּלָה לוֹ אֶרֶץ יִשְׂרָאֵל. וְכִי אֶרֶץ יִשְׂרָאֵל, דְּאִיהִי ד' מֵאוֹת פַּרְסָה עַל ד' מֵאוֹת פַּרְסָה, הֵיךְ אִתְעַקָרַת מֵאַתְרָהּ, וְיָתְבָא תְּחוֹתוֹי. אֶלָּא אֶרֶץ אָחֳרָא עִלָּאָה קַדִּישָׁא אִית לְּקוּדְשָׁא בְּרִיךְ הוּא, וְאֶרֶץ יִשְׂרָאֵל אִקְרֵי. וְהִיא תְּחוֹת דַּרְגָּא דְּיַעֲקֹב דְּקָאִים עָלָהּ. וְאַחֲסִין לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּגִין רְחִימוּתָא דִּלְהוֹן, לְדַיְּירָא עִמְּהוֹן, וּלְדַבְּרָא לְהוֹן, וּלְאַגָּנָא לְהוֹן מִכֹּלָא, וְאִקְרֵי אֶרֶץ חַיִּים.</p>"],[9520012189,"<p>תָּא חֲזֵי, אָסִיר לֵיהּ לְבַר נָשׁ, לְאִסְתַּכְּלָא בַּאֲתַר דְּקוּדְשָׁא בְּרִיךְ הוּא מָאִיס בֵּיהּ, וּרְחִיקָא בֵּיהּ נַפְשֵׁיהּ. וּמַה בְּמַה דְּרָחִים קוּדְשָׁא בְּרִיךְ הוּא, אָסִיר לְאִסְתַּכְּלָא בֵּיהּ, בְּמַה דְּרָחִיק עַל אַחַת כַּמָּה וְכַמָּה. דְתָּא חֲזֵי, אָסִיר לֵיהּ לְבַר נָשׁ לְאִסְתַּכְּלָא בַּקֶּשֶׁת, בְּגִין דְּאִיהוּ חֵיזוֹ דְּדִיּוּקְנָא עִלָּאָה. אָסִיר לֵיהּ לְבַר נָשׁ לְאִסְתַּכְּלָא בְּאָת קַיָּימָא דִּילֵיהּ, בְּגִין דְּהוּא רָמִיז לְצַדִּיקָא דְּעָלְמָא. אָסִיר לֵיהּ לְבַר נָשׁ לְאִסְתַּכְּלָא, בְּאֶצְבְּעָן דְּכַהֲנֵי, בְּשַׁעֲתָא דְּפַרְסֵי יְדַיְיהוּ, בְּגִין דְּתַמָּן שַׁרְיָא יְקָרָא דְּמַלְכָּא עִלָּאָה. וּמַה בַּאֲתַר קַדִּישָׁא עִלָּאָה אָסִיר <Nonei></i>לְאִסְתַּכְּלָא, בַּאֲתַר מִסְאֲבָא רְחִיקָא לָא כָּל שֶׁכֵּן. בְּגִינֵי כַּךְ, אַל תִּפְנוּ אֶל הָאֱלִילִים. רִבִּי יִצְחָק אָמַר, וּמַה לְאִסְתַּכְּלָא בְּהוּ אָסִיר, לְמִפְלַח לְהוּ, אוֹ לְמֶעְבַּד לְהוּ, עַל אַחַת כַּמָה וְכַמָּה.</p>\n<p>וּבְגִּינֵי כַּךְ, אַל תִּפְנוּ אֶל הָאֱלִילִים. הָכָא אָתָא לְאַזְהָרָא לְהוּ לְיִשְׂרָאֵל כְּקַדְמֵיתָא. לָקֳבֵיל (שמות כ׳:ג׳) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי. וִאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם, לָקֳבֵיל לֹא תַעֲשֶׂה לְךָ פֶסֶל אֲנִי יְיָ' אֱלֹהֵיכֶם. לָקֳבֵיל אָנֹכִי יְיָ' אֱלֹהֶיךָ, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ. לָקֳבֵל כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ. וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ, זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. לֹא תִּשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר. לֹא תִשָּׂא אֶת שֵׁם יְיָ' אֱלֹהֶיךָ לַשָּׁוְא. לֹא תִּגְנוֹבוּ, לֹא תִגְנוֹב. וְלֹא תְכַחֲשׁוּ, וְלֹא תְשַׁקְּרוּ אִישׁ בַּעֲמִיתוֹ. לֹא תַעֲנֶה בְרֵעֲךָ עֵד שָׁקֶר. מוֹת יוּמַת הַנּוֹאֵף וְהַנּוֹאָפֶת, לֹא תִנְאָף. לֹא תַעֲמוֹד עַל דַּם רֵעֶךָ, לֹא תִּרְצַח. וְהָא אוּקְמוּהָ, וְעַל דָּא כְּלָלָא דְּאוֹרַיְיתָא, בְּפַרְשְׁתָּא דָּא.</p>"],[9520012190,"<p>אָמַר רִבִּי חִיָיא, בְּקַדְמִיתָא, אָנֹכִי יְיָ' אֱלֹהֶיךָ. זָכוֹר אֶת יוֹם הַשַּׁבָּת. לֹא תִשָּׂא. לֹא תִרְצַח. לֹא תִנְאָף. לֹא תִגְנוֹב. בְּלִישָׁנָא יְחִידָאי. וְהָכָא, אֲנִי יְיָ' אֱלֹהֵיכֶם. אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ. אַל תִּפְנוּ אֶל הָאֱלִילִים. בְּלִישָׁנָא דְּסַגִּיאִין. אֶלָּא תָּא חֲזֵי, מִיּוֹמָא דַּהֲווֹ יִשְׂרָאֵל שְׁכִיחִין בְּעָלְמָא, לָא אִשְׁתְּכָחוּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּלִבָּא חַד, וּבִרְעוּתָא חֲדָא, כְּמָה בְּהַהוּא יוֹמָא דְּקַיְימוּ בְּטוּרָא דְּסִינַי. וְעַל דָּא כֹּלָּא אִתְּמַר בְּלָשׁוֹן יְחִידָאי. לְבָתַר בְּלִישָׁנָא דְּסַגִּיאִין, דְּהָא לָא אִשְׁתְּכָחוּ כָּל כַּךְ בְּהַהוּא רְעוּתָא.</p>\n<p>רִבִּי אֶלְעָזָר הֲוָה אָזִיל לְמֵחֱמֵי לְרִבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוּנְיָא חָמוּי, וַהֲווּ עִמֵּיהּ רִבִּי חִיָּיא וְרִבִּי יוֹסֵי, כַּד מָטוּ חַד בֵּי חֲקַל, יָתְבוּ תְּחוֹת אִילָנָא חֲדָא. אָמַר רִבִּי אֶלְעָזָר, כָּל חַד לֵימָא מִלָּה דְּאוֹרַיְיתָא. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (הושע י״ג:ד׳) וְאָנֹכִי יְיָ' אֱלֹהֶיךָ מֵאֶרֶץ מִצְרָיִם וִאלֹהִים זוּלָתִי לֹא תֵּדָע. לָא כְּתִיב אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרָיִם, אֶלָּא אָנֹכִי יְיָ' אֱלֹהֶיךָ מֵאֶרֶץ מִצְרָיִם, וְכִי מֵאֶרֶץ מִצְרַיִם הֲוָה לְהוּ מַלְכָּא, וְלָא מִקַּדְמַת דְּנָא, וְהָא כְּתִיב (בראשית ל״ה:ב׳) וַיֹּאמֶר יַעֲקֹב אֶל בָּנָיו הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר אֲשֶׁר בְּתוֹכְכֶם. וּכְתִיב (בראשית ל״ה:ג׳) וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל, וְאַתְּ אַמְרַת מֵאֶרֶץ מִצְרָיִם.</p>\n<p>אֶלָּא, מִן יוֹמָא דַּהֲווֹ יִשְׂרָאֵל בְּעָלְמָא, לָא אִשְׁתְּמוֹדָעוּ יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא. בַּר בְּאַרְעָא דְּמִצְרַיִם, דַּהֲווּ בְּהַהוּא פּוּלְחָנָא קַשְׁיָא, וְצָוְוחוּ לָקֳבְלֵיהּ, וְלָא אִשְׁתָּנּוּ מִנִּימוּסָא דִּלְהוֹן לְעָלְמִין. וְתַמָּן אִתְבְּחִינוּ אֲבְהֲתָנָא, כִּדַהֲבָא מִגּוֹ שָׁפְכָה. (ס\"א כפתורא דדהבא מגו טפסא) וְעוֹד, דַּהֲווֹ חָמָאן בְּכָל יוֹמָא, כַּמָה חַרְשִׁין, כַּמָה זִינִין בִּישִׁין, לְאַטְעָאָה לוֹן לִבְנֵי נָשָׁא, וְלָא סָטוּ מֵאָרְחָא לִימִינָא וְלִשְׂמָאלָא. וְאַף עַל גַּב דְּלָא הֲווֹ יַדְעֵי כָּל כַּךְ בִּיקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא הֲווֹ אַזְלִין בָּתַר נִימוּסֵי אֲבָהַתְהוֹן.</p>\n<p>וּלְבָתַר, חָמוּ כַּמָה נִסִּין, וְכַמָּה גְּבוּרָאן, וְנָטַל לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְפוּלְחָנֵיהּ. וּבְגִין דְּכֻלְּהוּ חָמוּ כַּמָה נִסִּין וְאָתִין בְּעֵינֵיהוֹן, וְכָל אִינּוּן אָתִין וּגְבוּרָן. אָמַר וְאָנֹכִי יְיָ' אֱלֹהֶיךָ מֵאֶרֶץ מִצְרָיִם. דְּתַמָּן הֲוָה בְּאִתְגַּלְיָיא יְקָרָא דִּילֵיהּ. וְאִתְגְּלֵי עָלַיְיהוּ עַל יַמָּא, וְחָמוּ זִיו יְקָרָא עִלָּאָה דִּילֵיהּ אַפִּין בְּאַפִּין. דְּלָא תֵּימְרוּן אֱלָהָא אָחֳרָא הוּא דְּמַלִּיל עִמָּנָא, אֶלָּא אֲנָא הוּא דַּחֲמִיתוּן בְּאַרְעָא דְּמִצְרַיִם, אֲנָא הוּא דְּקָטַלְנָא סָנְאֵיכוֹן בְּאַרְעָא דְּמִצְרַיִם. אֲנָא הוּא דְּעָבֵדְנָא כָּל אִינּוּן עֶשֶׂר מְחָאָן בְּאַרְעָא דְּמִצְרַיִם. וּבְגִּינֵי כַּךְ, וִאלֹהִים זוּלָתִי לֹא תֵדָע, דְּלָא תֵּימָא דְּאָחֳרָא הֲוָא, אֶלָּא אֲנָא הוּא כֹּלָּא.</p>"],[9520012191,"<p>תּוּ פָּתַח, (ויקרא י״ט:י״ג-י״ד) לֹא תַעֲשׁוֹק אֶת רֵעֲךָ וְלֹא תִגְזוֹל לֹא תָלִין פְּעוּלַּת שָׂכִיר אִתְּךָ עַד בֹּקֶר. לֹא תָּלִין פְּעוּלַּת שָׂכִיר אֲמַאי. אֶלָּא מִקְּרָא אָחֳרָא אִשְׁתְּמַע, דִּכְתִּיב, (דברים כ״ד:ט״ו) בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ וְלֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ כִּי עָנִי הוּא וְאֵלָיו הוּא נוֹשֵׂא אֶת נַפְשׁוֹ. לֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ, אִזְדְּהַר דְּלָא תִּתְכְּנִש בְּגִינוֹי מֵעָלְמָא, עַד לָא יִמְטֵי זִמְנָךְ לְאִתְכַּנְּשָׁא. כְּמָה דְּאַתְּ אָמֵר, (קהלת י״ב:ב׳) עַד אֲשֶׁר לֹא תֶחְשַׁךְ הַשֶּׁמֶשׁ וְגוֹ'. מֵהָכָא אוֹלִיפְנָא מִלָּה אָחֳרָא, מַאן דְּאַשְׁלִים לְנַפְשָׁא דְּמִסְכְּנָא. אֲפִילּוּ <Nonei></i>דְּמָטוּ יוֹמוֹי לְאִסְתַּלְּקָא מֵעָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא אַשְׁלִים לְנַפְשֵׁיהּ, וְיָהִיב לֵיהּ חַיִּין יַתִּיר.</p>\n<p>לֹא תָלִין פְּעוּלַּת שָׂכִיר, תָּא חֲזֵי, מַאן דְּנָטִיל אַגְרָא דְּמִסְכְּנָא, כְּאִילּוּ נָטִיל נַפְשֵׁיהּ, וּדְאַנְשֵׁי בֵּיתֵיהּ. הוּא אַזְעַר נַפְשַׁיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא אַזְעִיר יוֹמוֹי, וְאַזְעַר נַפְשֵׁיהּ, מֵהַהוּא עָלְמָא. דְּהָא כָּל אִינּוּן הֲבָלִים דְּנַפְקֵי מִפּוּמֵיהּ, כָּל הַהוּא יוֹמָא, כֻּלְּהוּ סַלְּקִין קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְקַיְימִין קַמֵּיהּ, לְבָתַר סַלְּקָא נַפְשֵׁיהּ, וְנַפְשַׁיְיהוּ דְּאַנְשֵׁי בֵּיתֵיהּ, וְקַיְימִין, בְּאִינּוּן הֲבָלִים דְּפוּמֵיהּ. וּכְדֵין, אֲפִילּוּ אִתְגְּזַר עַל הַהוּא בַּר נָשׁ כַּמָה יוֹמִין, וְכַמָּה טָבָאן, כֻּלְּהוּ מִתְעַקְּרָאן מִנֵּיהּ, וּמִסְתַּלְקֵי מִנֵּיהּ.</p>\n<p>וְלֹא עוֹד, אֶלָּא דְּנַפְשָׁא דִּילֵיהּ לָא סַלְּקָא לְעֵילָּא, וְהַיְינוּ דְּאָמַר רִבִּי אַבָּא, רַחֲמָנָא לִשֵׁזְבִינָן מִנַּיְיהוּ, וּמֵעֶלְבּוֹנַיְיהוּ. וְאוֹקְמוּהָ אֲפִילּוּ עָשִׁיר הוּא, וְאֵלָיו הוּא נוֹשֵׂא אֶת נַפְשׁוֹ דַּיְיקָא, אֲפִילּוּ מִכָּל בַּר נָשׁ נָמֵי, וְכָּל שֶׁכֵּן מִסְכְּנָא. וְהַיְינוּ דְּהֲוָה רַב הַמְנוּנָא עָבִיד, כַּד הֲוָה הַהוּא אָגִיר מִסְתְּלַק מֵעַבִידְתֵּיהּ, הֲוָה יָהִיב לֵיהּ אַגְרֵיהּ, וְאָמַר לֵיהּ, טוֹל נַפְשָׁךְ דְּאַפְקִידַת בִּידָאי, טוֹל פִּקְדוֹנָךְ.</p>\n<p>וַאֲפִילּוּ אָמַר יְהֵא בִּידָךְ, דַּאֲנָא (לא) בָּעֵינָא לְסַלְּקָא אַגְרִי. לָא הֲוָה בָּעֵי. אָמַר פִּקְדוֹנָא דְּגוּפָךְ, לָא אִתְחֲזֵי לְאִתְפָּקְדָא בִּידִי, כָּל שֶׁכֵּן פִּקְדוֹנָא דְּנַפְשָׁא. דְּהָא פִּקְדוֹנָא דְּנַפְשָׁא לָא אִתְיְהִיבַת, אֶלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב, (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי, אָמַר רִבִּי חִיָּיא, וּבִידָא דְּאָחֳרָא שָׁארֵי. אָמַר לֵיהּ, אֲפִילּוּ בִּידֵיהּ, בָּתַר דְּיָהִיב.</p>\n<p>כְּתִיב לֹא תָלִין פְּעוּלַּת שָׂכִיר, וּכְתִיב וְלֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ. אֶלָּא הָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי לֵית לָךְ יוֹמָא וְיוֹמָא, דְּלָא שַׁלְטָא בֵּיהּ יוֹמָא עִלָּאָה אָחֳרָא. וְאִי אִיהוּ לָא יָהִיב לֵיהּ נַפְשָׁא דִּילֵיהּ בְּהַהוּא יוֹמָא, כְּמַאן דְּפָגִים לְהַהוּא יוֹמָא עִלָּאָה. וּבְגִּינֵי כַּךְ בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ, וְלֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ. וְהָא דְּאִתְּמַר לֹא תָלִין, בְּגִין דְּנַפְשֵׁיהּ לָא סָלִיק, וְסָלִיק הַהוּא נַפְשָׁא דְּמִסְכְּנָא, וּדְאַנְשֵׁי בֵּיתֵיהּ, כְּמָה דְּאִתְּמַר.</p>"],[9520012192,"<p>רִבִּי חִיָּיא פָּתַח וְאָמַר קְרָא אֲבַתְרֵיהּ, (ויקרא י״ט:י״ד) לֹא תְּקַלֵּל חֵרֵשׁ וְלִפְנֵי עִוִּר וְגוֹ', הַאי קְרָא כְּמַשְׁמָעוֹ. אֲבָל פַּרְשְׁתָּא דָּא, כֹּלָּא אוֹלִיפְנָא מִינָּהּ מִלִּין אָחֳרָנִין, וְכֻלְּהוּ תַּלְיָין דָּא בְּדָא. תָּא חֲזֵי, מַאן דְּלָיִיט לְחַבְרֵיהּ, וְאִיהוּ קַמֵּיהּ, וְאַכְסִיף לֵיהּ, כְּאִלּוּ אוֹשִׁיד דָּמֵיהּ, וְהָא אוֹקִימְנָא. וְהַאי קְרָא, דְּלָאו חַבְרֵיהּ עִמֵּיהּ, וְהוּא לָיִיט לֵיהּ, הַהִיא מִלָּה סַלְּקָא.</p>\n<p>דְּלֵית לָךְ מִלָּה וּמִלָּה דְּנָפִיק מִפּוּמֵיהּ, דְּלָא אִית לֵיהּ קָלָא, הַהוּא קָלָא סָלִיק לְעֵילָּא, וְכַמָּה קַסְטְרִין מִתְחַבְּרָן עִמֵּיהּ דְּהַהוּא קָלָא, עַד דְּסַלְּקָא וְאִתְּעַר אֲתַר דִּתְהוֹמָא רַבָּא, כְּמָה דְּאוּקְמוּהָ וְכַמָּה מִתְעָרִין עָלֵיהּ דְּהַהוּא בַּר נָשׁ. וַוי לְמַאן דְּאַפִּיק מִלָּה בִּישָׁא מִפּוּמֵיהּ, וְהָא אוּקְמוּהָ.</p>\n<p>וְלִפְנֵי עִוִּר לֹא תִתֵּן מִכְשׁוֹל, כְּמַשְׁמָעוֹ. וְאוּקְמוּהָ, בְּמַאן דְּגָרִים לְאָחֳרָא לְמֶחֱטֵי. וְכֵן מַאן דְּמָחֵי לִבְרֵיהּ רַבָּא. וְלִפְנֵי עִוִּר לֹא תִתֵּן וְגוֹ', בְּמַאן דְּלָא מָטָא לְהוֹרָאָה וְאוֹרֵי, (כמה דאת אמר) דִּכְתִּיב, (משלי ז׳:כ״ו) כִּי רַבִּים חֲלָלִים הִפִּילָה וַעֲצוּמִים כָּל הֲרוּגֶיהָ. וְהַאי אַעְבָּר, מִשּׁוּם וְלִפְנֵי עִוִּר לֹא תִתֵּן מִכְשׁוֹל, בְּגִין דְּאַכְשִׁיל לֵיהּ לְחַבְרֵיהּ לְעָלְמָא דְּאָתֵי.</p>\n<p>דְּתָנֵינָן מַאן דְּאָזִיל בְּאוֹרַח מֵישַׁר בְּאוֹרַיְיתָא, וּמַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא כְּדְקָא יָאוּת, אִית לֵיהּ חוּלָקָא טָבָא תָּדִיר לְעָלְמָא דְּאָתֵי. דְּהַהִיא מִלָּה דְּאוֹרַיְיתָא דְּאַפִּיק מִפּוּמֵיהּ, אַזְלָא וְשָׁאֲטָא בְּעָלְמָא, וְסַלְּקָא לְעֵילָּא. וְכַמָּה עִלָּאִין קַדִּישִׁין מִתְחַבְּרָאן בְּהַהִיא מִלָּה, וְסַלְּקָא בְּאוֹרַח מֵישָׁר, וְאִתְעַטָּר בְּעִטְרָא קַדִּישָׁא, וְאִסְתֲּחֵי בְּנַהֲרָא דְּעָלְמָא דְּאָתֵי, דְּנָגִיד וְנָפִיק מֵעֵדֶן, וְאִתְקַבַּל בֵּיהּ, וְאִשְׁתְּאַב בְּגַוִיהּ, וְאִתְעַנָּג (ס\"א ואתנטע) סוֹחֲרָנֵיהּ דְּהַהוּא נַהֲרָא, אִילָנָא עִלָּאָה. וּכְדֵין נָגִיד וְנָפִיק נְהוֹרָא עִלָּאָה וְאִתְעַטָּר בֵּיהּ בְּהַהוּא בַּר נָשׁ כָּל יוֹמָא, כְּמָה דְּאִתְּמַר. (יתרו נ\"ז ע\"א).</p>\n<p>וּמַאן דְּלָעֵי (נ\"א דיליף) בְּאוֹרַיְיתָא, וְלָא אִשְׁתָּדַּל בָּהּ בְּאוֹרַח קְשׁוֹט, <Nonei></i>וּבְאוֹרַח מֵישָׁר. הַהוּא מִלָּה סַלְּקָא, וְסָטֵי אוֹרְחִין, וְלֵית מַאן דְּיִתְחַבָּר בָּהּ, וְכֹלָּא דַּחְיָּין לָהּ לְבַר, וְאָזִיל וְשָׁאט בְּעָלְמָא וְלָא יִשְׁכַּח אֲתַר. מַאן גָּרִים לֵיהּ הַאי. הַהוּא דְּסַאטֵי לֵיהּ מֵאוֹרַח מֵישָׁר, הֲדָא הוּא דִכְתִיב וְלִפְנֵי עִוִּר לֹא תִתֵּן מִכְשׁוֹל. וּבְגִּינֵי כַּךְ כְּתִיב, וְיָרֵאתָ מֵּאֱלֹהֶיךָ אֲנִי יְיָ'.</p>\n<p>וּמַאן דְּתִיאוּבְתֵּיה לְמִלְעֵי בְּאוֹרַיְיתָא, וְלָא אַשְׁכַּח מַאן דְּיוֹלִיף לֵיהּ, וְהוּא בִּרְחִימוּתָא דְּאוֹרַיְיתָא, לָעֵי בָּהּ, וּמְגַּמְגֵּם בָּהּ, בְּגִמְגוּמָא דְּלָא יָדַע. כָּל מִלָּה וּמִלָּה סַלְּקָא, וְקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי בְּהַהִיא מִלָּה, וְקַבִּיל לָהּ, וְנָטַע לָהּ סָחֲרָנֵיהּ דְּהַהוּא נַחֲלָא, וְאִתְעָבִידוּ מֵאִלֵּין מִלִּין אִילָנִין רַבְרְבִין, וְאִקְרוּן עַרְבֵי נַחַל, הֲדָא הוּא דִכְתִיב, (משלי ה׳:י״ט) בְּאַהֲבָתָהּ תִּשְׁגֶּה תָמִיד.</p>\n<p>וְדָוִד מַלְכָּא אָמַר, (תהילים פ״ו:י״א) הוֹרֵנִי יְיָ' דַּרְכֶּךָ אֲהַלֵךְ בַּאֲמִתֶּךָ. וּכְתִיב (תהילים כ״ז:י״א) וּנְחֵנִי בְּאֹרַח מִישׁוֹר לְמַעַן שׁוֹרְרָי. זַכָּאִין אִינּוּן דְּיַדְעִין אוֹרְחוֹי דְּאוֹרַיְיתָא, וּמִשְׁתַּדְּלֵי בָּהּ בְּאֹרַח מֵישָׁר, דְּאִינּוּן נַטְעִין אִילָנִין דְּחַיִּין לְעֵילָּא, דְּכֻלְּהוּ אַסוּותָא. וּבְגִין כַּךְ כְּתִיב, (מלאכי ב׳:ו׳) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ. וְכִי אִית תּוֹרָה דְּלָאו אִיהִי אֱמֶת. אִין כְּגַוְונָא דְּאַמָרָן, דְּאוֹרֵי מַאן דְּלָא יָדַע, וְלָאו אִיהוּ קְשׁוֹט וְהַהוּא דְּאוֹלִיף מִלָּה מִינֵיהּ, אוֹלִיף מִלָּה דְּלָאו אִיהוּ אֱמֶת. וּבְגִּינֵי כַּךְ כְּתִיב, תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ.</p>\n<p>וְעִם כָּל דָּא, מִבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵילַף מִלֵּי דְּאוֹרַיְיתָא מִכָּל בַּר נָשׁ, אֲפִילּוּ מִמַּאן דְּלָא יָדַע. בְּגִין דְּעַל דָּא יִתְּעַר בְּאוֹרַיְיתָא, וְיֵיתֵי לְמֵילַף מִמַּאן דְּיָדַע, וּלְבָתַר אִשְׁתְּכַח, דְּאָזִיל בָּהּ בְּאוֹרַיְיתָא בְּאֹרַח קְשׁוֹט. תָּא חֲזֵי, יִשְׁתְּדַל בַּר נָשׁ בְּעָלְמָא בְּאוֹרַיְיתָא וּפִקּוּדוֹי, אֲפִילּוּ דְּלָא עָבִיד לִשְׁמָהּ, דְּמִתּוֹךְ שֶׁלֹּא לִשְׁמָהּ בָּא לִשְׁמָהּ.</p>"],[9520012193,"<p>רִבִּי יוֹסֵי פָּתַח קְרָא אֲבַתְרֵיהּ וְאָמַר, (ויקרא י״ט:ט״ו) לֹא תַעֲשׂוּ עָוְל בַּמִּשְׁפָּט וְגוֹ'. לֹא תַּעֲשׂוּ עָוְל בַּמִּשְׁפָּט, כְּמַשְׁמָעוֹ. אֲבָל הָא אִתְּמַר, דְּפַרְשְׁתָּא דָּא מִלִּין עִלָּאִין וְיַקִּירִין אִית בָּהּ בְּפִקּוּדֵי אוֹרַיְיתָא. הַאי קְרָא מִסּוֹפֵיהּ קָא מַשְׁמַע, דִּכְתִּיב בְּצֶדֶק תִּשְׁפּוֹט עֲמִיתֶךָ. תָּא חֲזֵי, תְּרֵי דַּרְגִּין אִינּוּן הָכָא: מִשְׁפָּט, וְצֶדֶק. מַה בֵּין הַאי לְהַאי. אֶלָּא חַד רַחֲמֵי, וְחַד דִּינָא, וְדָא אִתְבְּסָם בְּדָא.</p>\n<p>כַּד אִתְּעַר צֶדֶק, דָּאִין דִּינָא לְכֹלָּא כַּחֲדָא, דְּלֵית בֵּיהּ רַחֲמֵי, וְלָאו וַותְּרָנוּתָא. כַּד אִתְּעַר מִשְׁפָּט, אִית בֵּיהּ רַחֲמֵי. יָכוֹל יְהֵא כֹּלָּא בְּמִּשְׁפָּט. אָתָא קְרָא וְאָמַר, בְּצֶדֶק תִּשְׁפּוֹט עֲמִיתֶךָ. מַאי טַעְמָא. בְּגִין דְּצֶדֶק לָאו דָּאִין לְדָא וְשָׁבִיק לְדָא, אֶלָּא כֻּלְּהוּ כַּחֲדָא בְּשִׁקּוּלָא חֲדָא. כְּגַוְונָא דָּא לֹא תִשָּׂא פְנֵי דָל וְלֹא תֶהְדַּר פְּנֵי גָּדוֹל, אֶלָּא כֻּלְּהוּ בְּשִׁקּוּלָא חֲדָא, בְּצֶדֶק. יָכוֹל יְהֵא כֹּלָּא דִּינָא בְּצֶדֶק בִּלְחוֹדוֹי. אָתָא קְרָא וְאָמַר תִּשְׁפּוֹט, דְּבָעֵי לְחַבְּרָא לְהוּ כַּחֲדָא, דְּלָא יִשְׁתְּכַּח דָּא בְּלָא דָּא, וְהַאי שְׁלִימוּ דְּדִינָא.</p>\n<p>וְכָּל כַּךְ לָמָּה. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא שְׁכִיחַ תַּמָּן. וּבְגִּינֵי כַּךְ בָּעֵי לְאַשְׁלְמָא דִּינָא. כְּגַוְונָא דְּאִיהוּ עָבִיד לְתַתָּא, כְּגַוְונָא דִּילֵיהּ מַמָּשׁ עָבִיד לְעֵילָּא. וְתָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא שַׁוִּי כּוּרְסְיָיא דְּדִינָא, בְּשַׁעֲתָא דְּדַיָינֵי יַתְבִין, הֲדָא הוּא דִכְתִיב, (תהילים ט׳:ח׳) כּוֹנֵן לְמִשְׁפָּט כִּסְאוֹ. וּמִתַּמָּן אִתְתָּקַּן כּוּרְסְיָה דְּקוּדְשָׁא בְּרִיךְ הוּא. וּמַאן אִיהוּ כּוּרְסְיָה. אִלֵּין אִינּוּן צֶדֶק וּמִשְׁפָּט. הֲדָא הוּא דִכְתִיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ. וּמַאן דְּדָאִין דִּינָא, בָּעֵי לְמֵידַן (ס\"א למיתב) בְּכוּרְסְיֵהּ דְּמַלְכָּא. וְאִי פָּגִים חַד מִנַּיְיהוּ, כְּאִלּוּ פָּגִים לְכוּרְסֵיהּ דְּמַלְכָּא. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא אִסְתְּלַּק מִבֵּינַיְיהוּ דְּדַיְינֵי, וְלָא קָאִים בְּדִינַיְיהוּ. וּמַאי אָמַר. (תהילים י״ב:ו׳) עַתָּה אָקוּם יֹאמַר יְיָ' וְגוֹ'. וְרוּחָא דְּקוּדְשָׁא אָמַר, (תהילים נ״ז:ו׳) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים.</p>"],[9520012194,"<p><Noneb>רעיא מהימנא</b> (ויקרא י״ט:י״ז) לֹא תִשְׂנָא אֶת אָחִיךָ בִּלְבָבֶךָ הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ וְגוֹ'. פִּקּוּדָא דָּא, לְאוֹכָחָא לְהַהוּא דְּחָטֵי, לְמֵחֱזִי לֵיהּ רְחִימוּ סַגְיַא, דְּרָחִים לֵיהּ, בְּגִין דְּלָא יִתְעֲנָשׁ אִיהוּ. דְּהָא בְּקוּדְשָׁא בְּרִיךְ הוּא כְּתִיב, (משלי ג׳:י״ב) כִּי אֶת אֲשֶׁר יֶאֱהַב יְיָ' יוֹכִיחַ. וּכְמָּה דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד וְאוֹכַח לְמַאן דְּרָחִים לֵיהּ, הָכִי יוֹלִיף בַּר נָשׁ מֵהַהוּא אָרְחָא, וְיוֹכַח לְחַבְרֵיהּ. קוּדְשָׁא בְּרִיךְ הוּא בְּמַאי אוֹכַח לְבַּר נָשׁ. אוֹכַח לֵיהּ בִּרְחִימוּ בְּסִתְרָא, אִי יְקַבֵּל לֵיהּ יָאוּת. וְאִי לָא, אוֹכַח לֵיהּ בֵּין רְחִימוֹי. אִי יְקַבֵּל יָאוּת. וְאִי לָא, אוֹכַח לֵיהּ בְּאִתְגַּלְיָיא לְעֵינֵיהוֹן דְּכֹלָּא. אִי יְקַבֵּל יָאוּת. וְאִי לָאו, שָׁרִי לֵיהּ, וְלָא אוֹכַח לֵיהּ, וְשָׁבִיק <Nonei></i>לֵיהּ יֵיזִיל וְיַעְבִיד רְעוּתֵיהּ.</p>\n<p>בְּקַדְמִיתָא אוֹדַע לֵיהּ בְּסִתְרָא, בְּגִין לְאוֹכָחָא לֵיהּ, וּלְאִתְעֲרָא לֵיהּ, דְּלָא יִנְּדַע בֵּיהּ בַּר נָשׁ. וְדָא אִיהוּ בֵּינֵיהּ לְבֵינֵיהּ. אִי מְקַבֵּל יָאוּת. וְאִי לָאו, אוֹדַע לֵיהּ בֵּין רְחִימוֹי, בְּזִמְנָא דְּכַהֲנָא רַבָּא הֲוָה בְּעָלְמָא, יָהִיב לֵיהּ מַרְעִין בְּעַרְסֵיהּ, וְאָתוּ רְחִימוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאוֹדְעָן לֵיהּ, אִי אִית בֵּיהּ חוֹבָא דְּיֵיתוּב מִנֵּיהּ, וּלְעָיֵין בְּמִלֵיהּ. אִי מְקַבֵּל יָאוּת, וְאִי לָאו אוֹכַח לֵיהּ בְּאִתְגַּלְיָיא, בְּמָמוֹנֵיהּ, בִּבְנוֹי, דְּכֹלָּא מְלַחֲשָׁן עָלֵיהּ, וְיִיתוּן לְגַבֵּיהּ. אִי מְקַבֵּל יָאוּת. וְאִי לָאו שָׁארֵי לֵיהּ מָארֵיהּ לְמֶעְבַּד רְעוּתֵיהּ, וְלָא יַתְקִיף בֵּיהּ לְעָלְמִין. כְּגַוְונָא דָּא אִצְּטְרִיךְ לֵיהּ לְאוֹכָחָא לְחַבְרֵיהּ בְּקַדְמִיתָא בְּסִתְרָא. לְבָתַר בֵּין רְחִימוֹי. לְבָתַר בְּאִתְגַּלְיָיא. מִכָּאן וּלְהָלְאָה יִשְׁבּוֹק לֵיהּ וְיַעְבִּיד רְעוּתֵיהּ.</p>\n<p>וְעַל דָּא כְּתִיב הוֹכֵחַ תּוֹכִיחַ. הוֹכֵחַ: בְּסִתְרָא, דְּלָא יִנְּדַע בֵּיהּ בַּר נָשׁ. תּוֹכִיחַ: בֵּין חַבְרוֹי וּרְחִימוֹי. אֶת עֲמִיתֶךָ: בְּאִתְגַּלְיָיא. וְעַל דָּא לָא כְּתִיב בְּקַדְמִיתָא תּוֹכִיחַ, אֶלָּא הוֹכֵחַ. תּוּ הוֹכֵחַ, אִי אִיהוּ בַּר נָשׁ דְּיִכְסוּף, לָא יִימָּא לֵיהּ וְלָא יוֹכִיחַ לֵיהּ אֲפִילּוּ בְּסִתְרָא, אֶלָּא יִימָּא קַמֵּיהּ, כְּמָאן דְּמִשְׁתָּעֵי בְּמִלִּין אָחֳרָנִין. וּבְגוֹ אִינּוּן מִלִּין, יִדְכַּר מַאן דְּעָבַד הַהוּא חוֹבָא הוּא כַּךְ וְכַךְ, בְּגִין דְּאִיהוּ יְדַע בְּגַרְמֵיהּ, וְיִשְׁתְּבִיק מֵהַהוּא חוֹבָא. וְעַל דָּא הוֹכֵחַ. וְאִם לָאו, תּוֹכִיחַ. וּלְבָתַר אֶת עֲמִיתֶךָ בְּאִתְגַּלְיָיא. מִכָּאן וּלְהָלְאָה וְלֹא תִשָּׂא עָלָיו חֵטְא.</p>\n<p>דָּבָר אַחֵר וְלֹא תִשָּׂא עָלָיו חֵטְא, דְּהָא כֵּיוָן דְּבַּר נָשׁ אוֹכַח לְחַבְרֵיהּ, וְאִזְדְּמַן לְאוֹכָחָא לֵיהּ בְּאִתְגַּלְיָא, לָא יְסַלֵּק קַמֵּיהּ הַהוּא חוֹבָה דַּעֲבֵיד, דְּאָסִיר לֵיהּ וַדַאי, אֶלָּא יֵימָּא סְתָם, וְלָא יְסַלֵּק עֲלוֹי הַהוּא חוֹבָא בְּאִתְגַּלְיָיא, וְלָא יַרְשִׁים עֲלוֹי חוֹבָא, דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עַל יְקָרָא דְּבַר נָשׁ, אֲפִילּוּ בְּחַיָּיבַיָא. (ע\"כ רעיא מהימנא) (פקודא ח\"י לברכא ליה לקודשא בריך הוא וכו' ר\"ע ע\"ב)</p>\n<p>פָּתַח וְאָמַר, וַיְהִי קוֹל הַשּׁוֹפָר הוֹלֵךְ וְגוֹ'. וַיְהִי קוֹל הַשּׁוֹפָר, הָכָא אִתְפְּלִיגוּ סִפְרֵי קַדְמָאֵי וְכוּ', עַד דְּאָתוּ רִבִּי אַבָּא וְרִבִּי יְהוּדָה, וְאוֹדוּ לֵיהּ לְרִבִּי אֲחָא. (אמר המגיה מצאתי כתוב כאן זה המאמר ויען שכבר הודפס פרשת ויקרא דף ו' ע\"ב שורה כ\"ב ומסיים בדף ח' ע\"א שורה כ\"ו, לא רציתי להדפיסו פעם שנית)</p>"],[9520012195,"<p>קָמוּ, עַד דַּהֲווּ אַזְלֵי, אָמַר רִבִּי אֶלְעָזָר לֹא תֵלֵךְ רָכִיל בְּעַמֶּךָ לֹא תִשְׂנָא אֶת אָחִיךָ לֹא תִקּוֹם וְלֹא תִטּוֹר. הָא אוֹקִימְנָא לוֹן, וְכֻלְּהוּ אַתְעֲרוּ עָלַיְיהוּ חַבְרַיָּיא, אֲבָל נֵימָא מִלָּה בְּפָרְשָׁתָא דָּא, כְּתִיב, אֶת חֻקּוֹתַי תִּשְׁמוֹרוּ בְּהֶמְתְּךָ לֹא תַרְבִּיעַ כִּלְאַיִם שָׂדְךָ לֹא תִּזְרַע כִּלְאָיִם וּבֶגֶד כִּלְאַיִם שַׁעֲטְנֵז לֹא יַעֲלֶה עָלֶיךָ.</p>\n<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (ישעיהו מ״ג:י׳) אַתֶּם עֵדַי נְאֻם יְיָ' וְעַבְדִּי אֲשֶׁר בָּחַרְתִּי לְמַעַן תֵּדְעוּ וְתַאֲמִינוּ וְגוֹ'. אַתֶּם עֵדַי, אִלֵּין אִינּוּן יִשְׂרָאֵל. וְתָנֵינָן, אִלֵּין אִינּוּן שְׁמַיָּא וְאַרְעָא, דִּכְתִיב (דברים ל׳:י״ט) הֲעִידוֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אֲבָל יִשְׂרָאֵל אִינּוּן סָהֲדִין אִלֵּין עַל אִלֵּין, וּשְׁמַיָא וְאַרְעָא וְכֹלָּא, סָהֲדִין עָלַיְיהוּ. וְעַבְדִּי אֲשֶׁר בָּחַרְתִּי, דָּא יַעֲקֹב, דִּכְתִיב (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר, וּכְתִיב, (ירמיהו ל׳:י׳) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב. וְאִית דְּאַמְרֵי דָּא דָּוִד. וְדָוִד עַבְדִּי אִקְרֵי, דִּכְתִּיב, (ישעיהו ל״ז:ל״ה) לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי אֲשֶׁר בָּחַרְתִּי, דָּא דָּוִד עִלָּאָה.</p>\n<p>לְמַעַן תֵּדְעוּ וְתַאֲמִינוּ לִי וְתָבִינוּ כִּי אֲנִי הוּא. מַאי כִּי אֲנִי הוּא. דְּאִתְרָעִיתִי בְּהַהוּא דָּוִד, וּבְהַהוּא יַעֲקֹב. אֲנָא, הוּא מַמָּשׁ. לְפָנַי לֹא נוֹצַר אֵל, דְּתָנֵינָן, קְרָא קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב אֵל, דִּכְתִיב, (בראשית ל״ג:כ׳) וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. קוּדְשָׁא בְּרִיךְ הוּא קָרָא לְיַעֲקֹב אֵל. הֲדָא הוּא דִכְתִיב, לְפָנַי לֹא נוֹצַר אֵל וְאַחֲרַי לֹא יִהְיֶה. וּבְגִין כָּךְ, אֲנִי הוּא. כֹּלָּא כְּמָה דְּאִתְּמַר. וְאַחֲרַי לֹא יִהְיֶה, דְּהָא דָּוִד הָכִי אִקְרֵי, וְלָאו אִית בַּתְרֵיהּ אָחֳרָא.</p>\n<p>תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, אַתְקִין כָּל מִלָּה וּמִלָּה, כָּל חַד וְחַד בְּסִטְרוֹי. וּמָנֵי עָלַיְיהוּ חֵילִין עִלָּאִין. וְלֵית לָךָ אֲפִילּוּ עִשְׂבָּא זְעֵירָא בְּאַרְעָא, דְּלֵית לֵיהּ חֵילָא עִלָּאָה לְעֵילָּא. וְכָל מַה דְּעָבְדִין בְּכָל חַד וְחַד, (תרי נוסחי) וְכָל מַה דְּכָל חַד וְחַד עָבִיד, כֹּלָּא הוּא בִּתְקִיפוּ דְּהַהִיא חֵילָא עִלָּאָה, דִּמְמָנָא עָלֵיהּ לְעֵילָּא. וְכֻלְּהוּ נִמוּסִין גְּזִירִין מִדִּינָא, עַל דִּינָא נַטְלִין, וְעַל דִּינָא קַיְימִין. לֵית מַאן דְּנָפִיק <Nonei></i>מִן קִיּוּמֵיהּ לְבַר.</p>\n<p>וְכֻלְּהוּ מְמָנָן, מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, מִתְפַּקְדָן שִׁלְטוֹנִין עַל כָּל מִלָּה וּמִלָּה. וְכֻלְּהוּ נַטְלִין עַל נִימוּסָא אָחֳרָא עִלָּאָה, דְּנַטְלִין כָּל חַד וְחַד. כְּמָה דִּכְתִּיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. כֵּיוָן דְּנַטְלִין הַהוּא חֹק, כֻּלְּהוּ אִקְרוּן חֻקּוֹת, וְהַהוּא חֹק דְּאִתְיְיהִיב לְהוּ, מִן שְׁמַיָּא קָא אָתֵי, וּכְדֵין אִתְקְרוּן חֻקּוֹת שָׁמַיִם. וּמְנָלָן דְּמִן שָׁמַיִם קָא אַתְיָין. דִּכְתִיב (תהילים פ״א:ה׳) כִּי חֹק לְיִשְׂרָאֵל הוּא.</p>\n<p>וְעַל דָּא כְּתִיב, אֶת חֻקּוֹתַי תִּשְׁמוֹרוּ בְּגִין דְּכָל חַד וְחַד מְמָנָא עַל מִלָּה יְדִיעָא בְּעָלְמָא, בְּהַהוּא חֹק. בְּגִין כַּךְ אָסִיר לְמִחְלַף זִינִין, וּלְאַעֲלָא זִינָא בְּזִינָא אָחֳרָא. בְּגִין דְּאָעֲקָר לְכָל חֵילָא וְחֵילָא מֵאַתְרַיְיהוּ, (אכחיש פמליא של מעלה) וְאַכְחִישׁ פּוּמְבִּי דְּמַלְכָּא.</p>\n<p>כִּלְאַיִם, מַהוּ כִּלְאַיִם. כְּמָאן דְּיָהִיב אָחֳרָא בְּבֵי מַטְרָא, כְּמָה דְאַתְּ אָמֵר (ירמיה לז) אֶל בֵּית הַכֶּלֶא, בְּגִין דְּלָא לְמֶעְבַּד מִידִי. כִּלְאַיִם: מְנִיעוּתָא, דְּמָנַע לְכָל אִינּוּן חֵילִין מֵעֲבִידָתָא דִּלְהוֹן. כִּלְאַיִם: עִרְבּוּבְיָיא, דְּעָבִיד עִרְבּוּבְיָא בְּחֵילָא דִּלְעֵילָּא, וְאַכְחִישׁ פּוּמְבִּי דְּמַלְכָּא, כְּמָה דְּאִתְּמַר, (ובגין כך) וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז לֹא יַעֲלֶה עָלֶיךָ.</p>\n<p>תָּא חֲזֵי, כְּתִיב (בראשית ב׳:י״ז) וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָמוּת. וְהָא אִתְּמַר, דְּשָׁנֵי פִּקּוּדוֹי דְּמַלְכָּא, וְאַחְלַף עֵץ חַיִּים, דְּבֵיהּ אִשְׁתְּלִים כֹּלָּא, וּבֵיהּ תַּלְיָא מְהֵימְנוּתָא, וְאִתְדְּבַק בַּאֲתַר אָחֳרָא. וְהָא תָּנֵינָן, בְּכֹלָּא בָּעֵי בַּר נָשׁ לְאַחֲזָאָה עוֹבָדָא כְּגַוְונָא דִּלְעֵילָּא, וּלְמֶעְבַּד עוֹבָדָא כְּמָה דְּאִצְטְרִיךְ. וְאִי אִשְׁתָּנֵּי בְּמִלָּה אָחֳרָא, הוּא אַנְגִּיד עָלֵיהּ לְשַׁרְיָא בֵּיהּ מִלָּה אָחֳרָא דְּלָא אִצְטְרִיךְ.</p>\n<p>וְתָא חֲזֵי, בְּשַׁעֲתָא דְּבַר נָשׁ אַחְזֵי עוֹבָדָא לְתַתָּא בְּאֹרַח מֵישָׁר, כְּמָה דְּאִצְטְרִיךְ, נָגִיד וְנָפִיק וְשַׁרְיָא עֲלוֹי רוּחַ קַדִישָׁא עִלָּאָה. וּבְשַׁעֲתָא דְּאִיהוּ אַחְזֵי עוֹבָדָא לְתַתָּא בְּאוֹרְחָא עֲקִימָא, דְּלֵית אִיהוּ אוֹרַח מֵישָׁר, כְּדֵין נָגִיד וְנָפִיק וְשָׁרֵי עֲלוֹי רוּחַ אָחֳרָא, דְּלָא אִצְטְרִיךְ, דְּסָטֵי לֵיהּ לְבַּר נָשׁ לִסְטַר בִּישׁ. מַאן מָשִׁיךְ עָלֵיהּ הַהוּא רוּחָא. הֲוִי אוֹמֵר, הַהוּא עוֹבָדָא דְּאַחְזֵי בִּסְטָר אָחֳרָא.</p>\n<p>כְּתִיב (משלי ל״א:י״ג) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. דָּרְשָׁה, מַהוּ דָּרְשָׁה. דְּבַעְיָא וְדָרִישׁ עַל צֶמֶר וּפִשְׁתִּים, מַאן דִּמְחַבֵּר לוֹן כַּחֲדָא, וְאִי תֵּימָא בְּצִיצִית אֲמַאי שָׁרֵי. הָא אוּקְמוּהָ. אֲבָל הָתָם הוּא הַהוּא לְבוּשָׁא בְּתִקּוּנוֹי, בְּאַשְׁלְמוּת עוֹבָדָא כַּדְקָא חֲזֵי.</p>\n<p>(נ\"א ודא) תּוּ, דָּרְשָׁה צֶמֶר וּפִשְׁתִּים, לְמֶעְבַּד נוּקְמָא בְּמַאן דִּמְחַבֵּר לוֹן כַּחֲדָא. אֲבָל אֵימָתַי שַׁרְיָא. בְּשַׁעֲתָא דְּאִיהוּ בְּאַשְׁלְמוּתָא, דִּכְתִיב, וַתַּעַשׂ בְּחֵפֶץ כַּפֶיהָ. וְצִיצִית, הָא אוֹקִימְנָא דְּהָתָם בְּהַהוּא כְּלָלָא דִּשְׁלֵימוּתָא אִשְׁתְּכַח, וְלָא עָבִיד מִדִּי. אֲבָל בְּשַׁעֲתָא דְּלָא אִשְׁתְּכַח בִּשְׁלֵימוּתָא, מַאן דְּאָתֵי לְחַבְּרָא לוֹן כַּחֲדָא, אִתְעַר עָלֵיהּ רוּחָא דְּלָא אִצְטְרִיךְ.</p>\n<p>מִלָּה דָּא מַאן אוֹכַח. קַיִן וְהֶבֶל אוֹכְחָן. דְּדָא אָתֵי מִסִּטְרָא חַד, וְדָא אָתֵי מִסִּטְרָא אָחֳרָא. וּבְגִין כָּךְ לָא לִבְעֵי לָן לְחַבְּרָא לוֹן כַּחֲדָא. (ס\"א ל\"ג מלה דא מאן אוכח. קין והבל אוכחן) וְקָרְבְּנָא דְּקַיִן, אִתְרְחַק מִקַּמֵּי קָרְבְּנָא דְּהֶבֶל.</p>\n<p>וְעַל דָּא וּבֶגֶד כִּלְאַיִם שַׁעֲטְנֵז לֹא יַעֲלֶה עָלֶיךָ. לֹא יַעֲלֶה עָלֶיךָ סְתָם, לֹא יַעֲלֶה עָלֶיךָ רוּחָא אָחֳרָא לְשַׁלְּטָאָה בָּךְ. וְאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְאַחֲזָאָה עוֹבָדָא דְּכַשְׁרָא כְּמָה דְּיָאוּת, וּבְהַהוּא עוֹבָדָא שַׁרְיָא עָלֵיהּ רוּחַ קַדִישָׁא, רוּחַ עִלָּאָה, לְאִתְקַדְּשָׁא בֵּיהּ, אָתָא לְאִתְקַדְּשָׁא מְקַדְּשִׁין לֵיהּ, דִּכְתִיב וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי קָדוֹשׁ אֲנִי יְיָ'.</p>\n<p>כְּתִיב וּמֵעֵץ הַדַּעַת טוֹב וָרָע, וּמַה עַל דָּא גָּרִים אָדָם מִיתָה בְּעָלְמָא, מַאן דְּאַחְזֵי עוֹבָדָא אָחֳרָא דְּלָא אִצְטְרִיךְ, עַל אַחַת כַּמָה וְכַמָּה. שׁוֹר וַחֲמוֹר אוֹכָחָן. מִסִּטְרָא דָּא אִקְרֵי שׁוֹר, וּמִסִּטְרָא דָּא אִקְרֵי חֲמוֹר, וְעַל דָּא כְּתִיב (דברים כ״ב:י׳-י״א) לֹא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּו. לָא תַּעֲבִיד עִרְבּוּבְיָיא כַּחֲדָא, בְּגִין דְּאִתְעַר לְאִתְחַבְּרָא סִטְרָא אָחֳרָא כַּחֲדָא, לְאַבְאָשָׁא עָלְמָא. וּמַאן דְּפָרִישׁ לוֹן, אַסְגֵּי שְׁלָמָא בְּעָלְמָא. אוּף הָכָא, מַאן דְּפָרִישׁ לוֹן בְּהַהוּא גַּוְונָא כְּמָה דְּאָמְרוּ, דְּלָא אִשְׁתְּכַח שׁוּעַ <Nonei></i>טָווּי וְנוּז כַּחֲדָא, הַאי בַּר נָשׁ אַסְגֵּי שְׁלָמָא עָלֵיהּ, וְעַל כָּל עָלְמָא.</p>\n<p>קָרְבְּנָא דְּקַיִן הֲוָה פִּשְׁתִּים, וְקָרְבְּנָא דְּהֶבֶל הֲוָה צֶמֶר, לָאו דָּא כְּדָּא, וְלָאו דָּא כְּדָּא. רָזָא דְּמִלָּה, קַיִן כִּלְאַיִם הֲוָה, עִרְבּוּבְיָא דְּלָא אִצְטְרִיךְ, סִטְרָא אָחֳרָא, דְּלָא זִינָא דְּחַוָּה וְאָדָם. וְקוּרְבָּנֵיהּ מֵהַהוּא סִטְרָא קָא אַתְיָא. הֶבֶל מִזִינָא חֲדָא דְּאָדָם וְחַוָּה. וּבְמֵעָהָא דְּחַוָּה אִתְחַבָּרוּ אִלֵּין תְּרֵין סִטְרִין. וּבְגִין דְּאִתְחַבָּרוּ כַּחֲדָא, לָא אַתְיָא מִנַּיְיהוּ תּוֹעַלְתָּא לְעָלְמָא, ואִתְאֲבִידוּ.</p>\n<p>וְעַד יוֹמָא דֵּין, סִטְרָא דִּלְהוֹן קַיְּימָא. וּמַאן דְּאַחְזֵי גַּרְמֵיהּ בְּעוֹבָדָא דְּחִבּוּרָא דָּא, אִתְּעַר עָלֵיהּ אִינּוּן סִטְרִין כַּחֲדָא, וְיָכִיל לְאִתְזְקָא, וְשָׁארִי עֲלוֹי רוּחָא אָחֳרָא, דְּלָא אִצְטְרִיךְ. וְיִשְׂרָאֵל בָּעָאן לְאִתְּעָרָא עָלַיְיהוּ רוּחָא קַדִּישָׁא לְמֶהֱוִי קַדִּישִׁין, לְאִשְׁתַּכְּחָא בִּשְׁלָמָא, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>כְּתִיב (ויקרא ו׳:ג׳) וְלָבַשׁ הַכֹּהֵן מִדוֹ בַד וּמִכְנְסֵי בַּד יִהְיוּ עַל בְּשָׂרוֹ (ובאבנט בד יחגור) אֲמַאי אִקְרֵי בַּד, יְחִידָאי. בְּגִין דְּלָא בָּעֵי לְחַבְּרָא לְהַאי פִּשְׁתִּים בְּאָחֳרָא, וְעַל דָּא לָא כְּתִיב מִדוֹ פִשְׁתִּים, אֶלָּא בַד יְחִידָאָה.</p>\n<p>וְכַהֲנָא אֲמַאי אִיהוּ בָּעֵי לְאִתְחֲזָאָה בְּהַאי. אֶלָּא אִלֵּין מָאנֵי בַּד, בָּעֵי לְאִתְחֲזָאָה בְּהוּ עַל מִזְבַּח הָעוֹלָה, כַּד הֲוָה מַפְנֵי קִטְרָא (ס\"א קטמא) דְּדִשְׁנָא דְּעוֹלָה, דְּהָא עוֹלָה מִסִּטְרָא דְּעֲבוֹדָה זָרָה וְהִרְהוּרָא בִּישָׁא קָא אַתְיָא. וּבְגִין כָּךְ, בָּעֵי לְאִתְחֲזָאָה בְּהוּ בִּלְחוֹדַיְיהוּ, וְלָא בְּעִרְבּוּבְיָא כְּמָה דְּאַמָרָן, בְּגִין דְּיִתְכַּפָּר לֵיהּ לְבַּר נָשׁ כָּל אִינּוּן חוֹבִין דְּאַתְיָין מֵהַהוּא סִטְרָא.</p>\n<p>וְכַד עָיֵיל לְמַקְדְּשָׁא, אֲתַר דִּשְׁלִימוּ אִשְׁתְּכַח, וְכָל אִינּוּן פּוּלְחָנֵי דִּשְׁלֵימוּתָא, אַף עַל גַּב דְּאִתְחַבָּרוּ, לֵית לָן בָּהּ, כְּמָה דְּאַמָרָן בְּצִיצִית, בְּגִין דְּתַמָּן אִשְׁתְּכָחוּ וְאִתְחֲבְּרוּ כָּל אִינּוּן זַיְּינִין דִּלְעֵילָּא, וְכָל אִינּוּן מָאנֵי מַקְדְּשָׁא, מִשְׁתַּכְּחִין בֵּיהּ כַּמָה זַיְּינִין מְשַׁנְּיָין דָּא מִן דָּא, וְכֻלְּהוּ אִתְכְּלִילוּ תַּמָּן כְּגַוְונָא דִּלְעֵילָּא. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לְהוּ אוֹרַיְיתָא דִּקְשׁוֹט, אוֹרַיְיתָא דִּמְהֵימְנוּתָא, וְרִיחַם לְהוּ מִכָּל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דִּכְתִּיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ'.</p>"],[9520012196,"<p>פָּתַח רִבִּי חִיָּיא אֲבַתְרֵיהּ וְאָמַר, כִי תָּבֹאוּ אֶל הָאָרֶץ וּנְטַעְתֶּם כָּל עֵץ מַאֲכָל וְגוֹ'. וּבַשָּׁנָה הָרְבִיעִית יִהְיֶה כָּל פִּרְיוֹ קֹדֶשׁ הִלּוּלִים לַיְיָ'. כִי תָּבֹאוּ אֶל הָאָרֶץ, הָא אוּקְמוּהָ חַבְרַיָּיא, אֲבָל תָּא חֲזֵי, דְּהָא אִילָנָא לָא עָבִיד פֵּירִין, אֶלָּא בְּאַרְעָא. וְאַרְעָא אַפִּיק לְהוֹן, וְאַחְזֵי הַהוּא אִיבָּא לְעָלְמָא. וְאַרְעָא לָא עַבְדָּא פֵּירִין אֶלָּא מִגּוֹ חֵילָא אָחֳרָא דְּעָלָהּ. כְּמָה דְּנוּקְבָּא לָא עַבְדָּא פֵּירִין, אֶלָּא מִגּוֹ חֵילָא דִּדְכוּרָא.</p>\n<p>וְהַהוּא אִיבָּא, לָא אִשְׁתְּלִים בְּאַשְׁלְמוּתָא, עַד תְּלַת שְׁנִין. וְחֵילָא לָא אִתְפָּקְדָא עָלֵיהּ לְעֵילָּא עַד דְּאִשְׁתְּלִים. בָּתַר דְּאִשְׁתְּלִים אִתְפָּקְדָא עָלֵיהּ חֵילָא וְאַרְעָא אִתְתְּקָנַת בֵּיהּ. דְּהָא עַד תְּלַת שְׁנִין אַרְעָא לָא אִתְתְּקָנַת בֵּיהּ וְלָא (אשתכחת) אִשְׁתְּלִימַת (ס\"א אתבסמת) (נ\"א אסתכמת) עִמֵּיהּ. בָּתַר דְּאִשְׁתְּלִים וְאִתְתְּקָנוּ כַּחֲדָא כְּדֵין הוּא שְׁלֵימוּתָא.</p>\n<p>תָּא חֲזֵי, נוּקְבָּא, עַד תְּלָת זִמְנִין דְּאִתְעַבְּרָא, אִיבָּא דִּמְעָהָא לָא אִשְׁתְּלִים. בָּתַר ג' עִידוּאָן, נוּקְבָּא אִתְתְּקָנַת בְּהַהוּא אִיבָּא, וְאִסְתְּכָּמוּ כַּחֲדָא. כְּדֵין הַהוּא אִיבָּא שְׁלִימוּ דְּכֹלָּא, וּשְׁפִּירוּ דְּכֹלָּא. בָּתַר דְּנָפַק, עַד ג' שְׁנִין לָא אִית לֵיהּ חֵילָא לְעֵילָּא, דְּהָא כְּדֵין אִשְׁתְּלִים בִּשׁוּלָא דִּילֵיהּ. לֵוִי אִתְרְעֵי מִכֹּלָּא, תְּלִיתָאָה לְאִמֵיהּ, דְּאִתְתָּקָּנַת בֵּיהּ, וְאִסְתַכְּמַת ס\"א (ואתבסמת) בַּהֲדֵיהּ.</p>\n<p>בָּתַר ג' שְׁנִין, אִתְפְּקָּדַת עָלֵיהּ (ס\"א אתפקד עלה) חֵילָא עִלָּאָה לְעֵילָּא. וּבַשָּׁנָה הָרְבִיעִית, יִהְיֶה כָּל פִּרְיוֹ קֹדֶשׁ הִלּוּלִים. מַאי קֹדֶשׁ הִלּוּלִים. תּוּשְׁבְּחָן, לְשַׁבְּחָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא. עַד הָכָא. מִכָּאן וְאֵילָךְ רָזָא דְּמִלָּה, דְּבַשָּׁנָה <Nonei></i>הָרְבִיעִית מִזְדְּוָּוגַת כְּנֶסֶת יִשְׂרָאֵל לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהִלּוּלָא חַד אִשְׁתְּכַח. דִּכְתִּיב קֹדֶשׁ הִלּוּלִים, הִלוּלָא וְחֶדְוָה בְּזִמְנָא (ס\"א בזווגא) חֲדָא.</p>\n<p>מַאי שָׁנָה (הרביעית) דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְתָנֵינָן, שָׁנָה הָרְבִיעִית, דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי קַיְּימָא רְבִיעָאָה לְכוּרְסְיָיא, וְכֹלָּא חַד, דְּהָא כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא מִזְדַּוַּוג בָּהּ בִּכְּנֶסֶת יִשְׂרָאֵל, וּכְדֵין הִיא קֹדֶשׁ, וְהִלּוּלָא קַדִּישָׁא אִשְׁתְּכַח, (וקודשא בריך הוא אזדווג בהדה) וּכְדֵין חַיָּילִין אִתְמָנָן עַל עָלְמָא, עַל כָּל מִלָּה וּמִלָּה כַּדְקָא חֲזֵי לֵיהּ מִכָּאן וּלְהָלְאָה מִתְבָּרְכָאן כֻּלְּהוּ, וְשָׁארִי לְמֵיכַל, דְּהָא כֻּלְּהוּ בִּשְׁלֵימוּתָא דְּכֹלָּא, בִּשְׁלֵימוּתָא דְּעֵילָּא וְתַתָּא.</p>\n<p>וְעַד לָא אִשְׁתְּלִים בְּכֹלָּא מִתַּתָּא וּמֵעֵילָּא, אָסִיר לְמֵיכַל מִנֵּיהּ. וּמַאן דְּאָכִיל מִנֵּיהּ, כְּמַאן דְּלֵית לֵיהּ חוּלָקָא בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִּכְּנֶסֶת יִשְׂרָאֵל, דְּהָא הַהוּא אִיבָּא בְּלָא רְשׁוּתָא עִלָּאָה קַדִּישָׁא קַיְּימָא, דְּלָא שָׁארֵי עָלֵיהּ עַד דְּיִשְׁתְּלִים. וּבְלָא רְשׁוּתָא. תַּתָּאָה, דְּהָא לָא אִסְתַכְּמַת (ס\"א אתבסמת) חֵילָא דְּאַרְעָא בֵּיהּ. וְהַהוּא דְּאָכִיל מִנֵּיהּ, אַחְזֵי גַּרְמֵיהּ דְּלֵית לֵיהּ חוּלָקָא לְעֵילָּא וְתַתָּא, וְאִי בָּרִיךְ עָלֵיהּ, בְּרָכָה לְבַטָּלָה הוּא. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא עַד כָּען לָא שַׁרְיָא עֲלוֹי, וְלֵית בֵּיהּ חוּלָקָא. רַחֲמָנָא לִישֵׁזְבִינָן מֵאִינּוּן דְּלָא מַשְׁגִּיחִין לִיקָרָא דְּמָארֵיהוֹן.</p>\n<p>זַכָּאִין אִינּוּן צַדִּיקַיָּיא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נוֹגַהּ. בְּגִין דִּבְהַהוּא זִמְנָא, יִסְתָּלַק חִוְיָא דְּשַׁרְיָא בְּנוּקְבָּא בְּקַדְמִיתָא, וְיֵיתֵי דְּכוּרָא לְמִשְׁרֵי בְּאַתְרֵיהּ כַּד בְּקַדְמִיתָא, וְכֹלָּא יְהֵא שְׁלִים. תָּאנָא בְּזִמְנָא דְּזַכָּאָה שָׁארֵי בְּעָלְמָא וְכוּ' עַד צַדִּיק כַּתָּמָר יִפְרָח. (אמר המגיה המאמר הזה ימצאהו המעיין בפרשת ויקרא דף י\"ד ע\"ב שורה כ\"ד ומשלים דף י\"ו ע\"א שורה כ\"ב)</p>"],[9520012197,"<p>רִבִּי יוֹסֵי פָּתַח קְרָא וְאָמַר, (ויקרא י״ט:כ״ו) לֹא תֹאכְלוּ עַל הַדָּם. הָא בְּכַמָּה אֲתַר אוּקְמוּהָ חַבְרַיָּיא, וְכָל הָנֵי קְרָאֵי אֲבַתְרֵיהּ. וְכָל חַד וְחַד בְּאִתְגַּלְיָיא. אֲבָל הַאי קְרָא אִית לְאִתְעָרָא בֵּיהּ, דִּכְתִיב מִפְּנֵי שֵׂיבָה תָּקוּם וְגוֹ'. מִפְּנֵי שֵׂיבָה, שֵׂיבָה דְּאוֹרַיְיתָא סְתָם. תָּקוּם, מִכָּאן דְּבָעֵי בַּר נָשׁ לְמֵיקָם בְּקִיּוּמָא (מכאן דבעי בר נש למיקם) מִקָּמֵי סֵפֶר תּוֹרָה, וְהָכִי רַב הַמְנוּנָא (ס\"א ייסא) סָבָא, כַּד הֲוָה חָמֵי סֵפֶר תּוֹרָה, הֲוָא קָם מִקַּמֵּיהּ, וְאָמַר מִפְּנֵי שֵׂיבָה תָּקוּם. (כד הוה חמי חומש דאורייתא הוא קם מקמיה) (ס\"א עביד ליה הדורא) (והוי אמר והדרת פני זקן) כְּגַוְונָא דָּא, בָּעֵי בַּר נָשׁ לְמֵיקָם בְּקִיּוּמֵיהּ לְקַמֵּיהּ דְתַּלְמִיד חָכָם, בְּגִין דְּאִיהוּ קָאִים בְּקִיּוּמָא (נ\"א בדיוקנא) קַדִּישָׁא עִלָּאָה. וְרָמַז לְכַהֲנָא עִלָּאָה (ס\"א והכא רמיז לעתיקא) קַדִּישָׁא עִלָּאָה, דִּכְתִיב וְהָדַרְתָּ פְּנֵי זָקֵן, דְּאִיהוּ בְּעָלְמָא. אָמַר רַבִּי שִׁמְעוֹן, מִכָּאן רֶמֶז לְתוֹרָה שֶׁבִּכְתָב וְרֶמֶז לְתוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>וְתוּ תָּנֵינָן, הַאי קְרָא לִדְרָשָׁא הוּא דְּאָתָא, מִפְּנֵי שֵׂיבָה תָּקוּם, כְּמָה דְּאִתְעֲרוּ בֵּיהּ חַבְרַיָּיא, מִפְּנֵי שֵׂיבָה תָּקוּם, אַזְהַר לֵיהּ לְבַר נָשׁ, עַד לָא יִסְתָּלַק בְּסִיבוּתָא, דִּיְקוּם בְּקִיּוּמָא טָבָא בְּעָלְמָא, בְּגִין דְּדֵין הוּא הִדּוּרָא לֵיהּ, אֲבָל לְסוֹף יוֹמוֹי לֵית שְׁבָחָא לֵיהּ לְבַּר נָשׁ כָּל כַּךְ, כַּד אִיהוּ סִיב וְלָא יָכִיל לְמֶהֱוִי בִּישׁ. אֶלָּא שְׁבָחָא דִּילֵיהּ, כַּד אִיהוּ בְּתוּקְפֵיהּ, וְאִיהוּ טַב. וּשְׁלֹמֹה מַלְכָּא צָוַוח וְאָמַר, (משלי כ׳:י״א) גַּם בְּמַעֲלָלָיו יִתְנַכֶּר נָעַר וְגוֹ'. כְּגַוְונָא דָּא כְּתִיב, (קהלת י״ב:א׳) וּזְכוֹר אֶת בּוֹרְאֶךָ בִּימֵי בְּחוּרוֹתֶיךָ. אָמַר רִבִּי אֶלְעָזָר, וַדַּאי (הכי הוא) אוֹרְחָא דָּא מְתֻקָּנָא קָמָן, וְהַאי אוֹרְחָא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9520012198,"<p>פָּתַח וְאָמַר, (תהילים א׳:ו׳) כִּי יוֹדֵעַ יְיָ' דֶּרֶךְ צַדִּיקִים וְדֶרֶךְ רְשָׁעִים תֹּאבֵד. מַאי כִּי יוֹדֵעַ יְיָ'. אֶלָּא, קוּדְשָׁא בְּרִיךְ הוּא יוֹדֵעַ וְאַשְׁגַּח בְּאָרְחָא דְּצַדִּיקַיָּיא, לְאוֹטָבָא לְהוּ, וּלְאַגָּנָא לְהוּ, וְהוּא אָזִיל קַמַּיְיהוּ לְנַטְרָא לְהוּ. וּבְגִין כָּךְ, מַאן דְּנָפִיק לְאָרְחָא בָּעֵי דְּלִהֱוִי הַהִיא אָרְחָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְיִשְׁתַּתַּף לֵיהּ בַּהֲדַיְיהוּ. וּבְגִין כָּךְ כְּתִיב, כִּי יוֹדֵעַ יְיָ' דֶּרֶךְ צַדִּיקִים וְדֶרֶךְ רְשָׁעִים תֹּאבֵד. הִיא מִגַּרְמָהּ, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא לָא <Nonei></i>אִשְׁתְּמוֹדַע לֵיהּ לְהַהוּא אָרְחָא דִּלְהוֹן, וְלָא אָזִיל בַּהֲדַיְיהוּ.</p>\n<p>כְּתִיב דֶּרֶךְ, וּכְתִיב אֹרַח, מַה בֵּין הַאי לְהַאי. אֶלָּא, דֶּרֶךְ: דִשְׁאָר קַרְסוּלֵי בְּנֵי נָשָׁא אָזְלוּ בָּהּ. אֹרַח: דְּאִיהוּ אִתְפְּתַח מִן זִמְנָא זְעֵירָא (דא ארח כמה דאת אמר (איוב ל״ד:ח׳) וארח לחברה עם פעלי און) וְעַל אָרְחָא דָּא כְּתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. אָמֵן כֵּן יְהִי רָצוֹן. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9520012199,"<p>(ויקרא כ״א:א׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה אֱמוֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן וְאָמַרְתָּ אֲלֵיהֶם לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו. אָמַר רִבִּי יוֹסֵי, מַאי טַעְמָא דָּא לָקֳבֵל דָּא, דִּכְתִּיב לְעֵילָּא, וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בָהֶם אוֹב אוֹ יִדְּעוֹנִי מוֹת יוּמָתוּ, וְסָמִיךְ לֵיהּ אֱמוֹר אֶל הַכֹּהֲנִים. אֶלָּא (משמע) כֵּיוָן דְּאַזְהַר לְהוּ לְיִשְׂרָאֵל, לְקַדְּשָׁא לְהוּ בְּכֹלָּא, אַזְהַר לְהוּ לְכַהֲנֵי לְקַדְּשָׁא לוֹן, וְכֵן לַלְוִיִּם. לְכַהֲנֵי מִנַּיִן. דִּכְתִּיב אֱמוֹר אֶל הַכֹּהֲנִים. לְלֵוָאֵי מִנַּיִן. דִּכְתִּיב, (במדבר י״ח:כ״ו) וְאֶל הַלְוִיִּם תְּדַבֵּר וְאָמַרְתָּ אֲלֵיהֶם. בְּגִין דְּיִשְׁתַּכְּחוּן כֻּלְּהוּ זַכָּאִין קַדִּישִׁין דַּכְיָין.</p>\n<p>אֱמוֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן, מַאי טַעְמָא הָכָא בְּנֵי אַהֲרֹן, וְכִי לָא יְדַעְנָא דִּבְנֵי אַהֲרֹן נִינְהוּ. אֶלָּא בְּנֵי אַהֲרֹן, וְלָא בְּנֵי לֵוִי, דְּאַהֲרֹן דְּהוּא שֵׁירוּתָא דְּכָל כַּהֲנֵי דְּעָלְמָא, דְּבֵיהּ אִתְרְעֵי קוּדְשָׁא בְּרִיךְ הוּא מִכֹּלָּא, בְּגִין לְמֶעְבַּד שְׁלָמָא בְּעָלְמָא, וּבְגִין דְּאַהֲרֹן אָרְחוֹי סַלִיקוּ לֵיהּ לְהַאי, דְּכָל יוֹמוֹי דְּאַהֲרֹן הֲוָה מִשְׁתָּדַּל לְאַסְגָּאָה שְׁלָמָא בְּעָלְמָא. וּבְגִין דְּאוֹרְחוֹי כַּךְ, סָלִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְהַאי, לְמֵיעַל שְׁלָמָא בְּפָמַלְיָא דִּלְעֵילָּא, וּבְגִין כַּךְ אֱמוֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן.</p>\n<p>אֱמוֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן וְאָמַרְתָּ אֲלֵיהֶם. רִבִּי יְהוּדָה פָּתַח, (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךָ וְגוֹ'. מַה רַב טוּבְךָ, כַּמָה עִלָּאָה וְיַקִּירָא, הַהוּא נְהוֹרָא עִלָּאָה דְּאִקְרֵי טוֹב, דִּכְתִּיב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְדָא הוּא אוֹר הַגָנוּז, דְּבֵיהּ עָבִיד קוּדְשָׁא בְּרִיךְ הוּא טַב בְּעָלְמָא, וְלָא מָנַע לֵיהּ בְּכָל יוֹמָא, בְּגִין דְּבֵיהּ מִתְקַיֵּים עָלְמָא, וְקָאִים עָלֵיהּ. אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ, דִּתְנָן, נְהוֹרָא עִלָּאָה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, וְגָנִיז לֵיהּ לְצַדִּיקַיָּא לְזִמְנָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ.</p>\n<p>פָּעַלְתָּ לַחוֹסִים בָּךְ. פָּעַלְתָּ, בְּזִמְנָא דְּאִתְבְּרֵי עָלְמָא, הַהוּא נְהוֹרָא הֲוָה קָאִים וְנָהִיר מֵרֵישָׁא דְּעָלְמָא לְסַיְיפֵי דְּעָלְמָא. כַּד אִסְתָּכַּל קוּדְשָׁא בְּרִיךְ הוּא, לְאִינּוּן חַיָּיבִין דִּזְמִינִין לְקַיְּימָא בְּעָלְמָא, גָּנִיז לֵיהּ לְהַהוּא נְהוֹרָא, דִּכְתִּיב (איוב ל״ח:ט״ו) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם. וְזַמִּין לְאַנְהָרָא לְצַדִּיקַיָּיא לְעָלְמָא דְּאָתֵי, וְדָא הוּא אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךָ, וּכְתִיב (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>"],[9520012200,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַר נָשׁ קָאִים לְמֵיהַךְ לְהַהוּא עָלְמָא, וְהוּא בְּבֵי מַרְעֵיהּ, אַתְיָין עָלֵיהּ ג' שְׁלוּחִין, וְחָמֵי תַּמָּן, מַה דְּלָא יָכִיל בַּר נָשׁ לְמֵחֱמֵי כַּד אִיהוּ בְּהַאי עָלְמָא. וְהַהוּא יוֹמָא, יוֹמָא דְּדִינָא עִלָּאָה הוּא, דְּמַלְכָּא בָּעֵי פִּקְדוֹנָא דִּילֵיהּ. זַכָּאָה הַהוּא בַּר נָשׁ, דְּפִקְדוֹנֵיהּ אָתִיב לְמַלְכָּא כְּמָה דְּאִתְיְיהִיב לֵיהּ בְּגַוִיהּ. אִי הַהוּא פִּקְדוֹנָא אִתְטְנָּף בְּטִנּוּפֵי גּוּפָא, מַה יֵימָּא לְמָארֵי פִּקְדוֹנָא.</p>\n<p>זָקַף עֵינוֹי, וְחָמֵי לְמַלְאַךְ הַמָּוְת קָאִים קַמֵּיהּ, וְסַיְיפֵיהּ שְׁלִיפָא בִּידֵיהּ, קַסְטַּר בְּקַטְרִין, בְּקוּטְמָא דְּהַהוּא בַּר נָשׁ. וְלֵית לָהּ לְנַפְשָׁא קַשְׁיוּ בְּכֹלָּא, כִּפְרִישׁוּ דִּילָהּ מִן גּוּפָא. וּבַר נָשׁ לָא מִית, עַד דְּחָמֵי לִשְׁכִינְתָּא, וּמִגּוֹ סְגִיאוּת תִּיאוּבְתָּא דִּשְׁכִינְתָּא, נַפְשָׁא נַפְקַת <Nonei></i>לְקַבְּלָא לִשְׁכִינְתָּא. בָּתַר דְּנָפְקָא, מַאן אִיהִי נַפְשָׁא דְּאִתְדַּבָּק בָּהּ (ס\"א ותתקבל) וִיקַבְּל בְּגוּפָא (ס\"א בגווה) וְהָא אוּקְמוּהָ לְהָנֵי מִלֵי.</p>\n<p>בָּתַר דְּנָפְקָא נַפְשָׁא מִן גּוּפָא, וְאִשְׁתְּאַר גּוּפָא בְּלָא רוּחָא, אָסִיר לְמִשְׁבַּק לֵיהּ בְּלָא קְבוּרָתָא, דִּכְתִּיב, (דברים כ״א:כ״ג) לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ כִּי קָבֹר תִּקְבְּרֶנוּ בַּיּוֹם הַהוּא. בְּגִין דְּמֵיתָא דְּיִשְׁתָּהֵי כ\"ד שָׁעוֹת, דְּאִינּוּן יוֹמָם וָלַיְלָה, בְּלָא קְבוּרָתָא, יָהִיב חַלִישׁוּתָא בְּשַׁיְיפוֹי דִּרְתִיכָא, וּמְעַכֵּב עַבִידְתָּא דְקוּדְשָׁא בְּרִיךְ הוּא מִלְּמֶעְבַד דְּאֶפְשָׁר דְּקוּדְשָׁא בְּרִיךְ הוּא גָּזַר עָלֵיהּ, בְּגִין לְמֵיתֵיהּ בְּגִלְגּוּלָא אָחֳרָא, מִיַּד בְּהַהוּא יוֹמָא דְּאִתְפְּטָר, לְאוֹטָבָא לֵיהּ. וְכָל זִמְנָא דְּלָא אִתְקְבַר גּוּפָא, נִשְׁמְתָא לָאו עָאלַת קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְלָא יַכְלָא לְמֶהֱוִי בְּגוּפָא אָחֳרָא, בְּגִלְגּוּלָא תִּנְיָינָא, דְּלָא יָהֲבִין לְנִשְׁמְתָא גּוּפָא אָחֳרָא, עַד דְּיִתְקְבָר קַדְמָאָה. וְדָא דָּמֵי לְבַר נָשׁ דְּמֵיתַת אִתְּתֵיהּ, לָא אִתְחֲזֵי לֵיהּ, לְמֵיסַב אִתְּתָא אָחֳרָא, עַד דְּקָבִיר לְּקַדְמֵיתָא, וּבְגִין דָּא אָמְרָה אוֹרַיְיתָא, לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ.</p>\n<p>דָּבָר אַחֵר, כַּד אִתְפָּרְשָׁא נִשְׁמְתָא מִן גּוּפָא, וּבַעְיָא לְמֵיזָל לְהַהוּא עָלְמָא, לָא תֵּיעוּל לְהַהוּא עָלְמָא, עַד דְּיָהֲבִין לָהּ גּוּפָא אָחֳרָא מִנְּהוֹרָא, וּלְבָתַר יַכְלָא לְמֵיעַל. וּמֵאֵלִיָּהוּ תִּנְדַּע, דַּהֲווֹ לֵיהּ תְּרֵין גּוּפִין, חַד דְּבֵיהּ אִתְחֲזֵי לְתַתָּא לִבְנֵי נָשָׁא, וְחַד דְּבֵיהּ אִתְחֲזֵי לְעֵילָּא, בֵּין מַלְאֲכִין עִלָּאִין קַדִישִׁין. וְכָל כַּמָּה דְּגוּפָא לָא אִתְקְבַר, צַעֲרָא הוּא לְנִשְׁמְתָא, וְרוּחַ מִסְאֲבָא אִזְדְּמַן לְשַׁרְיָיא עֲלוֹי, וּלְסַאָבָא לְהַהוּא גּוּפָא.</p>\n<p>וּבְגִין דְּהַהוּא רוּחַ מִסְאֲבָא, אִזְדְּמַן, לָא לִבְעֵי לֵיהּ לְאִינִישׁ, לְמֵיבַת הַהוּא גּוּפָא לֵילְיָא חַד, בְּגִין דְּרוּחַ מִסְאֲבָא אִשְׁתְּכַח בְּלֵילְיָא, וְאִשְׁתְּטַח בְּכָל אַרְעָא, לְאַשְׁכְּחָא גּוּפָא בְּלָא נַפְשָׁא, לְסָאֲבָא לֵיהּ, וְאִסְתְּאַב יַתִּיר, וְעַל דָּא אַזְהַר לְכַהֲנֵי וְאָמַר, לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו, בְּגִין דְּאִינּוּן קַדִּישִׁין לָא יִשְׁרֵי עָלַיְיהוּ רוּחַ מִסְאֲבָא, וְלָא יִסְתַּאֲבוּן.</p>"],[9520012201,"<p>(ויקרא כ\"א) אֱמוֹר אֶל הַכֹּהֲנִים, רִבִּי יִצְחָק אָמַר, אֱמוֹר אֶל הַכֹּהֲנִים, בִּלְחִישׁוּ. כְּמָה דְּכָל עוֹבָדֵיהוֹן דְּכַהֲנֵי בִּלְחִישׁוּ, כַּךְ אֲמִירָה דִּלְהוֹן בִּלְחִישׁוּ. אֱמוֹר וְאָמַרְתָּ: זִמְנָא חַד, וּתְרֵין זִמְנִין, לְאַזְהָרָא לְהוּ עַל קְדוּשַׁיְיהוּ, בְּגִין דְּלָא יִסְתַּאֲבוּן. דְּמַאן דִּמְשַׁמֵּשׁ בַּאֲתַר קַדִּישָׁא, בַּעְיָא דְּיִשְׁתְּכַח קַדִּישָׁא בְּכֹלָּא. לְנֶפֶשׁ לֹא יִטַּמָּא, כְּמָה דְּאוֹקִימְנָא, דְּגוּפָא בְּלָא רוּחַ, מִסְאֲבָא הוּא, וְשָׁארֵי עָלֵיהּ רוּחַ מִסְאֲבָא. דְּהָא תִּיאוּבְתָּא דְּרוּחֵי מִסְאֲבֵי לְגַבֵּי גּוּפֵיהוֹן דְּיִשְׂרָאֵל אִיהוּ, בְּגִין דְּאִתְּרָק מִנַּיְיהוּ רוּחָא קַדִּישָׁא, וּבְמָנָא דְּקוּדְשָׁא, אַתְיָין לְאִתְחַבְּרָא. וְכַהֲנֵי דְּאִינּוּן קַדִּישִׁין, קְדוּשָּׁתָא עַל קְדוּשָּׁתָא, לָא בַּעְיָין לְאִסְתַּאֲבָא כְּלַל, בְּגִין דִּכְתִּיב, (במדבר ו׳:ז׳) כִּי נֵזֶר אֱלֹהָיו עַל רֹאשׁוֹ. וּכְתִיב כִּי שֶׁמֶן מִשְׁחַת אֱלֹהָיו עָלָיו אֲנִי יְיָ'.</p>\n<p>וְהוּא כְּגַוְונָא דִּלְעֵילָּא קָאִים לְתַתָּא, דִּכְתִּיב, (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן זְקַן אַהֲרֹן שֶׁיוֹרֵד עַל פִּי מִדּוֹתָיו, הַאי קְרָא אוּקְמוּהָ, אֲבָל כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, דָּא מְשַׁח רְבוּת קַדִּישָׁא עִלָּאָה, דְּנָגִיד וְנָפִיק מֵאֲתַר דְּנַהֲרָא עֲמִיקָא דְּכֹלָּא. דָּבָר אַחֵר, דְּנָגִיד וְנָפִיק מֵרֵישָׁא דְּכָל רֵישִׁין, סְתִימָא דְּכָל סְתִימִין. עַל הָרֹאשׁ, עַל הָרֹאשׁ וַדַאי, רֵישָׁא דְּאָדָם קַדְמָאָה.</p>\n<p>יוֹרֵד עַל הַזָּקָן, דָּא דִּיקְנָא יַקִירָא, כְּמָה דְּאוּקְמוּהָ. זְקַן אַהֲרֹן, דָּא כֹּהֵן גָּדוֹל דִּלְעֵילָּא, וְהָא אוּקְמוּהָ. וְהַהוּא שֶׁמֶן, <Nonei></i>יוֹרֵד עַל פִּי מִדוֹתָיו, דְּמֵאִינּוּן מְשִׁיחָן, נָגִיד וְנָפִיק וְנָחִית לְתַתָּאֵי, וּכְגַוְונָא דָּא נָגִיד וְאִתְעַטָּר כַּהֲנָא תַּתָּאָה, בִּמְשַׁח רְבוּת לְתַתָּא.</p>\n<p>הַאי קְרָא, לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. כְּתִיב אֱמוֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן וְאָמַרְתָּ אֲלֵיהֶם לְנֶפֶשׁ לֹא יִטַּמָּא. לָא יִטַּמְּאוּ מִבָּעֵי לֵיהּ, מַהוּ לֹא יִטַּמָּא. אֶלָּא, עַל הַהוּא כֹּהֵן עִלָּאָה מְכֻּלְּהוּ קָאָמַר. אָמַר רִבִּי יְהוּדָה וְהָא כְּתִיב וְהַכֹּהֵן הַגָּדוֹל מֵאֶחָיו. (כאן חסר) אֶלָּא וַדַּאי הָכִי הוּא כְּמָה דְּאִתְּמַר, וְאָמַר רִבִּי יִצְחָק, כַּהֲנָא דְּקָאִים לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, בִּקְדוּשָּׁה אִצְטְרִיךְ לְאִשְׁתַּכְּחָא יַתִּיר מִכֹּלָּא, כְּמָה דְּאִתְּמַר.</p>"],[9520012202,"<p><Nonei></i><Noneb>רעיא מהימנא</b> פִּקוּדָא דָּא, לְסַדְּרָא כַּהֲנָא בְּכָל יוֹמָא בּוּצִּינִין בְּבֵי מַקְדְּשָׁא, וְהָא אוֹקִימְנָא בְּרָזָא דִּמְנוֹרָה. וְאִיהוּ רָזָא כְּגַוְונָא דִּלְעֵילָּא, בְּגִין דִּנְהִירוּ עִלָּאָה בִּמְשַׁח רְבוּ, נָחִית עַל רֵישָׁא דְּכַהֲנָא בְּקַדְמִיתָא לְבָתַר אִיהוּ אַדְלִיק וְאַנְהִיר כָּל בּוּצִּינִין. דִּכְתִּיב כַּשֶּׁמֶן הַטוֹב עַל הָרֹאשׁ וְגוֹ', וּכְתִיב כִּי שֶׁמֶן מִשְׁחַת אֱלֹהָיו עָלָיו וְגוֹ'. וְעַל דָּא אִתְיְיהִיב רְשׁוּ לְכַהֲנָא בִּלְחוֹדוֹי, לְסַדְּרָא בּוּצִּינִין, וּלַאֲדְלָקָא לְהוֹן בְּכָל יוֹמָא תְּרֵין זִמְנִין, לָקֳבֵל נְהִירוּ דְּיִחוּדָא תְּרֵין זִמְנִין, קָרְבְּנָא בְּכָל יוֹמָא, תְּרֵין זִמְנִין, וְכֹלָּא אִצְּטְרִיךְ.</p>\n<p>וְעַל יְדֵי דְּכַהֲנָא נַהֲרִין בּוּצִּינִין בְּכֹלָּא, עֵילָּא וְתַתָּא <Nonei></i>לְמֶחְדּוּ חֵידּוּ, וּלְאַשְׁכְּחָא חֵידּוּ בְּכָל סִטְרִין. בְּאַדְלְקוּתָא דְּבוּצִּינִין, דְּהָא תְּרֵין אִלֵּין עַל יְדֵי דְּכַהֲנָא, לְאִשְׁתַּכְּחָא חֵידוּ בְּכָל סִטְרִין, וְאִלֵּין אִינּוּן אַדְלְקוּתָא דְּבוּצִּינִין וּקְטֹרֶת. וְהָא אוֹקִימְנָא (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, (ע\"כ רעיא מהימנא)</p>"],[9520012203,"<p>(ויקרא כ״א:ג׳) וְלַאֲחוֹתוֹ הַבְּתוּלָה הַקְּרוֹבָה אֵלָיו וְגוֹ'. מַה כְּתִיב לְעֵילָּא, כִּי אִם לִשְׁאֵרוֹ הַקָּרוֹב אֵלָיו וְגוֹ'. רִבִּי אַבָּא פָּתַח, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ', מִי זֶה בָּא מֵאֱדוֹם, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְלַבְשָׁא לְבוּשֵׁי נוּקְמָא עַל אֱדוֹם, דְּאַחֲרִיבוּ בֵּיתֵיהּ, וְאוֹקִידוּ הֵיכָלֵיהּ, וְגָלוּ לִכְנֶסֶת יִשְׂרָאֵל בֵּינֵי עַמְמַיָא. וּלְמֶעְבַד לְהוֹן נִקְמַת עָלְמִין, עַד דְּיִשְׁתַּכְחוּן כָּל טוּרִין מִטוּרֵי עָלְמָא, מַלְיָין מִקָטוּלֵי עַמִּין, וּלְמִקְרֵי לְכָל עוֹפָא דִּשְׁמַיָּא עָלַיְיהוּ, וְכָל חֵיוַות בָּרָא יִתְזְנוּן מִנַּיְיהוּ תְּרֵיסָר יַרְחֵי, וְעוֹפָא דִּשְׁמַיָּא שֶׁבַע שְׁנִין, עַד דְּלָא תִּסְבַּל אַרְעָא נִיוּוּלָא דִּידְהוּ. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ד:ו׳) כִּי זֶבַח לַיְיָ' בְּבָצְרָה וְטֶבַח גָּדוֹל בְּאֶרֶץ אֱדוֹם, עַד דְּאִינּוּן לְבוּשִׁין יִסְתַּאֲבוּן, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ג:ג׳) וְכָל מַלְבּוּשַׁי אֶגְאָלְתִּי.</p>\n<p>חֲמוּץ בְּגָדִים מִבָּצְרָה, בְּגִין דְּמִינָּהּ נָפְקוּ אוּכְלוּסִין דְּעָלְמָא, לְחַיְילָא עַל יְרוּשָׁלַם, וְאִינּוּן שָׁרוּ לְאוֹקְדָא הֵיכָלָא, וּבְנֵי אֱדוֹם מְפַגְרִין שׁוּרִין, וְרָמוּ אַבְנֵי יְסוֹדָא, הֲדָא הוּא דִכְתִיב (תהילים קל״ז:ז׳) זְכוֹר יְיָ' לִבְנֵי אֱדוֹם וְגוֹ', הָאוֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּהּ.</p>\n<p>זֶה הָדוּר בִּלְבוּשׁוֹ, בְּאִינּוּן לְבוּשֵׁי דְּנוּקְמָא דְּזַמִּין לְאַלְבְּשָׁא. צוֹעֶה בְּרוֹב כֹּחוֹ, מַהוּ צוֹעֶה. מְתָבַּר. כְּמָה דִּכְתִּיב, (תהילים מ״ה:ו׳) עַמִּים תַּחְתֶּיךָ יִפְּלוּ וְגוֹ'. אָמְרוּ יִשְׂרָאֵל לִישַׁעְיָה, מַאן הוּא דֵּין דְּיַעֲבֵיד כָּל כַּךְ. פָּתַח וְאָמַר, (ישעיהו ס״ג:א׳) אֲנִי מְדַבֵּר בִּצְדָקָה, הַהוּא דְּאִיהוּ רַב לְהוֹשִׁיעַ, הַהוּא דִּכְתִּיב בֵּיהּ, (תהילים ל״ג:ה׳) אוֹהֵב צְדָקָה וּמִשְׁפָּט. וְאִיהוּ צְדָקָה מַמָּשׁ, וְאִיהוּ רַב לְהוֹשִׁיעַ.</p>\n<p>וְכָּל כַּךְ לָמָּה. בְּגִין דְּגַרְמוּ לִכְּנֶסֶת יִשְׂרָאֵל לְמֶהֱוִי שְׁכִיבַת לְעַפְרָא בְּגָלוּתָא, וּלְמִנְפַּל לְאַרְעָא, כְּמָה דִּכְתִּיב, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. וּבְגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא יִלְבַּשׁ לְבוּשֵׁי נוּקְמָא עָלַיְיהוּ, לְסָאֲבָא לוֹן בִּסְגִיאוּ דְּקָטוּלְיָיא, דִּכְתִיב וְכָל מַלְבּוּשַׁי אֶגְאָלְתִּי.</p>\n<p>וְכָל כַּךְ לָמָּה, דִּכְתִיב וְלַאֲחוֹתוֹ הַבְּתוּלָה הַקְּרוֹבָה אֵלָיו אֲשֶׁר לֹא הָיְתָה לְאִישׁ. דְּלָאו חוּלָקֵיהּ דְּעֵשָׂו, וְלָא הֲוַות בְּעַדְבֵיהּ דְּהַהוּא דִּכְתִּיב בֵּיהּ (בראשית כ״ה:כ״ז) אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה, לָהּ יִטַּמָּא, בְּאִינּוּן לְבוּשִׁין דְּנוּקְמָא, דְּזַמִּין לְאִסְתַּאֲבָא בֵּין אִינּוּן אוּכְלוּסִין, דִּכְתִיב בֵּיהּ לָהּ יִטַּמָּא, בְּגִינָהּ, בְּגִין דְּאִיהִי שְׁכִיבַת לְעַפְרָא, וְהוּא בָּעֵי לְאַקָּמָא לָהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ס׳:א׳) קוּמִי אוֹרִי כִּי בָא אוֹרֵךְ. (ס\"א (עמוס ט׳:י״א) ביום ההוא אקים את סכת דויד הנפלת).</p>"],[9520012204,"<p>(ויקרא כ״א:ה׳) לֹא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם. רִבִּי יוֹסֵי אָמַר, לֹא יִקְרְחֻה בְּהֵ\"א מַאי טַעֲמָא. אֶלָּא, הַהוּא שֶׁמֶן עִלָּאָה, דְּאִיהוּ מְשַׁח רְבוּת קוּדְשָׁא, דְּאַשְׁלִים לְכָל שִׁבְעָה יוֹמִין כְּמָה דְּאִתְּמַר, דִּכְתִּיב, (ויקרא ח׳:ל״ג) כִּי שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם, הַהוּא שֶׁמֶן עִלָּאָה אִתְעָדֵי מִנֵּיהּ וְאִתְקְרַח, אִי אִיהוּ אַפְגִּים רֵישֵׁיהּ. בְּגִין דְּרֵישָׁא דְּכַהֲנָא עִלָּאָה, הַהוּא שֶׁמֶן עִלָּאָה הֲוִי, וְעַל דָּא לָא לִיבְעֵי לֵיהּ לְכַהֲנָא דִּלְתַתָּא, לְאַחֲזָאָה בֵּיהּ בְּגַרְמֵיהּ פְּגִימוּ כְּלַל, וְהָא אִתְּמַר. וּבְגִין כַּךְ כְּתִיב בְּהֵ\"א.</p>\n<p>פָּתַח וְאָמַר, (תהילים קכ״ו:א׳) בְּשׁוּב יְיָ' אֶת שִׁיבַת צִיּוֹן הָיִינוּ כְּחוֹלְמִים. בְּשׁוּב יְיָ' אֶת שִׁיבַת, דָּא בְּגָלוּת בָּבֶל אִתְּמַר. דְּלָא אִשְׁתְּכָחוּ יַתִיר בְּגָלוּתָא אֶלָּא שִׁבְעִין שְׁנִין. דִּכְתִיב, (ירמיהו כ״ט:י׳) כִּי לְפִי מְלֹאת לְבָבֶל שִׁבְעִים שָׁנָה אֶפְקוֹד אֶתְכֶם. וּכְתִיב הָיִינוּ כְּחוֹלְמִים, מַאי כְּחוֹלְמִים. אֶלָּא הָא אַתְעֲרוּ חַבְרַיָּיא, דְּאִיכָּא שִׁבְעִין <Nonei></i>שְׁנִין בְּחֶלְמָא.</p>"],[9520012205,"<p>וְתָא חֲזֵי, כְּתִיב כִּי שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם. מַאן שִׁבְעַת יָמִים. הָא אִתְּמַר, הַהוּא אֲתַר עִלָּאָה, דְּהוּא כְּלָלָא דְּכָל שִׁיתָא אָחֳרָנִין, אִקְרֵי שִׁבְעַת יָמִים, וְאִקְרֵי תְּשׁוּבָה. תָּנֵינָן, מַאן דְּיָתִיב בְּתַעֲנִיתָא בְּשַׁבְּתָא, קוֹרְעִין לוֹ גְּזַר דִּינוֹ שֶׁל שִׁבְעִים שָׁנָה, וְשִׁבְעִין שָׁנָה אִינּוּן שֶׁבַע אַנְפֵּי מַלְכָּא, דְּאֲפִילּוּ אִסְתְּכָמוּ עָלֵיהּ (כלא) לְבִישׁ, הַהוּא גְּזַר דִּינָא אִתְקְרַע. מַאי טַעְמָא. בְּגִין דְּאָחִיד בֵּיהּ בְּהַהוּא יוֹמָא, בִּכְלָלָא דְּכֻלְּהוּ, דְּאִקְרֵי שִׁבְעָה, וְאִקְרֵי תְּשׁוּבָה, בְּגִין כַּךְ בְּכֻלְּהוּ אָחִיד, וְאַהְדָּר בִּתְשׁוּבָה, וְאִתְקְרַע גְּזַר דִּינָא בְּכֻלְּהוּ. וְעַל דָּא וַדַּאי שִׁבְעִין שְׁנִין אִיכָּא בְּחֶלְמָא.</p>\n<p>כְּגַוְונָא דָּא, כַּהֲנָא אִתְעֲטָּר בְּשֶׁבַע, דְּאִקְרֵי שִׁבְעַת יָמִים, אִי פָּגִים רֵישֵׁיהּ, הַהוּא שִׁבְעָה דְּאִיהוּ כְּלָלָא דְּכֻלְּהוּ, אַקְרַח מִנֵּיהּ כָּל הַהוּא קְדוּשָּׁא דְּכֻלְּהוּ, דְּשַׁרְיָא עָלֵיהּ. וְעַל דָּא אִזְדְּהָרוּ דְּלָא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם, וְיִשְׁתְּכָחוּ פְּגִימִין מִכֹּלָּא. וּבְגִין כָּךְ כַּהֲנָא בָּעֵי לְאִשְׁתַּכְּחָא בִּשְׁלִימוּ יַתִּיר מִכֹּלָּא, כָּל שֶׁכֵּן הַהוּא דְּאִיהוּ עִלָּאָה מְכֻּלְּהוּ.</p>\n<p>אָמַר רִבִּי אַבָּא, כָּאן בְּהֵ\"א תַּתָּאָה, כָּאן בְּהֵ\"א עִלָּאָה. כֹּהֵן גָּדוֹל דְּאִיהוּ עִלָּאָה מְכֻּלְּהוּ, בְּהֵ\"א עִלָּאָה. דִּכְתִּיב אֲשֶׁר יוּצַק עַל רֹאשׁוֹ שֶׁמֶן הַמִּשְׁחָה וּמִלֵּא אֶת יָדוֹ וְגוֹ'. וּמִלֵּא יָדוֹ דִּכְתִּיב שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם. כַּהֲנָא אָחֳרָא בְּה' תַּתָּאָה, דִּכְתִּיב, לֹא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם, וּכְתִיב בַּתְרֵיהּ, וְלֹא יְחַלְּלוּ שֵׁם אֱלֹהֵיהֶם. וְהַאי שֵׁם הָא יְדִיעָא אִיהוּ. וּבְגִין כָּךְ כְּתִיב, וְהַכֹּהֵן הַגָּדוֹל מֵאֶחָיו אֲשֶׁר יוּצַק עַל רֹאשׁוֹ שֶׁמֶן הַמִּשְׁחָה לִלְבּוֹשׁ אֶת הַבְּגָדִים, כְּמָה דְּאַמָרָן. וּבְגִין דְּאִיהוּ קַדִּישָׁא כְּגַוְונָא דִּלְעֵילָּא, כְּתִיב וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא.</p>"],[9520012206,"<p>רִבִּי אַבָּא פָּתַח וְאָמַר, (דניאל ט׳:ז׳) לְךָ יְיָ' הַצְּדָקָה וְלָנוּ בּוֹשֶת הַפָּנִים כְּהַיּוֹם הַזֶּה לְאִישׁ יְהוּדָה וּלְיוֹשְׁבֵי יְרוּשָׁלַ ם. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, וּמִגּוֹ רְחִימוּתָא דִּלְהוֹן, יָהַב לְהוּ אוֹרַיְיתָא דִּקְשׁוֹט, לְמִנְדַּע אָרְחָא דְּמַלְכָּא קַדִּישָׁא. וְכָל מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, כְּאִלּוּ אִשְׁתָּדַּל בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאוֹרַיְיתָא כֹּלָּא שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוִי. וּבְגִין כָּךְ מַאן דְּאִתְעַסָּק בְּאוֹרַיְיתָא, אִתְעֲסַּק בֵּיהּ בִּשְׁמֵיהּ, וּמַאן דְּאִתְרְחַק מֵאוֹרַיְיתָא, רְחִיקָא הוּא מְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>תָּא חֲזֵי, לְךָ יְיָ' הַצְּדָקָה, כְּמָה דְאַתְּ אָמֵר, (דברי הימים א כ״ט:י״א) לְךָ יְיָ' הַגְּדוּלָּה וְהַגְבוּרָה. מַאן צְדָקָה. אֲתַר דְּכָל אַנְפִּין נְהִירִין אֲחִידָן בֵּיהּ, וְהוּא אָחִיד בְּכֻלְּהוּ, וּבֵיהּ אִשְׁתְּכָחוּ. וְלָנוּ בּוֹשֶת הַפָּנִים אֲתַר דְּכָל אַנְפִּין נְהִירִין אִתְרַחֲקָן מִנֵּיהּ. צְדָקָה, אֱמֶת קְשׁוֹט, וּנְהוֹרָא דְּכֹלָּא, וּנְהוֹרָא דְּאַנְפִּין חֵידוּ דְּכֹלָּא. בּוֹשֶת, כִּסּוּפָא רְחִיקוּ דִּקְשׁוֹט מַאן דְּאַכְסִיף, בְּגִין דֶּאֱמֶת דְּאִיהוּ צְדָקָה, אִתְרְחַק מִנֵּיהּ. רְחִיקוּ דְּאַנְפִּין נְהִירִין.</p>\n<p>תָּא חֲזֵי, כַּהֲנָא עִלָּאָה בָּעֵי לְאִתְחֲזָאָה בִּשְׁפִּירוּ דְּאַנְפִּין, בִּנְהִירוּ דְּאַנְפִּין, בְּחֵידוּ יַתִּיר מִכֹּלָּא. וְלָא בָּעֵי לְאִתְחֲזָאָה בֵּיהּ עֲצִיבוּ וְרוּגְזָא, אֶלָּא כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא. זַכָּאָה חוּלָקֵיהּ, דְּעָלֵיהּ כְּתִיב, (במדבר י״ח:כ׳) אֲנִי חֶלְקְךָ וְנַחֲלָתְךָ. וּכְתִיב (דברים יח) יְיָ' הוּא נַחֲלָתוֹ. וְעַל דָּא בָּעֵי לְאִתְחֲזָאָה שְׁלִים בְּכֹלָּא, בְּגַרְמֵיהּ, בִּלְבוּשֵׁיהּ, דְּלָא יַפְגִּים גַּרְמֵיהּ כְּלַל, כְּמָה דְּאִתְּמַר. (האי איהו בתר נישואין וכו', עד לארעא דישראל דף רע\"ו ע\"א שיטה ד'. זהו קצת מאמר מרעיא מהימנא מצאתי בהעתק ונדפס באורך בפרשת כי תצא כי שם ביתו מאמר מתחיל וענשו אותו)</p>"],[9520012207,"<p>(ויקרא כ״א:י״ג) וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח. רִבִּי שִׁמְעוֹן פָּתַח, (דברים כ״ב:י״ז) וְהִנֵּה הוּא שָׂם עֲלִילוֹת דְּבָרִים וְגוֹ'. וּכְתִיב וְעָנְשׁוּ אוֹתוֹ מֵאָה כֶסֶף וְגוֹ', כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל, וְכִי בְּתוּלַת יִשְׂרָאֵל הִיא, בְּתוּלַת אָבִיהָ, אוֹ בְּתוּלַת בַּעְלָהּ הִיא, מַהוּ <Nonei></i>בְּתוּלַת יִשְׂרָאֵל הָכָא. הֲדָא הוּא דִּכְתִיב, (דברים ל״ב:ז׳) שְׁאַל אָבִיךָ וְיַגֵדְךָ זְקֵנֶיךָ וְיֹאמְרוּ לָךְ. אוּף הָכָא כַּהֲנָא דְּקָאִים כְּגַוְונָא דִּלְעֵילָּא, כְּתִיב וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח, הָכִי נָמֵי בִבְתוּלֶיהָ, דְּלָא תִּפוּק מִבָּבָא דְּחַצֵרָהּ מִזִּמְנָא לְבַר, וְהָא אִתְּמַר.</p>"],[9520012208,"<p>רִבִּי שִׁמְעוֹן הֲוָה אָזִיל בְּאָרְחָא, וַהֲווּ עִמֵּיהּ רִבִּי יְהוּדָה ורִבִּי יוֹסֵי ורִבִּי חִזְקִיָּה. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים קי״א:ה׳) טֶרֶף נָתַן לִירֵאָיו יִזְכּוֹר לְעוֹלָם בְּרִיתוֹ. טֶרֶף נָתַן לִירֵאָיו, אִלֵּין אִינּוּן זַכָּאִין, אִינּוּן דַּחֲלֵי דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּכָל מַאן דְּדָחִיל לֵיהּ, אִתְקְרֵי מֵאִינְשֵׁי דְּבֵיתָא דְּמַלְכָּא, וְעָלֵיהּ כְּתִיב, (תהילים קי״ב:א׳) אַשְׁרֵי אִישׁ יָרֵא אֶת יְיָ'.</p>\n<p>מַהוּ טֶרֶף נָתַן לִירֵאָיו. אֶלָּא כְּמָה דִּכְתִיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ. מֵהָכָא אוֹלִיפְנָא, דְּכָל בַּר נָשׁ דְּלָעֵי בְּאוֹרַיְיתָא בְּלֵילְיָא, וְקָם בְּפַלְגוּת לֵילְיָא, בְּשַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל אִתְעֲרַת לְאַתְקְנָא בֵּיתָא לְמַלְכָּא, הַאי אִשְׁתְּתַּף בַּהֲדָהּ, וְהַאי אִקְרֵי מִבֵּי מַלְכָּא, וְיָהֲבִין לֵיהּ כָּל יוֹמָא מֵאִינּוּן תִּיקוּנֵי בֵּיתָא, הֲדָא הוּא דִכְתִיב וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. מַאן בֵּיתָה. כָּל אִינוּן דְּמִשְׁתַּתְפֵי בַּהֲדָה בְּלֵילְיָא, אִקְרוּן בֵּיתָהּ, בְּנֵי בֵּיתָהּ. וּבְגִין כַּךְ טֶרֶף נָתַן לִירֵאָיו.</p>\n<p>מַהוּ טֶרֶף. טֶרֶף מַמָשׁ, דְּאִיהִי נַטְלָא מֵאֲתַר רְחִיקָא עִלָּאָה, דִּכְתִיב (משלי ל״א:י״ד) מִמֶּרְחָק תָּבִיא לַחְמָהּ. וּמַאן זָכֵי לְהַאי טֶרֶף, סוֹפֵיהּ דִּקְרָא אוֹכַח, דִּכְתִיב, (תהילים קי״א:ט׳) יִזְכּוֹר לְעוֹלָם בְּרִיתוֹ. מַאן דְּאִסְתַּכַּל (ס\"א דאשתדל) בְּאוֹרַיְיתָא, לְאִשְׁתַּתְּפָא בַּהֲדָהּ בְּלֵילְיָא. וְלָא עוֹד, אֶלָּא דְּצַדִּיק חַד עִלָּאָה אִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהוּא אִשְׁתְּתַּף בַּהֲדֵיהּ, וְיָרְתִין תַּרְוַויְיהוּ לִכְנִישְׁתָּא דְּיִשְׂרָאֵל, דִּכְתִּיב, (ישעיהו ס׳:כ״א) צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>"],[9520012209,"<p>תּוּ פָּתַח וְאָמַר, (ויקרא כ״א:ט״ו) וְלֹא יְחַלֵּל זַרְעוֹ בְּעַמָּיו כִּי אֲנִי יְיָ' מְקַדְּשׁוֹ. תָּא חֲזֵי, כָּל מַאן דְּאַפִּיק זֶרַע לְבַטָּלָה, לָא זָכֵי לְמֶחמֶי אַפֵּי שְׁכִינְתָּא, וְאִקְרֵי רָע, דִּכְתִיב (תהילים ה׳:ה׳) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגוּרְךָ רָע. הַאי מַאן דְּאַפִּיק לֵיהּ בִּידֵיהּ, אוֹ בְּאִנְתּוּ אָחֳרָא דְּלָא כַּשְׁרָא. וְאִי תֵּימָא דְּאַפִּיק לֵיהּ בְּאִנְתּוּ דְּלָא מִתְעַבְּרָא, הָכִי נָמֵי. לָא. אֶלָּא כְּמָה דְּאַמָרָן.</p>\n<p>וְעַל דָּא יִבְעֵי בַּר נָשׁ מִקוּדְשָׁא בְּרִיךְ הוּא, דְּיַזְמִין לֵיהּ מָאנָא דְּכַשְׁרָא, דְּלָא יַפְגִים זַרְעֵיהּ, מַאן דְּאַפִּיק זַרְעָא בְּמָאנָא דְּלָא כַּשְׁרָא, פָּגִים לֵיהּ לְזַרְעֵיהּ, וַוי לְמַאן דְּפָגִים זַרְעֵיהּ. וּמַה בִּשְׁאָר בְּנֵי נָשָׁא כַּךְ, בְּכַהֲנָא דְּקָאִים לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא בִּקְדוּשָּׁה עִלָּאָה, עַל אַחַת כַּמָה וְכַמָּה.</p>\n<p>בְּעַמָּיו, מַהוּ בְּעַמָּיו. דְּהָא כְּתִיב לְעֵילָּא, אַלְמָנָה וּגְרוּשָׁה וַחֲלָלָה זוֹנָה אֶת אֵלֶּה לֹא יִקָּח, וּכְתִּיב וְלֹא יְחַלֵּל זַרְעוֹ בְּעַמָּיו. בָּהֶם מִבָּעֵי לֵיהּ, מַהוּ בְּעַמָּיו. אֶלָּא מִלָּה דָּא קְלָנָא בְּעַמָּיו, פְּגִימוּ בְּעַמָּיו, וְעַל דָּא כְּתִיב, כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה, מֵעַמָיו וַדַאי, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא, כִּי אֲנִי ה' מְקַדְּשׁוֹ, מַהוּ מְקַדְּשׁוֹ. אֶלָּא אֲנָא הוּא הַהוּא, דְּאִיהוּ מְקַדֵּשׁ לֵיהּ בְּכָל יוֹמָא, וּבְגִין כַּךְ לָא יַפְגִּים זַרְעֵיהּ, וְלָא יִשְׁתְּכַח בֵּיהּ פְּגִימוּ. (ס\"א ובגין דא) דְּהָא אֲנִי יְיָ' מְקַדְּשׁוֹ דַּאֲנָא בָּעֵינָא לְקַדְּשָׁא לֵיהּ וְיִשְׁתְּכַח קַדִּישָׁא בְּכֹלָּא, דְּקַדִּישָׁא יִשְׁתַּמֵּשׁ עַל יְדָא דְּקַדִּישָׁא.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא <Nonei></i>יִשְׁתַּמֵּשׁ עַל יְדֵי דְּכַהֲנָא, וְיִשְׁתְּכַח קַדִּישָׁא כַּד אָתֵי לְשַׁמְּשָׁא, וּבְגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יִשְׁתַּמֵּשׁ עַל יְדָא דְּכַהֲנָא דְּאִיהוּ קַדִּישָׁא, כַּהֲנָא יִשְׁתַּמֵּשׁ עַל יְדֵי דְּדַכְיָא, דְּאִתְקַּדָּשׁ בְּדַכְיוּתֵיהּ, וּמַאי אִיהוּ. לֵיוָאֵי. בַּר נָשׁ (כהנא) אָחֳרָא, יִשְׁתַּמֵּשׁ עַל יְדֵי דְּקַדִּישָׁא אָחֳרָא, בְּגִין דְּיִשְׁתַּכְחוּן כֹּלָּא בִּקְדוּשָּׁא, לְשַׁמְּשָׁא לְּקוּדְשָׁא בְּרִיךְ הוּא. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, דְּעָלַיְיהוּ כְּתִיב, (ויקרא כ׳:כ״ו) וָאַבְדִיל אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי. כַּמָה פְּרִישָׁן יִשְׂרָאֵל מִכֹּלָּא, בִּקְדוּשָּׁה, לְשַׁמְּשָּׁא לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי אֲנִי יְיָ' אֱלֹהֵיכֶם.</p>\n<p>תּוּ פָּתַח וְאָמַר, (תהילים ג׳:ט׳) לַיְיָ' הַיְשׁוּעָה עַל עַמְּךָ בִרְכָתֶךָ סֶּלָה. לַיְיָ' הַיְשׁוּעָה. הָכִי תָּנֵינָן, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דִּבְכָל אֲתַר דְּאִתְגָּלוּ, שְׁכִינְתָּא אִתְגַּלְיָיא בַּהֲדַיְיהוּ. כַּד יִפְּקוּן יִשְׂרָאֵל מִגָּלוּתָא, פּוּרְקָנָא לְמַאן, לְיִשְׂרָאֵל אוֹ לְּקוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא הָא אוּקְמוּהָ בְּכַמָּה קְרָאֵי, וְהָכָא, לַיְיָ' הַיְשׁוּעָה וַדַּאי, אֵימָתַי. עַל עַמְּךָ בִרְכָתֶךָ סֶּלָה. בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יַשְׁגַּח בְּבִרְכָאן עָלַיְיהוּ דְּיִשְׂרָאֵל, לְאַפָּקָא לוֹן מִן גָּלוּתָא, וּלְאוֹטָבָא לְהוּ, כְּדֵין לַיְיָ' הַיְשׁוּעָה וַדַּאי. וְעַל דָּא תָּנֵינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא יֵיתוּב עִמְּהוֹן דְּיִשְׂרָאֵל מִן גָּלוּתָא, הֲדָא הוּא דִכְתִיב, (דברים ל׳:ג׳) וְשָׁב יְיָ' אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחֲמֶךָ.</p>"],[9520012210,"<p><Nonei></i><Noneb>רעיא מהימנא</b> כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה, פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר, פִּקּוּדָא דָּא, לְמֵיסַב כַּהֲנָא רַבָּא בְּתוּלְתָא, הֲדָא הוּא דִכְתִיב אַלְמָנָה וּגְרוּשָׁה וַחֲלָלָה זוֹנָה אֶת אֵלֶּה לֹא יִקָּח כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה. וַאֲמַאי בָּעֵינָן דְּלָא יִסַּב אֶלָּא בְּתוּלְתָא בְּלָא פְּגִימוּ. אֶלָּא, אִתְּתָא אִיהִי כּוֹס דִּבְרָכָה, טָעֲמוּ פְּגָמוֹ. וְכַהֲנָא דְּקָרִיב קָרְבְּנָא קֳדָם יְיָ', בָּעֵי דְּלִהֱוִי אִיהוּ שְׁלִים, בְּלָא פְּגִימוּ, שְׁלִים בְּאֵבָרוֹי בְּלָא פְּגִימוּ, דְּמוּמִין פַּסְלִין בְּכַהֲנַיָא. שְׁלִים בְּגוּפֵיהּ, שְׁלִים בְּנוּקְבֵיהּ, לְקַיְּימָא בֵּיהּ, (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ.</p>\n<p>דְּקָרְבְּנָא מִנְחָה אִיהוּ, וּצְּרִיכִין יִשְׂרָאֵל לְמִשְׁלַח מִנְחָתָא דִּלְהוֹן לְמַלְכָּא, בִּגְבַר (בגוף) שְׁלִים. דְּאִינּוּן בְּהִפּוּכָא דְּסִטְרָא אָחֳרָא, דְּהָא בְּיַד אִישׁ עִתִּי פָּגִים, הֲווֹ שַׁלְחִין לֵיהּ דּוֹרֹנָא, דִּכְתִיב (ויקרא ט״ז:ח׳) גּוֹרָל אֶחָד לַיְיָ' וְגוֹרָל אֶחָד לַעֲזָאזִל. דֶּאֱלֹהִים אֲחֵרִים כֻּלְּהוּ פְּגִימִין מִסִּטְרָא דְּצָּפוֹן וְהָכִי רוּבָּא דְּבָתֵי עֲבוֹדָה זָרָה הֵם פְּגִימִין, בְּנוּקְבָּא דִּלְהוֹן, חוּרְבָא, לִילִית, פְּגִימוּתָא וְכוּ'.</p>\n<p>(ס\"א ורעיא מהימנא) אִיהוּ ו' מָלֵּא וְאִיהוּ בְּסִדוּרָא דָּא יְה\"וּ. ה' בַּתְרָאָה, כּוֹס מָלֵּא בִּרְכַּת ה', מִסִּטְרָא דִּימִינָא וּמִסִּטְרָא דִּגְבוּרָה דְּאִיהוּ דִּינָא, שְׁכִינְתָּא אִתְקְרִיאַת הוי\"ה, הֲדָא הוּא דִכְתִיב, (שמות ט׳:ג׳) הִנֵּה יַ\"ד יְדוָֹ\"ד הוֹיָה בְּמִקְנְךָ אֲשֶׁר בַּשָּׂדֶה. קָם רַעְיָא מְהֵימְנָא, וְאִשְׁתְּטַח קַמֵּיהּ. וְאָמַר זַכָּאָה חוּלָקִי דְּמַטְרוֹנִיתָא דְּמָארֵי (ומטרוניתא) אִינְהוּ בְּעֶזְרִי. (ע\"כ רעיא מהימנא)</p>"],[9520012211,"<p><Nonei></i>(ויקרא כ״א:י״ז) אִישׁ מִזַּרְעֲךָ לְדוֹרוֹתָם אֲשֶׁר יִהְיֶה בּוֹ מוּם. רִבִּי יִצְחָק אָמַר, בְּגִין דְּאִיהוּ פָּגִים, וּמַאן דְּאִיהוּ פָּגִים, לָא אִתְחֲזֵי לְשַׁמְּשָׁא בְּקוּדְשָׁא. וְהָא אוּקְמוּהָ, דְּבַּר נָשׁ דְּאִשְׁתְּכַח פָּגִים, לֵית בֵּיהּ מְהֵימְנוּתָא, וְהַהוּא פְּגִימוּ אַסְהִיד עָלֵיהּ, כָּל שֶׁכֵּן כַּהֲנָא, דְּבַעְיָא לְאִשְׁתַּכְחָא שְׁלִים, מָארֵיהּ דִּמְהֵימְנוּתָא, יַתִיר מִכֹלָּא, וְהָא אוּקְמוּהָ.</p>\n<p>רִבִּי אֶלְעָזָר הֲוָה יָתִיב בְּקִסְטְרָא דְּבֵי חָמוּי, וְהוּא הֲוָה אָמַר, זִילְגָא דִּבְקִסְטִירָא בְּעֵיטָא שְׁכִיחַ. אַדְהָכִי, אַעְבָר חַד בַּר נָשׁ, פָּגִים מְעֵינֵיהּ חַד. אָמַר חָמוּי, נִשְׁאַל לְהַאי. אָמַר, פָּגִים הוּא, וְלָאו מְהֵימָנָא. אָמַר, נִשְׁאַל בַּהֲדֵיהּ. אָתוּ שְׁאִילוּ לֵיהּ. אָמַר לֵיהּ, טוּפְקָא מַאן הוּא בְּעָלְמָא. אָמַר עֲתִירָא, אֲבָל דְּיַשְׁלִיף, בַּהֲדֵיהּ אֲנָא מִכֻּלְּהוּ. (ס\"א עתירא, אבל דישליף, ווי על דא, בהדיה אנא מכלהו) אָמַר רִבִּי אֶלְעָזָר, בְּמִלּוֹי אִשְׁתְּמַע, דְּלָאו מְהֵימְנוּתָא גַּבֵּיהּ, וְלָאו בַּר מְהֵימָנָא הוּא. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אָמַר כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב, דְּהָא קְדוּשָּׁא דִּלְעֵילָּא, לָא שַׁרְיָא בַּאֲתַר פָּגִים.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו ח׳:כ׳) לְתוֹרָה וְלִתְעוּדָה אִם לֹא יֹאמְרוּ כַּדָּבָר הַזֶּה. לְתוֹרָה וְלִתְעוּדָה. מַאן הוּא תּוֹרָה, וּמַאן הוּא תְּעוּדָה. אֶלָּא תּוֹרָה, דָּא תּוֹרָה שֶׁבִּכְתָּב. תְּעוּדָה, דָּא תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבְּעַל פֶּה לָא שַׁרְיָא בַּאֲתַר פָּגִים, דְּהָא מִתּוֹרָה שֶׁבִּכְתָּב אִתְבְּנֵי. כְּתִיב צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמּוּדָי, צוֹר תְּעוּדָה, דָּא תּוֹרָה שֶׁבְּעַל פֶּה, בְּגִין דְּתַמָּן אִתְּצַר צְרוֹרָא דְּחַיֵּי, וּבִתְעוּדָה אִתְקְשַׁר קִשְׁרָא דְּחַיֵּי (נ\"א קשרא דמהימנותא) דִּלְעֵילָּא, לְמֶהֱוִי כֹּלָּא חַד.</p>\n<p>וּמִתַּמָּן לְתַתָּא אִתְפָּרְשָׁן אוֹרְחִין וּשְׁבִילִין, וּמִתַּמָּן מִתְפָּרְשִׁין אוֹרְחִין בְּעָלְמִין כֻּלְּהוּ הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים.</p>\n<p>חֲתוֹם תּוֹרָה, חֲתִימָה דְּאוֹרַיְיתָא, דְּאִיהִי תּוֹרָה שֶׁבִּכְתָּב בְּאָן אֲתַר. בְּלִמּוּדָי, אִלֵּין נְבִיאֵי, כְּמָה דְאַתְּ אָמֵר (מלכים א ז׳:כ״א) וַיָּקֶם אֶת הָעַמּוּד הַיְמָנִי וַיִּקְרָא שְׁמוֹ יָכִין וַיָקֶם אֶת הָעַמּוּד הַשְּׂמָאלִי וַיִקְרָא שְׁמוֹ בּוֹעַז. וּמִתַּמָּן אִתְפָּרְשָׁן אוֹרְחִין לִנְבִיאֵי מְהֵימְנֵי, וְקַיְימֵי אִלֵּין בְּקִיּוּמָא לְגוּפָא, לְשִׁית טְהִירִין, הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:ט״ו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ. וְכֹלָּא לָא קַיְּימָא אֶלָּא בִּשְׁלִימוּ, וְלָא שַׁרְיָא קְדוּשָּׁה דְּכֹלָּא, אֶלָּא בִּשְׁלִימוּ, כַּד מִתְחַבְּרָאן דָּא בְּדָא, כֹּלָּא הוּא שְׁלִים, כֹּלָּא הוּא חַד, לָא אִתְפְּגִים אֲתַר. וְעַל דָּא אִקְרֵי כְּנֶסֶת יִשְׂרָאֵל שָׁלֵם, כְּמָה דְאַתְּ אָמֵר (בראשית י״ד:י״ח) וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם (תהילים ע״ו:ג׳) וַיְהִי בְשָׁלֵם סֻכּוֹ.</p>\n<p>וּבְגִין כַּךְ לָא שַׁרְיָא כֹּלָּא, אֶלָּא בַּאֲתַר שְׁלִים. וְעַל דָּא כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. כְּגַוְונָא דָּא קָרְבְּנָא דְּבֵיהּ מוּמָא לָא יִתְקְרִיב. מַאי טַעְמָא. דִּכְתִּיב כִּי לֹא לְרָצוֹן יִהְיֶה לָכֶם. וְאִי תֵּימָא הָא קוּדְשָׁא בְּרִיךְ הוּא לָא שָׁארֵי אֶלָּא בַּאֲתַר תְּבִירָא, בְּמָאנָא תְּבִירָא, דִּכְתִּיב, (ישעיהו נ״ז:ט״ו) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. הַאי אֲתַר שְׁלִים יַתִּיר הוּא מִכֹּלָּא, (דכתיב, (ישעיהו נ״ז:ט״ו) ואת דכא ושפל רוח) בְּגִין דְּמָאִיךְ גַּרְמֵיהּ לְמִשְׁרֵי עָלֵיהּ גָּאוּתָא דְּכֹלָּא, גָּאוּתָא עִלָּאָה, וְדָא הוּא שְׁלִים. אֲבָל לָא כְּתִיב, ואֶת <Nonei></i>עִוִּר וְשָׁבוּר וְחָרוּם וְשָׂרוּעַ. אֶלָּא וְאֶת דַּכָּא וּשְׁפַל רוּחַ, מַאן דְּמָאִיךְ גַּרְמֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא זָקִיף לֵיהּ.</p>\n<p>וּבְגִּינֵי כַּךְ, כַּהֲנָא דְּקָאִים לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא, בָּעֵי לְמֶהֱוִי שְׁלִים יַתִּיר מִכֹּלָּא, וְלָא יִתְחֲזֵי פָּגִים, וְעַל דָּא אַזְהַר לְהוּ לְכַהֲנֵי, דִּכְתִּיב אִישׁ מִזַּרְעֲךָ לְדוֹרוֹתָם אֲשֶׁר יִהְיֶה בוֹ מוּם.</p>\n<p>תּוּ פָּתַח וְאָמַר, (מלאכי א׳:ח׳) וְכִי תַגִּישׁוּן עִוִּר לִזְבּוֹחַ אֵין רָע, וְכִי תַגִּישׁוּ פִסֵּחַ וְחוֹלֶה אֵין רָע, וְכִי קוּדְשָׁא בְּרִיךְ הוּא אָמַר אֵין רָע, אִי הָכִי טוֹב הוּא. אֶלָּא סוֹפֵיהּ דִּקְרָא אוֹכַח, דְּיִשְׂרָאֵל בְּאִינּוּן יוֹמִין הֲווֹ מְמָנָן כַּהֲנֵי מָארֵי דְּמוּמִין, עַל גַּבֵּי מַדְבְּחָא, וּלְשַׁמְּשָׁא עַל מַקְדְּשָׁא, וְאַמְרֵי מַאי אִכְפַּת לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא דָּא, אוֹ אָחֳרָא. וְאִינּוּן הֲווֹ דְּאַמְרֵי אֵין רָע. וְקוּדְשָׁא בְּרִיךְ הוּא אָתִיב לְהוֹן הַהִיא מִלָּה דַּהֲווֹ אַמְרֵי. אָמַר: יִשְׂרָאֵל אַתּוּן אַמְרֵי כַּד מְקָרְבֵי מָארֵי דְּמוּמִין עַל פּוּלְחָנִי אֵין רָע, מַאי אִכְפַּת לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>סוֹפֵיהּ דִּקְרָא מַה כְּתִיב, הַקְרִיבֵהוּ נָא לְפֶחָתְךָ הֲיִרְצְךָ אוֹ הֲיִשָּׂא פָנֶיךָ. בַּר נָשׁ מִנַּיְיכוּ, אִי בָּעִיתוּ לְשַׁלוּמֵי לְמַלְכָּא, וּלְקָרְבָא קַמֵּיהּ דּוֹרוֹנָא, אַתּוּן מְשַׁדְרִין לֵיהּ בִּפְגִימָא, אוֹ לָא. הֲיִרְצְךָ אוֹ הֲיִשָּׂא פָנֶיךָ בְּהַהוּא דּוֹרוֹנָא, כָּל שֶׁכֵּן וְכָּל שֶׁכֵּן דְּאַתּוּן מְקָרְבִין קָמַאי בַּר נָשׁ פָּגִים לְקָרְבָא דּוֹרוֹנָא, הָא דּוֹרוֹנָא דִּלְכוֹן לְכַלְבָּא אִתְמְסַר, דְּוַדַּאי בַּר נָשׁ דְּאִיהוּ פָּגִים, פָּגִים הוּא מִכֹּלָּא, פָּגִים הוּא מְהֵימְנוּתָא. וְעַל דָּא כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב.</p>\n<p>אָמַר רִבִּי יוֹסֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַשְׁלְמָא לְהוּ לְיִשְׂרָאֵל, וּלְאִשְׁתַּכְּחָא שְׁלֵימִין בְּכֹלָּא, דְּלָא יְהֵא בְּהוֹן מָארֵי דְּמוּמִין כְּלַל, בְּגִין דִּיהוֹן תִּקּוּנָא דְּעָלְמָא, כְּאִלֵּין מָאנֵי וּלְבוּשָׁא דְּבַּר נָשׁ דְּאִינּוּן תִּקּוּנָא דְּגוּפָא, הֲדָא הוּא דִכְתִיב (איוב ל״ח:י״ד) ויִתְיַצְּבוּ כְּמוֹ לְבוּשׁ.</p>\n<p>(ס\"א ד\"א) תָּא חֲזֵי, כַּד יִתְּעֲרוּן מֵעַפְרָא, כְּמָה דְּעָאלוּ, הָכִי יְקוּמוּן, חִגְרִין אוֹ סוּמִין. עָאלוּ חִגְרִין וְסוּמִין, יְקוּמוּן בְּהַהוּא לְבוּשָׁא, דְּלָא יֵימְרוּן דְּאָחֳרָא הוּא דְּאִתְּעַר. וּלְבָתַר, קוּדְשָׁא בְּרִיךְ הוּא יֵיסֵי לוֹן, וְיִשְׁתַּכְחוּן שְׁלֵימִין קַמֵּיהּ, וּכְדֵין יְהֵא עָלְמָא שְׁלִים בְּכֹלָּא, כְּדֵין (זכריה י״ד:ט׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9520012212,"<p>(ויקרא כ״ב:כ״ז) שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז כִּי יִוָּלֵד וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ וְגוֹ'. רִבִּי יוֹסֵי פָּתַח, (תהילים ל״ו:ז׳) צִדְקָתְךָ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אֲבָל תָּא חֲזֵי, צֶדֶק: כִּתְרָא קַדִישָׁא עִלָּאָה. כְּהַרְרֵי אֵל: כְּאִינּוּן טוּרִין עִלָּאִין קַדִּישִׁין, דְּאִקְרוּן טוּרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא. וּבְגִין דְּאִיהִי סַלְּקָא לְאִתְקַשְּׁרָא בְּהוּ לְעֵילָּא, כָּל דִּינָהָא בְּשִּׁקוּלָא חֲדָא לְכֹלָּא, דְּלֵית בְּהַהוּא דִּינָא רַחֲמֵי. מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה. מִשְׁפָּט דְּאִיהוּ רַחֲמֵי, נָחִית לְתַתָּא לְהַהוּא דַּרְגָּא לְתַקְּנָא עָלְמִין, וְחָיֵיס עַל כֹּלָּא, וְעָבִיד דִּינָא בְּרַחֲמֵי לְבַסְּמָא עָלְמָא.</p>\n<p>וּבְגִין דְּאִיהוּ רַחֲמֵי, אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. לְכֹלָּא בְּשִּׁקוּלָא חֲדָא. אָדָם וּבְהֵמָה, הָא אוּקְמוּהָ, מַאן דְּהוּא אָדָם, וְשַׁוִּי לְגַרְמֵיהּ כַּבְּהֵמָה. אָדָם וּבְהֵמָה: דִּין אָדָם, וְדִין בְּהֵמָה, חַד הוּא. אָדָם: (בראשית י״ז:י״ב) וּבֶן שְׁמֹנַת יָמִים יִמּוֹל לָכֶם כָּל זָכָר. בְּהֵמָה: וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ וּמִיוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה לְקָרְבַּן אִשֶּׁה לַיְיָ', בְּגִין דִּיעָבַר עָלַיְיהוּ שַׁבָּת חַד, וְהָא (הקדמה י\"ג) אוּקְמוּהָ.</p>"]]});
